/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20131105-6","meetingId":"h25-cm11","date":"2013年11月5日","dateIso":"2013-11-05","committee":"区民委員会","time":"午後 １時００分～午後 ３時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２５年度、協働事業提案制度の審査結果","agenda":"平成２５年度、協働事業提案制度の審査結果","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"私は区政の方針を決定する際に住民参加を位置づけて、住民意見の表明や参加を保障する仕組みが協働だというふうに思いますけど、どうも区が考える協働というのは、ちょっと私の思いとは違うところがあるのか、違うのか、要するに行政が進めたいものに対して民間に担っていただくと。","respondent":"寺嶋協働・国際担当課長","answer":"それにつきましては、この協働事業が始まって５年以上経過しますけれども、さまざまな手法を用いまして実施してきたというふうに認識しています。","voiceIndex":9,"id":"exchange-001"},{"speaker":"中塚委員","kind":"提案","question":"二つ目は、そうはいっても、委託事業だからハードルをしっかり定めていかないといけないと、それはそうなのかもしれないのですけども、やはり基本構想の理念の一つと大きく位置づけている協働の中の一つの事業ということですけども、もっといろんな生活の中で、区政の中でいろんな幅広い中で、こういうのがこういう解決方法があるのではないか、いや、こういうやり方はどうなんだ。","respondent":"寺嶋協働・国際担当課長","answer":"この事業につきましては、平成２０年度から実施しておりまして、かつては区民提案という形もありましたけれども、実際のところ、区民活動助成が始まった段階で、やはりハードルの高さというか、独自性でちょっとチャレンジしてみたい事業といったものが多く。","voiceIndex":11,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"区としては、要するに解決が必要だとしている事業で、担い手が見つからなかった場合は、要するにどうするのかということですけど、といっても必要なわけですから、区で責任を持って今後方向を考えていくのか、それとも、いやそうではなくて、担い手を引き続き探していくというスタンスなのか、行政の役割として必要だというのであれば、僕も必要だと思うだけに、では区のほうでやるのか。","respondent":"寺嶋協働・国際担当課長","answer":"その中でも、区の職員としてのアイデア、発想なども一つの報告として出されたものですけれども、あえてそれを所管のほうから一般区民の方の斬新な考え、新しいアイデアも欲しいということで、今回区民の方向けに提案させていただいたという趣旨ですので。","voiceIndex":13,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"提案","question":"区が提起する課題のこの三つですけど、これはなぜこの三つなのか、今回提案を求めていったのかというのが見えてこないのですけど、その辺の考え方を教えていただきたいと思います。それと、来年度に委託事業になるようなことを課長から今お話をいただきましたけど、来年度の提案と、予算はこれからなのであれですが、大体どのくらいの予算を見込んでいるのかを教えてください。よろしくお願いします。","respondent":"寺嶋協働・国際担当課長","answer":"外国人を対象にした２団体で採択、不採択の団体の違いといったご質問ですけれども、審査会で一番のポイントになったのは、採択になったほうは、ちょっとこれもすみません、先ほどと重複する部分がありますけれども、まずこの団体は、いろんな講座を既に実施している団体で。","voiceIndex":15,"id":"exchange-004"},{"speaker":"石田（し）委員","kind":"意見","question":"人とペットが共存できる公園の環境づくりというのは、区が積極的に取り組んでいるものだったかというのが、確かに戸越公園とかで、今どちらかというと実験的というか、取り組みをしていただいて、非常に僕はうれしく思っているのですが、区がこういう課題があって、こういうのをやっていきますという積極的に出している活動に、ここはあまり入っていないのではないかと思いますけど、その辺の考え方を。","respondent":"寺嶋協働・国際担当課長","answer":"大変失礼しました。先ほど答弁漏れがございましたので、あわせてご説明いたします。","voiceIndex":17,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"提案","question":"最後にしますけど、よくわかりました。特に3)は地域でもいろいろな、両方の意見があるところなので、逆に行政だけではなくて、地域にお伺いをしながら進めていくというのは非常にいいことだと思うので、よくわかりました。審査会の意見はごもっともで、これを地域に投げて提案をさせるということ自体が、僕は、〔「容易ではない」と呼ぶ者あり〕非常に、容易ではなくて、不可能に近い。","respondent":"寺嶋協働・国際担当課長","answer":"区のほうでも、さまざまな検討を重ねて、取り組みを進めているところではありますけれども、その中の一つで、例えばこういった活動を中心にやっている団体とか、そういった方が何か独自のアイデアを出していただいて、一つの解決策としてご提案いただければ。","voiceIndex":19,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"区長、この間、金曜日か土曜日か、偶然きゅりあんで区長にお会いしました。タウンミーティングをやっていますよ。課長の答弁は、いろいろな中にある一つですという答弁が来ると思いますけれども、こういう形で行政と例えば議会が両輪だとかというお話でやってきて、一生懸命やっているのに、まだこういうことをある意味、こういう事業を新しくやっていかないと足りないものですかね。質問です。","respondent":"寺嶋協働・国際担当課長","answer":"何よりも区の理念とかにあります区と区民との協働というのがありまして、この協働というものを推進していく上で、あえて協働事業という形で区民の方に見えるような形でご提案させていただいて、協働を推進していくというキーワードのもとに。","voiceIndex":21,"id":"exchange-007"},{"speaker":"藤原委員","kind":"提案","question":"本当に一生懸命やっているではないですか、地域のために。ここに出ると、私個人としてはまだ足りないのかという思いがどうしても出てしまうのですよね。それがまず１点。それと、さっき課長の答弁の中で、いろんな課に何か提案はありませんかと投げたという形ですけれども、ちょうど(1)の2)、これは山崎ものづくり・経営支援課長のところですよね。","respondent":"山崎ものづくり・経営支援課長","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-008"},{"speaker":"藤原委員","kind":"提案","question":"これをどうですかと投げてどうするのという思いがあるのですけれども、投げかけて、これが採択されて戻ってきたときに、どうするのですか。所管がこういうふうにやるならいいのですけど、地域活動課の国際担当が採択というか、決めたのを、こういうふうになりましたからと所管に落としてしまうのですか。いいのですか、それで。今やってきているシステムはいいと思うので、その辺についてはいかがでしょうか。","respondent":"寺嶋協働・国際担当課長、山崎ものづくり・経営支援課長","answer":"若年層、公園も含めまして、それぞれの所管はそれぞれの所管として解決策を考えて、いろんな取り組みについては実施しているということで、先ほども申し上げましたように、いろんな手法があって。それで、若者の雇用対策につきましては、区のほうの取り組みもここ一、二年できっちり対応していこうということで就業センター開設以来、就業関係をやってきております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"藤原委員","kind":"提案","question":"一生懸命提案してきたつもりですけどね。〔「課長から」と呼ぶ者あり〕そうですか。だけど、私も議員になって４期目ですから、いろんな、ああだこうだといろいろありつつ、つくってきた中で、こういうふうに出てくると、もっとやらなければいけないという思いが出てしまうので、その辺、何か課長、ばしっと答弁いただいて、そうではないのですよと打ち消すような答弁をいただけますか。","respondent":"寺嶋協働・国際担当課長、中川原地域振興事業部長","answer":"日ごろから委員の皆様方、それから町会の皆様方に多大なるご支援をいただき、また区政について最大のご協力をいただいていることは重々認識しております。この協働事業提案制度というのは、提案制度ですけど、提案だけではなくて、このアイデアについて、私どもがやりますという、それのセットなのですね。ですので、区としましても、もちろん就業の問題にも取り組んでいます。","voiceIndex":28,"id":"exchange-010"}]},{"id":"topic-02","title":"の生鮮三品店支援事業","agenda":"の生鮮三品店支援事業","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回、シャッターの塗り替えということもありますけれども、おもしろいアイデアだというふうに思います。ぽつぽつですけども、商店街の目玉というか、活気につながると思いますけども、どういう経過や苦労の中で生まれたのか、狙いも含めて、もちろん小冊子を見させていただきましたけど、こういうところにこういうふうに使いたいと、その辺を改めて伺いたいと思います。これが１点です。","respondent":"米田商業・観光課長","answer":"大型店に対する規制というものは、現在大きなもので大規模小売店舗立地法ですとか特定商業施設の出店に伴なう周辺地域の生活環境の保全に関する要綱に基づいた地域住民への説明等が義務づけられたり、区の意見を求めたりというようなことがありますけれども、現在のところ。","voiceIndex":35,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０８カ所ある商店街の中で、何らかの生鮮三品があるのが５８店舗だというふうに伺いまして、何らかのということは、５５店舗、半分ぐらいが何もないというふうに思うと、本当に深刻だし、支援を広めていかなくてはいけないと思いますので、大型店とかかわって、区はこの点をどう考えているのか、半分が何らかのものがないというのは深刻だと私は思いますけれども、その点を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"大型小売店の代表も含めました産業振興懇談会という場もありますが、こちらにおいては、首長のほうより、やはり地域の商店街を大事にしながら、大型店のほうの出店を考えていってもらいたいというようなことが首長のほうからも、こちら。","voiceIndex":37,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう思いで、その場で大型店の代表者に説明をしたのか、改めてその気持ちを伺いたいと思います。先ほどご説明の中で、営業時間の話がありましたけれども、個人商店にとって営業時間を努力せよと言われても、従業員が限られているといいますか、家族でやっておりますから、朝早くから夜遅くまでというのは、そういう努力を求めるというよりも、大型店に営業時間の規制だったり、土日や祝日について。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"ああ、そうですね、ごめんなさい。先ほどの区長の狙いは改めて伺いたいと思います。どっちにしろ、この事業は大事な一歩だと思っています。商店街の話を聞いても、例えばシャッターは閉めて、テナントとして例えば貸したいと思っても、１階部分がテナントでも２階が住宅なので、トイレと台所が別々でないので貸せないと。区の支援策、今もあるのでしょうかね。ご説明いただきたいと思います。","respondent":"米田商業・観光課長","answer":"そういった意味で、大型店とはどうしても差別化し、なかなか競争というのも難しいですけれども、大型店に対抗していくというようなこと、そのために先ほどありましたけれども、空き店舗になってしまった商店に対しての分離改修の費用の助成等の制度を設けてあります。","voiceIndex":41,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"この生鮮三品店、公募の反響ですね。要するに生鮮三品店の盛り上がりといいますか、そういうプロセスに関してお伺いしたいのですけれど、どのような感じだったのでしょうか。","respondent":"米田商業・観光課長","answer":"７月の頭に広報に載せまして、各商店街のほうにもお願いして、店頭のチラシ等で、ぜひとも、私のまちの肉屋さん、魚屋さん、八百屋さんを推薦してくださいというようなことでの取り組みを続けてまいりました。","voiceIndex":43,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"やはり消費者側から見た意見等も入ってきていると思いますけれども、そういう意味で、テレビ番組のお話をお伺いしましたけれど、区側の認識としまして、新しい気づきとかそういうものはあったのでしょうか、その辺をちょっとお伺いしたい。","respondent":"米田商業・観光課長","answer":"そういった意味では、今回の生鮮三品の冊子のほうにもできるだけ顔が見えるような形で取材はしていただきましたけれども、地域の方々とそれから商店主の方々のつながり、こういうものをより深めていくことが、その個店とのつながり。","voiceIndex":45,"id":"exchange-016"},{"speaker":"吉田委員","kind":"意見","question":"そこで、ここにあります対象にならなかった、辞退と廃業等があったというお話で、全部で計算すると３２店舗ぐらいありますよね。そこを拾っていって、にぎわいがあるまちというのがこれから必要だと思いますけど、その辺、ちょっとお考えをお聞かせください。","respondent":"米田商業・観光課長","answer":"ご指摘のようにできるだけ拾っていきたいというふうにこちらも考えておりまして、区の商店街連合会も集計された結果をもとにそれぞれの個店にはきちんと働きかけてくださったというふうに認識しております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"山元委員","kind":"質問","question":"本当にこれを見ていて、今吉田委員もおっしゃっていましたけど、うちの町会のお店も出ていると思っていたのですけど、実際にこういう小冊子ができて、どのぐらいつくったのかということと、また各店舗等に配布するのでしょうけど、それ以外に何か活用していこうとかという何か予定というのはあるのでしょうか。","respondent":"米田商業・観光課長","answer":"また新たなＰＲの方法等についてはいろいろご意見を頂戴しながら進めてまいりたいと、このように考えてあります。","voiceIndex":49,"id":"exchange-018"},{"speaker":"山元委員","kind":"意見","question":"引っ越してきた人たちとか、本当にどこにお店があるかというのも知らない方もいるかと思いますが、このＰＲは区商連を中心にということでありますけれども、全然違った角度、例えば不動産屋さんというか、そういうところにまたアピールするというのも、こういうお店があるとかという、またちょっと角度を変えて、せっかくこのようなすごい冊子ができたので。","respondent":"米田商業・観光課長","answer":"今とりあえずある程度形にまとまったということでのご報告です。これをもとに、今後いろいろＰＲを展開するということは、ご説明で申し述べたとおりです。","voiceIndex":51,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。住所、電話番号は記載されていますけど。それで、ほかの、例えばそういった支援対象店を紹介するときには、区のホームページとかを使うわけではないですか。そこで見る人たちというのは、この冊子を見るというよりも、どちらかというと、ホームページから、こういうお店があるのかとアクセスをしてきますよね。","respondent":"米田商業・観光課長","answer":"それが今回こうやって必ずとりあえず名前は載せたというようなことで、そのお店は、お顔はわかっていたけど、こういうお店だったのだというようなことの一つのきっかけで、そういうような地道な取り組みをされているところが主ですので。","voiceIndex":53,"id":"exchange-020"}]},{"id":"topic-03","title":"ＭＥＴＡＬＥＸ２０１３品川パビリオンの出展","agenda":"ＭＥＴＡＬＥＸ２０１３品川パビリオンの出展","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、ＰＲのポイントというのはどこに置くのか、メード・イン・ジャパン、メード・イン・品川と、これが商談の中でなるほどと、目にとまるのというのは、また技術というのはなかなかすぐわかるようにアピールしていかなくてはいけないわけですから、独自策というのはどの辺に独自性を示すのか、どこをポイントにアピールしていくのか、そこを伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"我々区の職員はパビリオン全体をＰＲするということで、品川パビリオンのチラシを持ってやらせていただいたりとか、いろんな意味でとにかく当初わかってもらって目立つということが一番必要ですので、そうしたことに留意しながら。","voiceIndex":59,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"独自の味つけをしようと思って、独自のブースをつくったと。何を押し出すのかと。改めて何を押し出すのか、品川のものづくりの強さを、どこをＰＲして出していくのか、ぜひ高い技術、それをつくり出すネットワーク、バックヤードの強さ、そういうところが私は強みなのかというふうに思いますけれども、改めて伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"一口に言いますと、キャッチコピーとしましては、品川区は高品質、高技術に支えられ、産業の技術革新を起こしていく拠点だということで、イノベーションシティ品川というのがキャッチコピーになっておりますので。","voiceIndex":61,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"さっき言われた５回目ということですけど、自民党は１回目に参加させてもらって、行ってきました。そのときから出ている、ずっと５年間出ているのかわからないのだけど、１回目に出ていたら、何社か出ていると思いますけど、結果的にうまく事業がマッチングできているのかどうか、そこら辺が、今まであまり見えていないので、どのぐらいの状況になっているのか簡単に教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"パビリオンの出展につきましては、今回６社のうち、２社が新規で新たに行かれまして、それ以外の４社については２回目でありますとか、中には連続して毎年行かれていて、５回目というような企業もあります。","voiceIndex":63,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"かなり広い会場でやっているパビリオン、かなり広かったと思うのですね。ですから、ぜひうまくアピールしていただいて、成果を残してもらえるように頑張ってもらうのと、先ほどもありましたビジネスサポートセンター、あっちの利用もうまくこれからもやっていっていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-024"}]},{"id":"topic-04","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"裏面のオークランド市の件です。この前は、スポーツ交流で、野球とバスケットに来てもらっていましたけど、この雰囲気というか、どういうふうに伝わってきているのか、その辺を教えていただきたい。","respondent":"寺嶋協働・国際担当課長","answer":"これはオークランド市に限らず、そういった傾向が多くの都市に見られるというふうに認識しております。","voiceIndex":70,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"オークランド市は６年ぐらい前に品川から行きましたよね、友好団体と。その辺がなくなってしまうのかというのと、それからリンフィールド・カレッジでしたか、学校との、今も夏にやってもらっている、ある意味ではそっちに特化してしまうのかという感じがするのですけど、そうでもないのですか。","respondent":"寺嶋協働・国際担当課長","answer":"今ご指摘いただきましたリンフィールド・カレッジにつきましては、ある種民間レベル、友好協会を通してやっている事業でありまして、こちらについてはもちろん今後も引き続き継続していきますけれども、そちらにシフトしていくという考えは特になく。","voiceIndex":72,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"今のやりとりを伺っていたのですけど、都市と都市の交流について、先方から平和友好の交流については少しも否定するものはないのだけども、それぞれの分野についてオークランド市はこう考えているとか、いろいろ多分こういう分野はどうですか、こういう分野では何かできる方向はありますか、そういうふうに何か具体的に先方が伺っているみたいに今聞いていたのですけれども。","respondent":"寺嶋協働・国際担当課長","answer":"従来の交流のスタイル、現在も続いておりますけれども、今お話にあったように、スポーツ交流であるとか、それから周辺の行事であるとか、そういった形での行き来というものはもちろんございましたけれども、先ほど申し上げたいろんな得意分野に限って。","voiceIndex":74,"id":"exchange-027"},{"speaker":"山元委員","kind":"質問","question":"今各２３区の交流というタイトルですけど、実際品川区に東南アジア地域からアピールというか、今までなかったのでしょうか。交流しようよというのは変ですけども、何か言い方が変ですけど、そういう動きというのは全然なかったのですか。","respondent":"寺嶋協働・国際担当課長","answer":"私の知る範囲では、かつてたしか中国のハルビン市と教育後援ということがあったというふうに聞いておりますが、これも２０年以上前で文書が残っていないので、聞いた話という形になってしまうかもしれませんが、経済的な理由等で先方のほうから休止という形のお話があって。","voiceIndex":76,"id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"今はあちらからという話でしたけど、今度逆に品川区として、この都市と交流したいとかという思いというか、そういうものはお持ちではないのですか。","respondent":"寺嶋協働・国際担当課長","answer":"今の段階で、品川区としてどこかの都市と友好都市、姉妹都市の提携をしたいという形で今のところ考えているものはございません。","voiceIndex":78,"id":"exchange-029"},{"speaker":"石田（し）委員","kind":"質問","question":"今のとちょっと関係するのですが、聞いた中では、韓国のどこかの都市と何かちょっとやろうとしたけどというような、何となく、以前ね、何年か前にそういう話があったということを聞いたのですが、そういったのというのは、行政として把握をされているのかというのが１点と、先ほどの答弁の中で、いろんなところで友好しているけど。","respondent":"寺嶋協働・国際担当課長","answer":"ただ、そのことと、そのためにまた新しいところとあえて友好都市、姉妹都市という関係を持つことに、もし今後の展開としてそういったものが非常に重要だというような答えが出てくれば、それはそのときのまた検討になろうかと思いますけど。","voiceIndex":80,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"課長、いずれ検証ではなくて、検証はするべきなのですよ。検証しないといけないのです。だから、いずれ検証ではなくて、これは区民の意識調査をしていると思いますけれども、考えなくてはいけないなと思いますけれども、そこが１点。それと、私もそもそも論になってしまいますけれども、この国際友好をすることが、一般の品川区民にとって、どういうメリットがあるのか、明確に具体的に改めて教えてください。","respondent":"寺嶋協働・国際担当課長","answer":"先ほど申し上げましたいずれ検証というのは、国際交流のあり方についていずれ検証するということではなくて、基本的にはもちろんそれぞれの自治体のメリットというか意義を考えた上での交流をしていくというのは、今既に検証というか、検討もしておりますし。","voiceIndex":82,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"子どもたちの語学力も含めた国際友好というのは大事だということをものすごく前面に出していて、私もそれについては大賛成ですけれども、そこを具体的に、国際友好を含めてきちんと担当の方はやっていかないといけないと思うので、そこをしっかり押さえていただきたいと思いますけれども、もう一回その辺のところも含めて、答弁が重なってしまうところがあると思いますけど。","respondent":"寺嶋協働・国際担当課長","answer":"そういった意味におきましては、確かに今までは学生を対象とした語学研修等がメインになっていたという部分もありますけれども、それ以外にも友好協会を通してさまざまな地域のイベントをやっていたところもありまして。","voiceIndex":84,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"確認","question":"品川が出ていくという、そこら辺のつながりが、どうとったらいいのかというのが、ちょっと今聞きながら、どう判断したらいいのかがわかりにくくなってきてしまったので、ある意味確認ですけど、品川は行くのではなくて、待っているというイメージ、これから結びつけようとしていかないというと、そういうふうに捉えてしまうのだけど、違うのかな。","respondent":"寺嶋協働・国際担当課長","answer":"品川を発信するという部分と、あと大きく日本を発信する部分と、二つあると思いまして、究極的には品川区のよさを知っていただきたいのですけれども、やはり外国の方から見れば、まず日本にいらっしゃるということもありますので、例えば日本のいいところを紹介するというのが。","voiceIndex":86,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかりました。品川区は発信していくのに、どこにどうやって発信していくのというふうに突っ込んでいってしまうと、そういうふうに感じてしまう気がするのですね。その辺はどういうふうに考えればいいのか。余りにも相手がひどすぎるからどこまでできるかというのは、区のやれる範囲というのは限られてしまうと思うし、例えば姉妹都市、友好都市を持っていれば、そこに対して発信はしやすいですよね。","respondent":"寺嶋協働・国際担当課長","answer":"確かに日本に来る方、東京に来る方に、特に品川区にという形で打ち出すのは決して簡単なことではないと思いますけども、まず我々のほうで品川区のよさをもっと十分調べまして、それを発信するという形で、ある意味いろいろ例えば電車の経路とか、品川駅まで行ってしまうとか。","voiceIndex":88,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば、この前の資料で、大使館や領事館の一覧資料をいただいていますけど、例えばこの中でタイの大使館、一番接触があると思いますけど、大使館のほうから国の中で品川をどこまでアピールしてもらえるかわからないけれど、品川区としてタイに対して品川のこの状況をアピールしきれているのか、品川に来るようにタイの国の中で何かアピールしてくださいよというようなものが伝わっているのかどうか。","respondent":"寺嶋協働・国際担当課長","answer":"品川区のよさを各大使館に伝える努力はしてきたつもりですけれども、まだまだやれる余地は残っていると思いますので、引き続き努力していきたいと思います。","voiceIndex":90,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"台湾の場合、日本と国交を結べないということで非常に厳しい状況があるというのも聞いておりますけど、山口県だったか、しか交流がないというのを前に聞いたことがありますけど、そういう接点のある部分とつながりを持っていった上で、私はあえてアメリカ、ヨーロッパというよりも、東南アジアの中で何か提携を結べるところがあれば、進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはり、先ほど鈴木委員からもありましたけど、接点があるとすればそういった品川区もタイだったりというのが、非常に可能性が高いのかというふうに思いますので、きっかけをもし求めているのであれば、そういうところから発信をしていけるのかというふうに思うので、積極的にアジア圏、やはり近隣国ですから、友好を持つことによってメリットというのは絶対にあると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"ただ、もちろん、今まで積み上げてきた交流を大事にしていきたいという思いはそのとおりですけれども、こんな形になると、方向を見出す議論というのはまだ積み上がっていないと、逆に品川区の説明を聞いても、相手がある話ですから、なかなかどう呼応しているのかというところも、また困難なところも当然あるのかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-038"},{"speaker":"吉田委員","kind":"意見","question":"どういうふうに品川区がやっていくのかと思うと、先ほどほかの国から具体的ないろんな話を聞いているというお話を聞いたのですけど、パートナーとしてメリット、どのようなメリットがあるのかという話がある中で、そういうふうに外からもいろいろと発信されてくるのが、私はちょっと戦略的に考えていく自治体であるべきなのかという考えがするのですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"私が考える国際友好の原点というのは、仲よく、グローバルに愛し合うというのでしょうか、仲よくしていただくというのが一番の原点だと思っていますので、区として何ができるかと思いますと、とにかくいろんなご意見があって、外にアピールとかいろいろあると思いますけれども、今回戸籍の方法とかが変わって、いきなり人口がぼーんと増えたではないですか、３６万６,０００人ぐらいに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-040"},{"speaker":"山元委員","kind":"意見","question":"最初に、品川区がアジアの都市と交流できることというのは何だろうと思いました。ただ、そういうあまり難しいことをちょっと私は言えないのですけど、でも、人対人を大事にすることが一番大切なことで、まず品川区としてやれることをやっていくというのが大事ではないか、そこの中から、どういうビジョンを立てようかとかということを考えていけたらいいのではないかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-041"},{"speaker":"向副委員長","kind":"質問・要望","question":"インドネシア、タイ、あとブルネイ・ダルサラームとか、大きなところももちろんあって、そこと品川区との直接的な何かしら経済的な協定とか、今後将来的にもっと結んでいって発展していけたらいいかというのもありますけれども、品川区がそれとはまた別にコンサルティング的な役割で、もうちょっとタイ王国が求めているものが品川区だけで難しかったら、別の自治体とか、日本にそういうのがないかとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"逆に交流は交流のよさがあって、ビジネスはビジネス、販路拡大をしていく、生産拠点が移っては困りますけど、目的に照らしてどうあるべきなのかというふうに思います。この間積み上げてきた交流事業はとても大切だと思いますので、そこを全然否定するつもりはないですけども、やはり今日的と思うと、なかなかまだ区民的な議論、要望はどうなのかと思います。あまりまとまっていないのですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-043"},{"speaker":"石田（し）委員","kind":"意見","question":"ただ、区に今後のビジョンを考えたほうがいいのではないかというだけだとあれなので、今ある姉妹都市、友好都市において、僕は前からずっと言っておりますけど、やはり災害が起きたときに助けられるのかどうか。姉妹、友好というのであれば、そこには助け合いというのがどうして出てくるのかというふうに思いますので、これはなかなかやっている自治体というのはほとんどないと思うのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"品川区から経由して現地にやっていただきましたね。すごいその辺では今までもいい経験をしていただいているだけに、そういうのはどんどん活かしていただきたいというのは一つ感じた部分です。常に品川区があるということをわかるような形、逆にさっき藤原委員がおっしゃったように、品川区はどこと結んでいると区民の方にもうちょっとわかるようなアピールもしてほしいというのも１点追加したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"文化については、この間議論があったので大体イメージが持てる。芸術について、例えば商店街と連携したアートフェスティバルと言いましたか、あとメープルセンターが新しくなって、地元のいろんな若手芸術家というのでしょうかね、アーティスト、いろいろまだまだ芽が、芽が出ていないというのは失礼ですね。発展の過程であっても、いろいろ取り組みという話は伺うのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-046"},{"speaker":"中塚委員","kind":"意見","question":"そうですね。品川区としては、要するに原美術館とか、Ｏ美術館とか、それも大事ですけど、それとともに、若手芸術家でいろいろ取り組んでいるところも思慮に入れて、どんな人という言い方は変ですけど、どういう取り組みが今あるのか、そこでも注目をして、品川区の発掘といいますか、できれば芽が花開くといいとは思いますけど、そんな夢を見たいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-047"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"資料で、ぜひいただきたいと思うのが、文化施設と芸術関係の施設とスポーツの施設、品川のガイドブックとかにもいろいろと出ていますが、ぜひその辺はどういった施設がどのようなために品川区内に、どういった地域にあるのかというのは、できたら一覧でいただけると非常にありがたいと思うので、その辺をぜひ正副でまとめていただいて、可能な場合で構いませんけど、出していただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-048"}]},{"id":"topic-05","title":"の４、その他全般ということで、その他","agenda":"の４、その他全般ということで、その他","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"今ちょっと思い出したのですけど、今度区長杯の競馬の件でご案内をいただいています。区民委員会だけいただいているのでしょうか、競馬の関係。その流れが、私いただいて、ちょっと、どういう流れで来ているのか、区民委員会の案内なのか、というのは、基本的に競馬の関係は総務委員会で審議するところに、区民委員会でいただいたので。","respondent":"久保田地域活動課長","answer":"後ほど担当書記のほうを通じまして、もう一度ご案内を差し上げますので、出欠の確認の上、総務課のほうにご報告したいというふうに思っております。","voiceIndex":120,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"確認","question":"了解しました。意味が、全員に伝わってはいないので、どういう意味か、その辺意味がよくわからなかったのと、例えば本日のその他か何かで出るのかと、口頭で出るかと思ったけど、何もなかったので確認しました。もちろん行くのが嫌だとか、行かないよというのではなくて、大もとは違うのですけど、全体的なところがわからなかったので確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":55210,"voices":124}},{"id":"h25-20131105-7","meetingId":"h25-cm11","date":"2013年11月5日","dateIso":"2013-11-05","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の平成２６年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","agenda":"はじめに、(1)の平成２６年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","exchanges":[{"speaker":"井上委員","kind":"質問","question":"高齢者住宅のほうからなんですけれども、募集の人数５０名程度を考えているということだったんですけれども、その根拠と、空きは毎年どのくらいある状況なのかということと、年１回ということであれば、去年も登録者が５０名くらいとすると、どのくらいの応募になっていたのか、教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"こちらにつきましては、例年１４０名から１５０名の方々が申し込みをされているところです。この要件に合致した方の中でも、やはり緊急度の高い、例えば、立ち退きを求められている方、あるいは、住環境の劣悪度が重い方等につきましては、かなり多いと認識しています。","voiceIndex":7,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"１４３名申し込まれて、６１名が登録ということで、その関係は、１４３名の方がこの五つに該当しないということなのか。その辺がどういうことなんでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"やはり、空き室の問題というのがありまして、例年ですと、大体３０戸程度と申し上げました。","voiceIndex":9,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"登録というのは、自分が登録するのではなくて、品川区が、あなたは登録者ですよということで、決めるのは品川区ということなんでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"実際に申し込みを受けて、そのうえで、こちらのほうで、ご本人がどういう状況かということをきちんと審査、これは書類上の審査と、それから実態調査をし、どういうご自宅にお住まいなのかということを、きちんとその辺を見極めながら審査しているものです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"家賃が高額というのは、具体的にどのくらいのことを指しているのかということ。それから、大井林町のほうは、中に入られてから介護等が必要になった場合には、外付けサービスで、介護を受けながら暮らすことも一定程度できるということだと思うんですが、ちょっと確認なんですが、通常の高齢者住宅の場合は、介護等がかなり必要になってきた場合には、原則は、出なきゃいけないんでしょうか、教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"そういった方々に、やはりさまざまな支援をしながら、限りなく住み続けるといったことが、実際に我々高齢者住宅を考える側にとりましても、お元気なうちは住んでいただくといった考え方に基づいて、デイサービスが必要な方であったり、あるいはそこにヘルパーが必要な方だったり。","voiceIndex":13,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"介護の件は、では、ここに書いてある4)の考え方としては、独立して日常生活を営め、自炊が可能な方というのは、寝たきりでなければ大丈夫みたいなイメージでいいんでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"したがいまして、高齢者の方々ですので、お入りになってから身体機能が低下するというのは、その辺のことにつきましては、適切なサービスにつなげていくといった考え方で、申し込みの時点では、自立です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"１点だけ確認をさせてください。辞退等で４３名が実際に登録をされて、２３名の方が入居されたということで、２０名の方が、希望されていて入れなかったというなんですけれども、今年度、５０名募集された場合に、この２０名が順位的には優先されるということなんでしょうか。次の５０名というのは、２１番目からとか、そういうことなんでしょうか。そこのところを教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"やはり多くのお困りの事象といいますか、生活状況がありますので、その方々がやはり最優先ではないか、緊急性の高い方々ではないかということで、この２０名の方がお入りになれなかったという部分については、今の生活状態も。","voiceIndex":17,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"二つあります。今年はもう、そういった要件を廃止されたのか、どうなのかということが１点。それから、先ほど、２３名の方が入居したということで、登録についても、入居についても、区が判断して決めているということですが、苦情申立てとか、どうしてそういうふうになるのかとか、そういった納得ができないというような不服申請をする仕組みは、ちゃんとできているんでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"大井林町のほうの住み替えの入居枠です。こちらにつきましては、昨年の６月１日にオープン、６月２日入居開始ということで、その前の年度から各所管の木造密集市街地、あるいは、八潮のほうの住み替えの関係で行ってきたものにつきましては、次年度は廃止をしています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"住み替え枠を１年目はつくって、もう廃止されたということなんですけれども、今、評価をしたときに、ほんとうに枠が必要だったのかどうかということ。それとも、１回目にやったときに、応募が足りなかったですよね。そういう意味で、利用者がないということで、判断をして廃止をしたのか、枠をつくったことと、廃止をしたところの総括というのは、どういうふうにまとめられているんでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"八潮からの住み替えと、それから木造密集地域からの住み替えということで、まず八潮につきましては、募集したところ１０組、その中で単身用の方もいらっしゃいますので、全てが２人用の住居ではございませんけれども、当初の予定では２０名程度ということで。","voiceIndex":21,"id":"exchange-008"},{"speaker":"井上委員","kind":"確認","question":"ごめんなさい、ちょっと質問の意図が通じなかったかと思うんですけれども、住み替えの枠に応募が少なかったというところで、住み替えたときに不安があるだろうと躊躇した人たちがいるんではないかということに対して、それで申し込みが少なかったと。そこのところを品川区はどう判断をしているんですかということを、確認したいんです。","respondent":"白鳥高齢者いきがい課長","answer":"ただ、八潮、あるいは荏原方面の木造密集地域からの住み替えの方々につきましては、それぞれ各所管のほうから、住宅事情ですとか、施設の構成ですとか、あるいは地域のこと、全ての全体的なことの中で丁寧にご案内、ご説明をしている中では。","voiceIndex":23,"id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"高齢者住宅部門としては、そうだということで、それぞれがやったでしょうということで、これは多分、高齢者いきがい課長を責めてもしようがないかなと思うんですが、健康福祉事業部長とか、副区長とか、トータルなところで、そういったところの判断について、何かご説明があればお願いしたいと思います。","respondent":"早津健康福祉事業部長","answer":"住み替えの需要が実際にどうだったかというのは、所管としては、住宅課等で考えることだとは思いますが、高齢者住宅として建設したものを、それを有効活用ということで、一定の枠を設けたわけです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"大井林町、高齢者住宅、どちらもなんですけれども、なぜ部屋があくのか。転居とか、死亡とかあると思うんですけれども、ちょっとそこの多いものを教えていただきたい。それから、高齢者住宅、応募が、去年１４０名から１５０名あったというところでは、高齢者住宅に対して需要がどんな状況か、区としてどう考えているのか、ちょっとお聞きしたいんです。","respondent":"白鳥高齢者いきがい課長","answer":"ただ、その中でも、高齢者住宅という中で、緊急性の高い方が入居される、管理人がいて、区の施設ということで、安心して住まわれるといった中で、こちらのほうにお申し込みをされる方がほとんどだというふうに思っておりますが、先ほど申し上げましたとおり。","voiceIndex":27,"id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"大井林町の話なんですけれども、風呂なしの部屋もありますね。そこが、ちょっと聞いた話なんですが、要介護状態の方が入れるように確保されている、詳しくはわからないんですけれども、そういう話も伺ったんです。風呂なしの部屋の現状と、本来の対象は、ここにある募集要項的なものと一緒なのか、お聞かせください。","respondent":"白鳥高齢者いきがい課長","answer":"１点目のサービス付高齢者住宅のほうの今後、増やす予定は、というご質問ですが、区立型のサービス付高齢者住宅は、昨年度初めてつくったものですから、今後につきましては、これから入居者の状況ですとか、品川区内の地域全体のことを見た中で、今後。","voiceIndex":29,"id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"入居されている方から、快適だとか、いま一つだとか、いろいろあるかと思うんですけれども、そういった声などを把握していらっしゃれば、教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"先ほどもご説明しましたとおり、移り住むことにつきましては、大変に抵抗がありますし、労力も必要であるといった中で、思い切って自分自身を奮い立たせてというようなこともある中で、昨年６月当初につきましては、誰も知り合いがいないというような状況の中では。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"申し込んで、当たったらというか、やっぱり次の家がないとそこの家は売り払えないわけですから、入居が決まってから売却をしていくという手続はいけないんだろうかという、応募もできないというところでは、何とかならないかというところでは、どうでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"１点目の、さまざま広く、この大井林町を知っていただくためのＰＲの工夫につきましては、これから機会を捉えながら、数多く知っていただくためのＰＲに努めたいと考えています。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-02","title":"の肺がん検診実施医療機関の拡大","agenda":"の肺がん検診実施医療機関の拡大","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"今までの品川、荏原の両医師会のところから新たに１３カ所増やしたということなんですが、この背景というか、経緯というか、その辺を教えてください。","respondent":"江部健康課長","answer":"この検討につきましては、もう１年越しの検討で、両医師会と協議を重ねてきたものです。理由の一つは、まず受診率の伸び悩みで、数年ほぼ５,５００件くらいで続いているということ、率にいたしますと、５％台というところできておりまして、受診数を拡大したいということ。","voiceIndex":40,"id":"exchange-015"}]},{"id":"topic-03","title":"先ほど視察も行いましたが、本日は、障がい者の就労支援","agenda":"先ほど視察も行いましたが、本日は、障がい者の就労支援","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ほんとうは現場でお聞きしたかったんですけれども、就労支援センターの中で、ジョブコーチとか、ありますけれども、これは伺って大丈夫かどうかわからないんですけど、今回、厚生委員会の視察で伺ったときも、就職するよりも定着支援のほうがとても大変なんだということで、当然だろうと思うんですけれども、そのジョブコーチ的な人たちが。","respondent":"中山障害者福祉課長","answer":"キャパがあのスペースで足りるのかというところと、相談と訓練、今後の方針というご質問ですけれども、今の体制になったのが平成２４年度からということになります。","voiceIndex":47,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"障害者の方たちが一般就労を目指したいというところで、ハローワークが、障害者専用にあるかと思うんですけれども、そこが大変遠くて、なかなか行かれないというような声を伺っているんです。ここがなるのか、それとも、ほかにありますよということなのか。区内のそういった高校から就職された方たちのお話を伺っているんですが、そこの体制整備、品川区はどういうふうにとられているのか、教えてください。","respondent":"中山障害者福祉課長","answer":"就労移行支援のほうでも、発達障害の方の受け入れも行っておりますので、もしご相談があれば、こちらのげんき品川のほうで就労につなげることは可能であると考えております。","voiceIndex":49,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"就労支援センターと就労移行支援事業が一緒にやることによって、就職の道が機能するということは理解するんですが、そうすると、旗の台の心障会館とか、就労移行支援事業をしているところが、ここだけではなくてあるかと思うんですけれども、そうしたところの連携に課題があるのではないかと思うんですけれども、その辺はどういう状況でしょうか。","respondent":"中山障害者福祉課長","answer":"先ほどもちょっと視察の中でもお話があったかと思うんですが、就労のことはげんき品川でいいんだけれども、逆に生活面で不安がないのかといったときに、障害者相談支援センターと連携をうまくすることで、長く働き続けられるというような支援をしています。","voiceIndex":51,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"移行支援を１カ所にしたということは、前にも、げんき品川では就労の訓練はされていたと思うんですけれども、人員的に、定員的にすごく増えてしまっているのではないかと思いますけれども、そういったことはないんですか。","respondent":"中山障害者福祉課長","answer":"就労の相談のところと、それから訓練の機能がうまくかみ合うことで、その方の能力ですとか、適性を見極めて、よりよい就労につながるということで、平成２４年度から、会館のほうからげんき品川のほうに就労移行支援を移してきたというのが、この間の経緯になります。","voiceIndex":53,"id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"他区の先生と何回かお話ししたことがあるんですけれども、げんき品川はげんき品川で、こういうキャパでやるというのは、自分たちで考えてやっているんでいいと思いますけれども、あまり課題をいろいろかぶせるとなかなか厳しいと思うので、もしも事業を拡大するのであれば、同じように、下から上がってくるＮＰＯをうまく育てるとか、あるいは、委託するとか、見つけるとか。","respondent":"中山障害者福祉課長","answer":"確かに、品川区全域を、１カ所の就労移行支援センターでというのは、なかなか厳しいところもありますので、今後の障害者の就労の意欲、相談の件数とかの伸びも見ながら、そういったＮＰＯ等があれば、育てていきたいと考えているところです。","voiceIndex":55,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから逆に、福祉的就労をやっている方の中から、訓練を重ねて一般就労に結びつけたいということで、げんき品川のほうにくるとか、そこの行ったり来たりというか、その連携というんですか、この辺がどうなっているのか、ちょっと教えてください。","respondent":"中山障害者福祉課長","answer":"そういった中で、障害者就労支援センターだけではなく、福祉的就労ですとか、就労移行支援を使うには、必ず障害者相談支援センターの方で個別支援計画を立てなければならないことになっていますので、就労支援関係機関連絡会というのを設けまして、げんき品川だけではなく。","voiceIndex":57,"id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"２点目のほうなんですけれども、そうすると、いろいろな福祉法人がＡ型、Ｂ型とやられている中で、これはわからないんですけれども、どうしても福祉法人のほうでも定員確保というんですか、そういう中で定員割れしないようにという考えもおありかな思うんですけれども、その中で連携がうまくスムーズにいくのなと、そんなことはないとは思うんですけれども、ちょっと心配で、その辺は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"げんき品川、今日見に行かせていただいて、私も、なかなか狭いところで大変そうだなというのは感じたんです。職員５人の専門というか、それぞれ内訳があれば教えていただきたい。ですので、じっくり話を聞いてもらえたり、また企業に対して、ジョブコーチのほうで障害者にかわって伝えていくということを、もうちょっと強化していただきたいと、私は思うんですけれども、その辺はいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"例えば特別支援学校でも、卒業後３年間は、特別支援学校の進路の先生が職場に見に行ったり、あるいはもちろんげんき品川にも登録をしてもらうので、げんき品川のほうも見に行ったり、そこも両者が連携したりということで、企業側でもさまざまなアプローチをかけておりますし。","voiceIndex":60,"id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"障害者雇用促進法で、雇用率のアップなどが、というところで、私たち共産党としては、自治体が率先して障害者の雇用を進めていくべきだという質問などもさせていただいているんですけれども、自治体がそういったところでの雇用率をさらにアップさせていくのかということと、今現在、品川区は、規定の雇用率は雇用しているということなんですけれども。","respondent":"中山障害者福祉課長","answer":"そういったところでも、やはり公の機関ということで、積極的に障害者を雇用していかなきゃいけないというところは十分に理解しているところです。現在、法定雇用率２.３％のところ、品川区では３％ぐらいです。当然、上回った雇用をしています。","voiceIndex":62,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"これは要望です。通所施設が足りないという声が、やはり障害者団体の方からも届いていまして、今日のげんき品川の状況を見させていただいても、やはり新たに増やしていかなければ、もうキャパオーバーで、どこもいっぱいになって、さらに職員も大変になって、サービスが行き届かないという形にもなりかねないので、さらに増やしていくということを考えるんですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"例えば、具体的にどこかの企業と一緒になってやれば、就職が決まれば、それは実績として残っていくわけなので、区としましては、就労移行支援をもし増やしていくんであれば、きちっとした障害者の安定した雇用につながるような事業所でないと。","voiceIndex":64,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"今の時点でも、障害者の方がまだ十分ではないと思う現状もある中で、しかしやはり働きたいという願いにこたえていく、その思いを尊重していくことが大事だということも、先ほどおっしゃられていましたので、そこを実現させていくためにも、さらに広げていかなければ、そういった障害者の思いにこたえる自治体にはなっていけないのではないかと思うので、今後ともご検討をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":22415,"voices":73}},{"id":"h25-20131105-8","meetingId":"h25-cm11","date":"2013年11月5日","dateIso":"2013-11-05","committee":"建設委員会","time":"午後 １時００分～午後 ５時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"大崎駅周辺地域イベントの開催","agenda":"大崎駅周辺地域イベントの開催","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"昨年２６万人ということだったんですが、このカウントはどういう形でされているのでしょうか。正確ではないでしょうけれども、どういうふうにしているのかなと。それと、この実行委員会、主催ですけれども、地元企業等で組織されているということですが、あそこの周辺に所在している企業ということなのか、何企業でやっていらっしゃるのかについて、説明を求めます。","respondent":"溝口都市開発課長","answer":"目黒川みんなのイルミネーション実行委員会ですが、地元の特に大崎駅周辺の、例えば大崎電気工業ですとか愛知産業、または開発が終わったサザンガーデン、そういった方たち、また今回事務局であります大崎・五反田タウンマネージメントですとか、大崎エリアマネージメント。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"９名での実行委員、運営はこの９名というか９団体というべきなんでしょうけれども、その方たちでこれらが賄えるものなのかということと、コストの問題として品川区から何か助成金とか、そういうものを出されているのか、教えてください。","respondent":"溝口都市開発課長","answer":"そのうち周辺へのＰＲとかそうしたもの、また震災後の取り組みになりますが、バイオディーゼル燃料をもとにした電源というのは、区から依頼した関係がありますので、それについて４００万円ほど。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"コストについて再度確認したいと思います。要は、品川区として委託費として４００万円は出ていると。そうするとあとの４,６００万円というのは、どこからどういう運営費として出されているのでしょうか。そこの仕組みを教えてください。","respondent":"溝口都市開発課長","answer":"ことしも同様に既に協賛企業等を募りながら、イベントを開催していくという形になっております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後援のところに「品川区ほか」とあるのですけれど、品川区以外にどういうところが後援をしているのか教えていただきたいのと。それともう一点は、発電の量的な部分が、このバイオ燃料で賄えているのかどうか、その辺も詳しく教えてください。","respondent":"溝口都市開発課長","answer":"バイオ燃料につきましては、基本的に地域の方々が集めた廃食用油からバイオディーゼルにしまして、やっていると。基本的には全部、全てバイオディーゼル燃料で発電機を動かして、期間中の電気は全て賄っているという形になっております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"せっかく環境課長もいらっしゃるので、これはこのときだけで終わっているのか、ぜひ、いい取り組みなので、品川区も食用の廃油を回収していますけれども、もっと広がって活発にしてほしいというところにおいては、企業絡みというのはやはり企業ならではのいろいろなノウハウもあると思うので、ぜひそういうのは広げていただきたいという思いがあるので、ちょっとそこを教えていただきたいのと。","respondent":"野呂瀬環境課長、溝口都市開発課長","answer":"そのほかにもいろいろ活用するというのは、意識として廃食用油の活用ということはこれからもうたっていくつもりですけれど、今、具体的にどこどこというのはないですけれども。光のつららにつきましては、大崎エリアマネージメントでさまざまな活動をしていく中で、自分たちで大崎の東西を結ぶイベントをしていきたいということで、自主資金で実施しております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に１番のほうは実行委員会形式と、地域を巻き込んでというところにおいて、広げていっていただきたいという思いもありますけれども、その一つに環境にやさしいイルミネーションを長い間つけていますけれども、ＬＥＤだったりバイオエネルギーを使うという、ぜひこういった面でも宣伝をしていただいて、啓発活動に使っていただけたらと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"所管が違うと思いながら聞くのですけれど、まずイルミネーション２０１２は２６万人集客したと聞いたのですけれど、それを次に商業振興につなげていくような構想については、品川区はどうお考えなのでしょうかというのが一点。それから、いい取り組みだと思うのです。","respondent":"溝口都市開発課長","answer":"今後の延長の話ですけれど、できることなら目黒川全体をつなげるというのは一ついいことだと考えていますし、そういった取り組みに発展させていきたいと考えていますが、あとはやはり費用の問題ですとか、実施する団体等の兼ね合いもあります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"神戸のルミナリエですか、ああいう非常にきれいなものができれば、たくさんの方が来ることも想定されますから、この目黒川でやることはもちろんすばらしいことであり、続けてほしいのですけれども、もっとさまざまな形でＰＲしていっていただきたいと思いますし、天王洲も含めておそらく都市開発課が報告するということは、再開発の部分もからんでくると思うのです。","respondent":"溝口都市開発課長","answer":"それをいかに持続して発展させていくかということが大事だと考えていますので、当課としてもまちをつくっておしまいというわけではなくて、今回大崎が取り組んでいるように、そのつくったものをどう生かして、どうＰＲしていくか、ひいては品川区をどう全国に広めていくかとか。","voiceIndex":19,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"今、伊藤委員から所管が違うという中で、この大崎地域イベントの開催ということで、まちづくりが主になるのか、今の言葉にあったようにまちづくりでできた資本をどう生かしていくか、まずどちらをこの事業について重きを置かれながらやっていくのか、どういう意識のもとに事業を発足して、そして現状続けられているのか、教えてください。","respondent":"溝口都市開発課長","answer":"ただ、当然私どもだけではできない部分はありますので、そういったところにつきましては、商業・観光課を含めて関連部署ともよく連絡を密にして、よりよいイベントになるように今後も進めていきたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"その中で商業・観光課との、先ほど「品川区ほか」ということで観光協会というご答弁をいただきましたけれども、どのような感じで連携がとられているのか、教えてください。","respondent":"溝口都市開発課長","answer":"観光協会につきましては、観光協会のほうのホームページで当イベントを紹介してもらうなど、そういったところでの取り組みをしていくのと、あと、当然地域の再開発事業の中にもありますが、飲食店街、そういったものもありますので、そういったところの橋渡しといったところは。","voiceIndex":23,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"今、商業・観光課で既存のお店などに橋渡しをしているということですが、ここの部分でこのイベントについては、区民委員会でこういうことの報告はあるのでしょうか。","respondent":"溝口都市開発課長","answer":"今回の報告につきましては、あくまでも主催が、一つは実行委員会ですけれど大崎・五反田タウンマネージメント、またもう一つは大崎エリアマネージメントということで、まちづくりを進めていく団体という形になっておりますので、私ども建設委員会だけの報告になっております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、連携のもとにやっているということであれば、しかるべき報告あるいはお互い同士の連携の部分で一定の線引きをしないと、そこの部分で見合ってしまうと、どこまでやっていいのか、どこまでこちらの課がやっていいのか、そういう混乱は生じないのでしょうか。","respondent":"溝口都市開発課長","answer":"本イベントにつきましては、あくまでも都市開発課が品川区の窓口となっておりますので、都市開発課のほうで受けて、必要な調整等はまた都市開発課のほうが庁内の調整を図る、そういった形でやらせていただいているもので、特段見合ったりとかご指摘のことがないように。","voiceIndex":27,"id":"exchange-012"},{"speaker":"大沢委員","kind":"意見","question":"今、委員からもありましたけれども、今後はやはりイベントである以上、区民委員会、ましてや観光協会等々との密な連携のもとに行われるのであれば、そこら辺の所管の委員会に、同時には無理かもしれないですが、出向いていってそれなりの報告なりするのが、やはりいいのではなかろうかと思うのですけれども、このところはどういうふうに。","respondent":"溝口都市開発課長","answer":"当イベントにつきましては、やはり大崎駅ということでまちづくりを進めてきたその延長線上に、大崎駅をつくったまちを持続的に発展させる取り組みの一環として行われているイベントになっておりますので。","voiceIndex":29,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"今の質疑で思ったんですけれど、こういうイベントを、議会も賛成している話ですからもったいないと思いませんか。だけれど次の新しいステップとして、今度は品川区の商業振興課も入れた形の仕組みをつくって、検討なさってみてはいかがでしょうか。ということについては、いかがですか。","respondent":"片田都市環境事業部長","answer":"今、委員からお話がありましたように、これまで継続的な発展ということで、地域が一応主体となって進めてきた、これを区が支援するという形で進めてきたものですけれども、今後もやはり地域の商店とか、これまで連携をとってきたのですけれども、さらに発展させていく上で。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"実行計画（第二次）および地域推進計画に基づく二酸化炭素排出実績","agenda":"実行計画（第二次）および地域推進計画に基づく二酸化炭素排出実績","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"両方とも基準年が２００６年ですよね。そのときに議論になったと思うんですが、地球温暖化防止のためにはかなり厳しい姿勢で臨んでいかなければいけないということで、世界的にも京都議定書をきちんと基準にして考えるべきであるという私たちの意見を述べたことがあるんですけれども、２００６年を基準にした理由をもう一回、改めてお聞かせいただきたいのと。","respondent":"野呂瀬環境課長","answer":"ただしその基準年に対する目標については、京都議定書のとおりマイナス６％を目指すというものに合わせたものです。２点目の目標が達成できないということ。目標を立てたら、それに対して進んでいくのは当然のことだと思います。","voiceIndex":39,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"環境課長のところだけではないので、全区的に努力をしていかないと、今の品川のまちづくりだととても、削減ではなくどんどん増えていくといった状況であると思うので、ぜひまちづくりの観点で環境を大きく位置づけていただきたいと思いますが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"ただ、これは区役所だけの努力ではなく、事業所もそうですし、また区民一般の家庭に対してもそうですし、そういった啓発的な面は数字がまた今度の見直しで変わったとしても、今の地域推進計画の考え方というのは、載っていますとおり全ての区民が行動する。","voiceIndex":41,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区のまちづくりといった観点で、今のままのまちづくりでは、エネルギーをどんどん浪費していくまちになる、地球温暖化を加速させていく状況にあると私たちは見ているんですが、広い視野で見た中で、法律にのっとってとかいうご答弁がいつもあるんですけれど、このままのまちづくりで本当に地球温暖化防止ができるのかどうか、品川区のまちづくりにおいてどうなのかというところを今お伺いしたので。","respondent":"片田都市環境事業部長","answer":"まちづくりと環境が相反するものではないと私は思っておりますので、それが両立するように、なおかつ持続、発展できるようなまちづくり、あるいは環境計画もきちっと進めていきたいと考えているところです。","voiceIndex":43,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では本当に、ここ数年どんどん暮らしにくい、日本全体がそうなってきていますけれど、地球規模というところにおいては、本当にこのＣＯ２削減問題というのは、私は京都議定書、京都で行われて世界的に決めたあの目標を、地球全体で一刻も早く達成していく、その先頭に日本が立たなくてはいけないという意味では、品川は開発がものすごく進んでいて、増やしている方向にある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"もちろん私どもとしてはＣＯ２削減はしていくべきだと思うし、その方向でやっていくべきであると思うのだけれど、本気でマイナス１８％を達成するのであれば、そういうところまで考えていかないと、どんなに計画を出してきたとしても、今ある車を使って、今ある家庭の中の冷蔵庫を使って、電気量を消費していくのであれば、これは達成できないことは目に見えていることであって、そうすると。","respondent":"野呂瀬環境課長","answer":"もちろん今のところ１０年計画の１年目の数字が出たところでございまして、１年目の数字が２５％削減するのに９％の増になっているということから考えると、なかなか計画の目標というのは難しいというのはこちらも認識していますので、見直すのであれば。","voiceIndex":46,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"だけれど実際にこれをやるとするのは、莫大な投資が必要になってくるのではないですか。だからそれは現実的な部分としっかり照らし合わせをしながら、だけれどもＣＯ２削減はしなければいけないわけだから、相差を十分踏まえながら対処していくと思うので、今言った環境計画の改定に合わせて、この目標値についても対処していくということでよろしいんでしょうか。その答弁だけお願いします。","respondent":"野呂瀬環境課長","answer":"それは今後もＰＲしていきながら、数字につきまして今のところ考えているのは、環境計画を５年後に見直しをするときに合わせて地域推進計画を、そのときには国の動向も、今は出ていませんけれども、それとか東京都も当然出てきますので。","voiceIndex":48,"id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"大体方向性は出てきていますけれども、確立されていないというところに立って、目標の数値が高い、低いというのは、これは目標ですから、そういう意味からすれば、崇高な目標を立てれば数値もこういうふうになってくるでしょうし。そういう状況で、まずそのことについて区民への啓蒙、やっているのだという啓蒙について、状況をお聞かせいただきたいと思います。","respondent":"野呂瀬環境課長","answer":"ただ、ちょっと話がずれますが、例えば区民サービスを低下させずに節電というのも、これもまた逆に言えば難しいところでございまして、ある程度数字ばかりを追いかけていくと、逆に区民サービスの低下につながりますし、また数字だけだからということになりますと、じゃあ。","voiceIndex":50,"id":"exchange-021"},{"speaker":"原委員","kind":"質問・要望","question":"それをお聞きして、当然そう思います。それから二つ目としては、やはりここは建設委員会ですからそこに接点として出てくるとすれば、わかりやすい例を出してしまえば、僕は時々思うんですけれども、船に乗らせてもらって川を、品川区から出て港区のほうに入ってみたりすると、意外とまだまだ港区と品川区の境ではっきりと、いろいろな面で違いが残っている。改善しているのはわかります。","respondent":"野呂瀬環境課長、片田都市環境事業部長","answer":"後段にありました、品川区がこういうふうにやっていると一般区民に対してＰＲしていくというのは、例えば品川区単独の実行計画の中で、こういう形でやっているとか、地域推進計画でも申しましたけれども。特に、環境計画の中でも幾つかの条件プロジェクトみたいなものを表記しています、そういう中でも区民と協働してやっていくためにはやはりわかりやすい形で、環境教育もそうですし、いろいろな区が取り組んでいることを。","voiceIndex":52,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"震災もありました、環境も非常に悪環境になってきた、夏場は暑いし、寒くなってくるしということで、そうなると具体的に、一つは品川区としてどうするんですかという、もう境界線ができるのではないですか。それをどう考えているのか。ではそれを今後、品川区のスタンスとして、どう考えて発想の転換をしながら進めていくのでしょうかということで、この辺のお考えをお聞かせ願います。","respondent":"野呂瀬環境課長","answer":"それに対してどんな工夫があるかですけれども、今のところやっているのは当然継続してやっていく、それに対して品川区独自の新しい取り組みとしては、４キロ四方の中で、ビルがたくさんあるようなところで太陽光、ソーラーシステム、これはなかなか非現実的で難しい。","voiceIndex":55,"id":"exchange-023"},{"speaker":"西本委員","kind":"提案","question":"非常にお答えにくい質問だったと思うんですけれども、非常に難しい取り組みだと思うんですね。でも、もしかしたら温暖化という言葉自体を変えるのも一つの手なのかなと。それはもう慣れてしまっている部分もあるので、なのでもっと違う、ここで何という提案はできないんですけれども、そういう方向にして意識を改革するとか、もっと発想の転換をしていかないと、なかなか難しいだろうなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"なので、ぜひ自然エネルギー導入のところ、この品川区でもできることを考えて、私、太陽光発電というのは有力であると思います。なので、ＣＯ２が発生するようなエネルギーを使うのばかりではなくて、自然エネルギーの活用というのを大きく大きく位置づけて、今後区民の中に広めていくという努力が必要だと思いますが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"私が先ほど申しましたのは、いわゆるメガソーラーといいますか、大きな広い土地があって、そこでやっているような他の県とかでやっているところがあります、そういうのは、今のこの品川区のエリアではなかなか難しいのではないかということで申し上げたので、そうでない。","voiceIndex":58,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ家庭用の太陽光パネルの支援も力を入れていただきたい、やはり啓発も含めて各家庭で電力を生み出していくということは有効だと思うので、太陽光パネルの支援を進めていただきたいのと、都会でもビルの中で、水を循環させて小水力で電力を生み出すとかいろいろあるので、ビルでの義務づけとか工夫をすればいろいろできると思うので、ぜひこの品川区でできる再生可能エネルギーの開発というところにも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"今、太陽光パネルの話があったんですけれども、品川区は太陽光パネルって本当に有効なのでしょうか。あまりにも鉛筆みたいな家なので。品川区の現状に果たして合うのかどうか、それに対して助成金をどうのこうのというのは、特定の人に助成をしているような状況で、あまり平等性からいうとどうなんだろうと思うんですけれど、その辺の考え方はいかがでしょうか。","respondent":"野呂瀬環境課長","answer":"それに対して区としては、そういう形でも設置するという方につきまして一定の支援をしているという現状ですので、なかなかケース・バイ・ケースのところで難しいことがあるというのは、現状だと思います。","voiceIndex":61,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"では逆に、こういう条件だったら可能ですよというような、データみたいなものは提示できるんですか。例えばこれから家を建てようと今思っている中で、こういう構造だったら大丈夫ですよというふうにアドバイス的なものが求められるとか、考える一つのきっかけみたいな、そういうのはいかがでしょうか。","respondent":"野呂瀬環境課長","answer":"環境課の窓口でも、太陽光パネルのお申し込み方法のところに一定のそういうことも書いてありますけれども、やはり何回も言いますけれどケース・バイ・ケースで、例えば南側で、こちらが屋根で設置できても、隣のマンションが邪魔になってしまったら難しいというのもありますし。","voiceIndex":63,"id":"exchange-028"}]},{"id":"topic-03","title":"環境経営セミナーの開催","agenda":"環境経営セミナーの開催","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"講師を二つの会社に、アズビル株式会社と株式会社ユビテックと書いてありますけれども、何年か続けていらっしゃるのか、この取り組みが何年目なのかその辺、ちょっと聞き漏らしたのかもしれませんが、この会社を選んだ選定の理由とかも聞かせていただきたいのと。８０名という規模なんですけれども、応募の状況が広がっているのか、その辺もお聞かせください。","respondent":"野呂瀬環境課長","answer":"この会社を選んだ理由ですけれども、今回はテーマがビルエネルギー管理システムということで、実際に区内の業者でこのアズビルとユビテックというところが、実際にこのビルマネジメントシステムを活用してやっている、区で認定したエコパワーカンパニーということで。","voiceIndex":71,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここの中身は多分、ずっとやられているのでいろいろな取り組みがあると思うんですけれども、例えば夜間電力を蓄電池で集めて使うとか、大きな意味では先ほどの延長線なんですけれども、ドイツなどはビルディングの屋上だけでなくて、壁面にも太陽光パネルを設置するとか、自社の電力を賄っていくという姿勢こそ大事であると思うので。","respondent":"野呂瀬環境課長","answer":"できる、できないよりも、やはり他社との意見交換の場に非常に有意義だということですので、事業所が増えていますので、当然その新しい事業所に対してもＰＲはしていきながら、逆にこの事業そのものもブラッシュアップして、いいものにしていきたいと考えているところです。","voiceIndex":73,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"品川区内の、このセミナーに該当する事業者の数というのは大体わかるんでしょうか。品川区の中でどれだけ企業がいて、どれだけの方たちが対象になるのか。大体でいいですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"そうでなくて、やはり経営者ですから、こういうことをやるともうけられますよみたいな、それが中心でないと、なかなか興味を引かない、仕方ないからやるしかないのかな、やっていけないからちょっと勉強でもしてみようかなという感覚だと、多分それなりで興味は低いと思うので、そうではなくて、もうけるため。","respondent":"野呂瀬環境課長","answer":"というのは、やはりどうしても決めつけみたいなことをするとそれはいくら会社の方針でやったとしても、なかなかうまくいかないというのは当然だと思いますので、そこをうまくやっていくということと、楽しみながら節電というのはなかなか難しいかもしれないですけれども。","voiceIndex":79,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり環境経営セミナー、もうちょっとわかりやすいというか、いずれにしても節電とかされるときに企業のほうがかなり節電で締めつけられていますよね、大企業は率先してされると思うんですけれど、でも事業者は当然ながらそれを要求されるわけですから、やはり危機感というのはある程度持ってもらえるようなテーマであったり、説明文であったり、ご案内であったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"環境経営セミナーの開催についてということで、これは平成１９年度からことし７回目ということなんですけれども、６０万円弱の予算取りをしているわけですけれど、この中でいわゆる費用と効果についてということで、効果についてお尋ねしたいんですけれども、この目的の中で「事業者にとって」云々、「経営的活力に結びつく」、それと「実施する意識を喚起する」ということで、ここのところ。","respondent":"野呂瀬環境課長","answer":"ですから、ここには「具体的な活動を実施する意識を喚起するため」という形で書いてありますが、これに対して企画のほうとしてはいろいろ手を変え、品を変えやっているところですけれども、逆に出てきていただく事業者の意識にもかかっているところですので。","voiceIndex":82,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問・要望","question":"ただ聞きたいのは、端的に聞きたいんですけれど、行政側の目的は環境についての意識を高めるということだと思うんですが、そこで端的に、どのような経営的活力に結びついたのか、その経営的活力に結びつくような事例はどのように分析しているのか、また「活動を実施する意識を喚起」、どのような喚起をされたのか、この二つについて端的に、これこれこういうふうに活力が生まれました。","respondent":"野呂瀬環境課長","answer":"ですので、あくまでもアンケートの中で「非常に参考になった」「具体的に」みたいなところで、今回やるときに逆に結びつくようなところがあるかどうかも含めて、具体的に聞いていきたいと考えていますけれども、ただし実際に経営に結びついたかどうかというよりも。","voiceIndex":84,"id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"過去５年行っていて、分析していないんですか。漠然とということですが、やはり行政は、費用に対して効果というのは必ずきちんと追求すべきものと思うんですけれども、このところは分析も何もされていないんでしょうか。ただ漠然と参考として捉えているだけなのか、そこのところをちょっと教えてください。","respondent":"野呂瀬環境課長","answer":"けれども漠然的に、この事業をきっかけにして節電に対する取り組みを考えることになった、そういう面ではこの事業は活用されているなということで、そういう細かいところの把握はちょっとしていないという形で申し上げているところです。","voiceIndex":86,"id":"exchange-036"},{"speaker":"大沢委員","kind":"質問","question":"漠然という単語が今、２回ばかり出てきましたけれど、これは検証すべきことだと大事なのではないでしょうか。曲がりなりにも５０万何がしの予算をつぎ込んでいるわけで、これを分析もしていない、検証もしていない、じゃあ、この事業は一体何なんだという話になると思うんですけれども、どういうお考えですか。","respondent":"片田都市環境事業部長","answer":"今、委員のお話しいただいたことを含めて、きちっとやはり対外的な部分も含めて、どういうような、抽象的なところが多いと思うんですけれども、どのような評価ができるのかということもあわせて、整理していきたいと考えています。","voiceIndex":88,"id":"exchange-037"},{"speaker":"大沢委員","kind":"質問","question":"まさにそのとおりで、環境というものは数値目標で決められるもの、決められないものが多いと思いますけれど、そこのところ、まさに決められないもの、先ほど数値を感覚で捉えていらっしゃるようなこともちょっとお話の中で受け取ったので、数値目標が出しにくいものであれば、それなりの分析が必要なのではないでしょうかということをお話しさせていただきました。それで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-038"}]},{"id":"topic-04","title":"防災緑化助成の実施","agenda":"防災緑化助成の実施","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"区内全域で、危険な箇所の調査というのは行われたことがあるのかどうか。もう一点は、モデル地区を実施されるということなんですけれども、ぜひこれを広げていただきたいんですけれど、どのぐらいモデル地区でやられて結果を出されるのか、将来的なことを聞かせてください。","respondent":"多並公園課長","answer":"今後のモデル地区を踏まえての展開ですが、まずは今回いろいろな新たな取り組みを行ってもありますので、旗の台四丁目でまずは助成をさせていただいて、その後、どのような形で展開していくべきかというのをもちろん見据えながら。","voiceIndex":96,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは全体で予算はどのぐらい見込んでいるのか教えていただきたいのと、ぜひ広げていただきたいので、この旗の台四丁目のモデルで広がって、実績が上がるようにご努力をお願いします。","respondent":"多並公園課長","answer":"平成２５年度の予算ですが、昨年度５４０万円に対して、今年度は６９０万円のまち並み緑化助成の生け垣について行ってあります。今まで生け垣助成を進めてまいりましたが、今後やはり防災という観点も含めまして、緑化という面も含めて進めていくということで、考えてあります。","voiceIndex":98,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ防災という観点で、危険箇所の把握なども目を向けていただいて、個人ではなかなか言えなくて困っている地域もあるんですが、声も上げていきますけれども、改善されるようにお力をいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-041"},{"speaker":"伊藤委員","kind":"確認","question":"実施についてですけれど、旗の台四丁目をモデル地区として増額するこの事業は、単年度事業でやるのでしょうか。それとも複数年でやるのでしょうということの確認をお願いします。もしくは例えば３年計画でこれだけの実績をやりたいという予定があって、なさったと思うんですけれども、その部分の予算の考え方が一点と。だからそういう展開についてはどうお考えなんでしょうかということをお聞かせください。","respondent":"多並公園課長","answer":"それ以外の地区につきましても、もともと総合危険度が、今回新しく出る前では４地区ございました、今度また総合危険度の高い地区というのがまた新たに示されてありますので、そこら辺をにらむのと、今後の防災事業、まちづくり全体の中でも進めていますが。","voiceIndex":101,"id":"exchange-042"},{"speaker":"伊藤委員","kind":"質問・要望","question":"目標なり、その計画のことがなかったんですけれども、それを教えていただきたいのと、それから先ほどの説明の中で、たしか４件実績があったと聞きました。それはそうなんだろうけれど、せっかくモデルとしてやるのなら、４件ではなくて例えばこれぐらい件数を出していきたいとか、そのことについてお考えをお聞かせください。","respondent":"多並公園課長","answer":"この助成事業を進めるに当たってもいろいろな課題やどんな点を盛り込んだほうが進められるかというのも、そこでお話を聞きながら進めてきた中で、一つあったのは、細街路がこの地区の約半分程度、先ほどの接道部の中にありますので。","voiceIndex":103,"id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういう個々の努力はお疲れさまです。それがぜひ形になって、具体的に進めるためには、やはり区民の方々にこういうふうなことを十分理解していただいて、建築される方がじゃあ、やろうと思っていただくまで、理解を求めていかなくてはいけない、それも大変だと思いますけれども、頑張ってください。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"それと、お隣同士の境界線とかいうのは、なかなか明確でない場合が多いと思うんですね。その場合測量をしなければいけないとか、変えればいいんですよというだけでなくて、いろいろな手当が必要になってくると思うんですが、ここの助成というのは、それらも含めての金額になるのか、どういう算出をされてどういう許容範囲があって、この金額があるのか、教えてください。","respondent":"多並公園課長","answer":"境界線の問題で申しますと、細街路ですから大井などは私道であったり、区道の場合もあります。そうした場合は、基本は現況をベースにしまして、そこにプランターという形で置かせていただくような形の対応で今回はやっていきたいと、そういう考えです。","voiceIndex":106,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"防犯という意味も、いろいろ状況によって変わると思うので、それはしっかりやっていただきたいということと、境界線なので意外とお隣同士でもめるケースがあるのではないかと思っているので、片やＡさんはいいと言っても、Ｂさんは嫌だというところもあれば、そこのあやふやな部分があるとか、いろいろなケースがあると思うので、その辺には対応していただきたいということを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-046"},{"speaker":"こんの副委員長","kind":"質問","question":"この事業は大変大事な事業であると受けとめております。今回はモデル地区ということですが、区内全体でこの事業がなかなか進まないという現状もあるかと思います。となると、あわせてブロック塀から緑化をしましたよだけではなくて、その先のメンテナンスということもあわせて今後考えていかなければいけないのかな、それを考えていくと、より進むのかなと考えるんですが、お考えはいかがでしょうか。","respondent":"多並公園課長","answer":"ただ、今後またこれにつきましては続けてまいりますので、その地区でもいろいろなご意見が多分あるかと思いますが、そういうのは丁寧にお聞きしながら、今後どう進めればいいのかというのは今後、検討していきたいと考えています。","voiceIndex":109,"id":"exchange-047"},{"speaker":"こんの副委員長","kind":"質問","question":"そうしたときにという意味で、今後の考え方ということで、どうなんですかというのを先ほど述べさせていただいたんですけれども、いわゆる建てたらおしまいというものではなくて、そこら辺のところをどう考えるかということが、一つは今後もついてくる課題かなというふうに思ったので、その辺持ち合わせていきながらこれを推進するということを。","respondent":"多並公園課長","answer":"メンテナンス部分まで申しますと、今までバランスでいいますと昭和６３年から生け垣助成を進めていて、今まで３.２キロにわたって助成しているところがあります。２３７軒です。","voiceIndex":111,"id":"exchange-048"},{"speaker":"こんの副委員長","kind":"意見","question":"でも一軒一軒そうやって聞いてくださって、皆さんがこれだったらというところを聞いてくださっている努力は本当にありがたいと思いますので、どうかこの事業が成功するよう、この先の部分も見せつつというか、考えつつというか、事業の展開をお願いしたいと、意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-049"}]},{"id":"topic-05","title":"災害時協力協定の締結状況","agenda":"災害時協力協定の締結状況","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"３ページ目の避難収容のところについての確認なんですけれど、避難所、補完避難所、二次避難所等、これはこれでもちろんいいんですけれど、区民にＰＲをする必要がありますね、当然。だけれど事前に、例えば○○大使館が避難所になるということをＰＲしにくいところもあるわけじゃないですか、施設によっては。だからその矛盾をどう解決するおつもりなんですかということを聞きたいです。","respondent":"鈴木防災課長","answer":"特に収容関係に関しましては、区と協定をお結びいただいた段階で区のデジタル移動通信登載の無線もしくは今度配付するタブレットのような、通信手段は一緒に区のほうで用意させていただきまして、実際の災害時には区と区の災害対策本部協議をしながら。","voiceIndex":119,"id":"exchange-050"},{"speaker":"伊藤委員","kind":"確認","question":"国際問題になったりすることはないと思うんですけれど、一応その確認。だから情報の集約をして混乱を避けるためにも、ここに書いてある甲の部分については、例えば品川区の防災課、窓口を一本にしていくとか、そういうふうにしていかないと混乱するのではないでしょうかということを確認したいんですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"３点ご質問いただきまして、まず１点目、区と協議をして、その後のお知らせだけでは、具体的に対応が間に合わないのではないかというご指摘ですが、ご指摘のとおり、実際の開設に当たりましては協議をしますが、あらかじめ実は事業者の方にのぼり旗のようなものを。","voiceIndex":121,"id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問・要望","question":"締結すること自体についてはもちろん進めてほしいんですけれども、相手の民間の方々の施設なりに迷惑がかからないように、区がリードしていっていただきたいのが一つと、それからそういう細かいことなんですけれども、大災害時の混乱する中で、品川区からですという要望を全部受け入れてしまうと、いろいろな考えをお持ちの方がいらっしゃるわけであるから、やはりこういう提携先との連絡を取り合うのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-052"},{"speaker":"原委員","kind":"意見","question":"つきとめていってしまうとそこまで行ってしまうので、こういうのは委員長がお詳しいと思うんですけれども、十分にその辺を配慮して、双方にとってやはり有益になるような形での展開をお願いしたいと。なぜ建設委員会でこういうことを申し上げて、ご返答は要らないと言ったのは、多分これは総務委員会の話だと思いますので、一応そこだけお願いをしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"災害時の相互連携というのは、さまざま求められているし、これからも出てくると思うんですけれども、３ページ目に各分野別にまとめられているんですけれども、どこがどうというのではないですが、ここまで締結を進めてきたいとか、連携していきたいという目標があるのかどうか、それに対して今どういう状況で、どう評価をされているかというのが一点です。","respondent":"鈴木防災課長","answer":"それから区民の方への周知ですが、先ほど申し上げましたように、基本的にしっかりと対応するためには、協定を結んでいただいた方と連絡がとれるような体制は整えますが、それ以外にもご了解いただけたところにはＣＳＲ、地域への貢献というところもありますので。","voiceIndex":125,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"特に、今心配しているのは津波の対策の避難場所、その辺のビルとかマンションとか、その辺の協定というのはどれぐらい進んでいるのでしょうか。かなり心配な声を聞いているので、そこも含めて避難所の収容場所が増えることと、表示がしっかりされることを望みますが、いかがでしょうか。","respondent":"鈴木防災課長、奥田河川下水道課長","answer":"それから津波の対応についての協定ですが、河川下水道課と連携をしまして、津波についても協定のお話をするときに、特に沿岸部で高層の建物の会社の方には、そのお話もあわせてさせていただいておりまして。マンションなどにつきましても今、手続を進めておりまして、京急とか、高台にあるようなお寺とか、そういったところと協議を進めている状況です。","voiceIndex":127,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"それぐらいしておかないと多分その場ではいろいろ動きにくいだろうと思っているんですが、それに対してはどうされているのか。そうすると断らなければいけないというケースも出てくるのではないか。例えばトイレの問題は一番大きな問題ではないかと思うんですが、その辺のアドバイス等々、備蓄の中に入っているだろうと思うんですけれども、そういう具体的な運用については、どのようにされるんでしょうか。","respondent":"鈴木防災課長","answer":"それとあわせて職員も、全ての協定先に派遣できるものではありませんが、必要に応じてやはり派遣の必要があるということで、それも本部の中で、全体調整の中で対応する予定になっております。","voiceIndex":130,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"一点、区の指導のもとでということなんですけれども、本当につながるかなと。交通、電話もつながらないといういろいろな状況の中で、どうやってそれを伝えていくのかなと。そこがまず一点ですね。そうなったときにどういう、同じような想定をした訓練はできないと思うので、それをどうするのかなと。やはりどうしても協力していただけるところでの判断に任せるしかないのかなと。その対応はいかがですか。","respondent":"鈴木防災課長","answer":"条文にもうたってあるんですが、例えば一時避難施設の開設の場合も、基本的には区からお願いをして、要請に基づいて開いていただきますが、もし現場の判断で、つまり協定先のほうの判断で必要があると思って開いた場合には、事後報告をいただくことで。","voiceIndex":132,"id":"exchange-057"},{"speaker":"西本委員","kind":"意見","question":"一番心配なのは、せっかく協定を結んで助けていただいているというところと、うまく連携がとれなくなってしまって、逆に危険を伴うようなケースを伴うようなケースが出たりということは、一番避けなければならないと思いますので、今までいろいろな一次避難所に対する連携というのをやっておられると思うので、具体的に動けるように工夫していってください。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-058"},{"speaker":"こんの副委員長","kind":"質問","question":"それから７番の施設等復旧関連、ここの仮設住宅というところを一つとってみたいと思うんですけれども、これについてはいわゆる仮設住宅の提供を、復旧のときには必要だというところでは、民間の不動産業の方との提携というのはどうお考えですかという、この２点をお願いします。","respondent":"鈴木防災課長","answer":"機会はいろいろあります、区の総務課でやっていますＣＳＲ推進協議会、地域貢献をするという事業者の方の集まりであるとか、それから区の防災関連の、訓練とか事業、そういうところで参加いただいた事業者とか、そういう方がご相談なり、もしくはご紹介なりをいただいたときに。","voiceIndex":135,"id":"exchange-059"},{"speaker":"こんの副委員長","kind":"質問","question":"協定の流れはわかりました。不動産業を申したのは、いわゆる仮設住宅というのは７自治体との協定も結んでいるところですけれども、民間の空いている部屋、いわゆる空き室というところが多く社会的にあるので、そういった活用ができればいいのではないかという発想から、今申し上げました。そのところはどうですか、ご答弁があればお願いしたいと思います。","respondent":"鈴木防災課長","answer":"そうですね、仮設住宅の確保の中で、民間のいわゆる賃貸住宅があいている場合のケースですが、それにつきましては区のほうとしても借り上げ型の応急住宅ということで既に想定しておりますので、具体的に今、確実に提供いただくという協定まで至っているところはないですが。","voiceIndex":137,"id":"exchange-060"}]},{"id":"topic-06","title":"前回は被害想定","agenda":"前回は被害想定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今日初めて見せていただいたんですけれど、このソフトはいつ買われて、どの範囲のシミュレーションをされているのか。今回はここの二葉と豊町の多分一番木密で危険であると思われる地域だと思うんですが、ここの６時間のシミュレーションをしていただいたんですが、全体的にはどういう状況になっているのか、教えてください。","respondent":"品川木密整備担当課長","answer":"シミュレーションソフトのほうは、大体２カ月前ぐらいに入ってまいりました。それまでにやはりこのシミュレーションソフトの中にデータを入れる作業、これがかなり時間がかかって、２カ月ぐらい前に導入ができたという形になってあります。","voiceIndex":147,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"質問の中には、今回、きょうのために、これ１カ所だけをシミュレーションして、ほかはしていないという理解でいいんですか。","respondent":"品川木密整備担当課長","answer":"シミュレーションというよりも、このソフトが入ってきましたので、ソフトが確実に動くか等のテストといいましょうか、そういった形では品川区内のいろいろなところで発火点をおきまして、シミュレーションはかけております。","voiceIndex":149,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"最後のシミュレーションを「かけています」ということは、もう具体的にこういう紙ベースでいつでも見られるということですか。特に補助２９号線だったら全体像が見られるということですか。きょう、なぜこれだけなのかなという思いがあるので。","respondent":"品川木密整備担当課長","answer":"事前にちょっと何カ所かはやっていますので、別の場所で少し見せる……。","voiceIndex":151,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"意見","question":"いや、見なくてもいいんです。どう把握されているのかというところがまず知りたかったので。","respondent":"品川木密整備担当課長","answer":"補助２９号線の沿道３０メートルを耐火建築物という形でシミュレーションをかけますと、どこの部分でやっても火が、補助２９号線でとまるというような形では、確認はしております。どこでもというか、かなり複数箇所やりまして、遮断するという形では確認しております。","voiceIndex":153,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きょう初めて見せていただいたので、品川区も本気で実態を把握する気になったのかなというところにおいては、活用していただくのと、実態を本当にしっかり伝えていただきたいし、質問もしていきたいと思っていますけれども、きょうのこの６時間で、この補助２９号線が引かれない、整備前の焼ける棟数と、整備された後の違いを具体的にわかったら示していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"今までは延焼遮断帯の効果を示すのに、東京都のシミュレーションをずっと出されてきたわけですけれども、東京都のシミュレーションとこのシミュレーションの関係を、どう捉えていいのか教えてください。","respondent":"品川木密整備担当課長","answer":"延焼遮断帯ということで、道路まで火災が行かなければ当然効果がないというのは、もうご理解いただけるかと思うんですが、木密地域不燃化１０年プロジェクトの中では不燃化特区というのを置いていまして、特にこういう燃えやすい地域に対しては、古い老朽住宅ですね。","voiceIndex":158,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"一つは、その違いですよね。耐火で固まっているという違いを、どう説明、これでやっていけば大丈夫ということなんでしょうか。やはり区民に明らかに、まちの姿が違いますよね、それをどう説明されるのか、ちょっと聞かせてください。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"要するに補助２９号線をこれから進めていくに当たって、沿道３０メートルについては防火地域に指定しようということを考えております。今のにちょっとつけ加えますけれども、防火にするということイコール高い建物を建てるということではございませんので、現状の建物の高さで防火にしていく、そういったことも含めて防火にするという意味ですので。","voiceIndex":160,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"その２点につけ加えて、この間ずっと指摘している車両火災、車両が一切このシミュレーションでは検証に入っていないということと、火の粉の問題も入っていないということにおいては、本当にきょう示されたのは絶対でもなく、ほんの一例、シミュレーションのデータを入れた一つの例であって、もっといろいろな想定があるというもとにおいて考えなければいけないのではないかと思うんですが。","respondent":"品川木密整備担当課長","answer":"というところから考えれば、不燃化特区というような制度を入れて、今進めております中で、木造住宅を準耐火建築物、耐火建築物に替えることで、火の粉というのは押さえられるというふうに区のほうでは考えております。","voiceIndex":163,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"車両火災なんですが、私、何も金沢大学の教授の話もきょうは言っていません。１人や２人ではありません。そういった心配を抱えているという認識をまず持たないと、沿道がどうあれ、道路自体が燃えるんですよね。私たちは倒れない、燃えない家づくりに個々の木造住宅、マンションなどにかけるお金のほうがずっと安くできるという試算をしているんですが、その辺はいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"仮にこれで戸越公園がもう少し避難人数の収容ができるようになれば、この補助２９号線は非常に、広域避難場所に行くまでの道として効果的であるというふうに我々は考えております。","voiceIndex":165,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"出火点は一つの想定ですから、出火点が変われば道の反対側も燃えますよね。だから出火点によって変わる、風向きによっても変わる、道路の車の量、火災の状況によっても変わる、でも一つ示した部分ではこれだけのものが燃えてしまうということで、延焼遮断帯、このシミュレーションではこちらは大丈夫だけれど、これを絶対に効果がありますと言い切れるんでしょうか。私は必要のない道路であると思います。","respondent":"品川木密整備担当課長","answer":"それから残地の点ですが、こちらは委員おっしゃるとおり、道路を通しますと残地というのは残ってしまいます。この点につきましてはやはり区民の皆さんと話し合って、区民の皆様が納得いくようなまちづくりをしていきたいと区としても考えております。","voiceIndex":169,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"意見","question":"はい、最後に。きょうのご説明でも、まず道路先にありきで、両側の沿道の開発を推し進める計画であるというふうに思っています。私は区民の命と財産を守るためには、まず住宅、マンションなどもそうですが倒れない、燃えない家づくりにこそ、この道路に係る予算を使って、面的にもっと安全なまちをつくるべきだと思います。意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これだけの火災が起きるということは、大災害ですよね、間違いなく。その客観的なデータからすると、たしか関東大震災と阪神・淡路大震災では燃え広がり方が１００倍違った。だからきょうもその一つをここで示していただいたのだけれども、シミュレーションの形は目的を越えないので、過去の地震の実例を学んだ上で、確かにこれは延焼遮断の効果があるということの答弁をいただきたいんですが、いかがですか。","respondent":"品川木密整備担当課長","answer":"国や民間の方、本当にそういう防災に関する知識人が集まってつくったソフトです。こういうソフトの中で延焼遮断効果があるということで、区としても効果があるということを目途にしながら、これからの防災まちづくりを進めていきたいと考えています。","voiceIndex":173,"id":"exchange-072"},{"speaker":"伊藤委員","kind":"質問","question":"だけれどそれを今、こういうシミュレーション上で表現できるような、学術的なものは確立されていない上では、それは不確かな情報を載せることは我々として逆に無責任だと思うので、むしろ今ある現状の式を最大限活用しながら、ここにあるように約１,４００棟ぐらいがこのシミュレーションでいうと燃えないわけだから、そちらのほうに価値を置く政策を展開していくべきだと思うんですが、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"これが崩れてしまうと、瓦れきという形になってしまってすぐに火がついてしまうようなことになります。こういった形で区民の皆様ができるところまで、そして区のほうもそれに援助するような形で総合的な防災まちづくりを進めていきたいというふうに区としては考えております。","voiceIndex":175,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問・要望","question":"都市部においての一番心配事というのは、火災だと思うんですね。それをこういう３・１１とか含めて延焼遮断とか含めての目的に絡めて、そういうふうにやっていくということについては、ご理解いただける部分はあるのではないかと思うんですね。そこの、今までたくさんの地域で説明会をされているんですけれども、実際に該当する方たちはどういう反応かというところはいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"各地区でまちづくり協議会、木密の説明会等、特区のほうの説明会をこれからやっていく予定なんですが、そういったところでは非常に活用していきたいと考えています。","voiceIndex":178,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"それで気になるのは、これで延焼遮断になるのかというような議論になったとき、そういう説に対して私が言いたいのは、じゃあ、どういう方法があるんですかと。そこまで責任持てるのですかというそれぐらい、やはり行政側としてもはっきり言っていいのかなと思うので、うまくこれを使いながら、啓発活動も含めて活用していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういうまちにしていくことと、地域のコミュニティーを壊さないで初期消火の体制がしっかりできる、スタンドパイプとか街頭消火器を使える、上水が断線しないで水がちゃんと出て、地域の消火ができる、そういったまちをつくっていくことこそ、私は東京都の計画だと言っている品川区みずから、品川区が一番できることを真っ先にやるべきであると思いますが、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"そういうところの中で、総合的に進めていくということで、区として進めていくものですので、そこのところをぜひともご理解いただきたいと考えています。","voiceIndex":181,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の方は納得していません。この間、学習会をやると言われていたのに、学習会は立ち消えていますよね。幾つかの地域からもっと話を聞いてほしい、意見を聞いてほしいと言われていますけれども、都のほうも区のほうも、その実現がなっていないので、ぜひお約束いただいた地域の住民の方の学習会とか、出向いてくださると言っていたので、ぜひ実現をしていただきたいんですが、最後にお願いします。","respondent":"藤田都市計画課長","answer":"その中で今、東京都と連携を図りながら地域の勉強会等についても考えるべきということで、今行っております。可能なものについては参加についても考えてありますが、東京都のほうも品川区だけで実際に９個のエリアについての説明会を今、行っている状況です。","voiceIndex":183,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"エリアが広くて大変だと思いますけれども、ぜひ求めていますので、１回の全体的な説明会だけで終わらせることなく、学習会等に出席をして、お話を聞いていただきたいと思いますので、よろしくお願いいたします。","respondent":"藤田都市計画課長","answer":"可能なものについては、実際には個々にお話を聞いたり、そういったことも可能ですので、できることを少しずつ、少しでも早くやっていくのが現実的かと考えています。","voiceIndex":185,"id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":70688,"voices":190}},{"id":"h25-20131105-9","meetingId":"h25-cm11","date":"2013年11月5日","dateIso":"2013-11-05","committee":"文教委員会","time":"午後 １時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２５年度小・中学校移動教室実施結果","agenda":"平成２５年度小・中学校移動教室実施結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、最後に説明された伊藤学園の４年生との共同実施というのは、ちょっと今までにあったのか、なかったのか。私は初めてのような気がしたので、共同実施という内容と、なぜそういうふうにしたのかという、そのあたりのことを教えてください。そのあたりで学校が特別の目的意識を持って実施されたんだろうと思うんですけど、そのあたりのことをちょっと教えていただきたいと思います。","respondent":"和氣学務課長","answer":"４年生と７年生、５年生と８年生、それぞれで実施してございまして、お互いのそれぞれが発達段階でいろいろかかわりを持つわけですけれども、特に異学年交流ということで、それぞれの学年に応じて指導していく上で、４年生・７年生で１回やって。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"あまり詳しいことはわからないので、それ以上の質問はできないんですけれども、異学年の交流というだけじゃなくて、そういうふうに設定した学校側の目的、意図というんですか、何をどこまでどういうふうに到達させたいと思ってこういう組み合わせにしたのかというところも含めて、それなりに教育的な効果はあるんだろうというふうに思うので、否定する意味での質問ではなくて。","respondent":"渋谷指導課長","answer":"４年生、５年生でお世話をされる立場になった子どもたちが、逆に今度は７年生、８年生でお世話をする立場を経験するということで、またそこでも新たなリーダーシップの育成だったりにつながるということで、品川学園が一体型になる前も、台場小学校、品川小学校。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そうしますと、移動教室という位置づけですよね。だから、費用的には学校側の負担になるということですよね。ここの学年も、また今まで過去にやられていた事業も、そういう費用の部分でのところがどういうふうになっているのかを教えていただけますか。","respondent":"和氣学務課長","answer":"４年生については、基本的に支給対象ではございませんので、私費になります。ただし、亀山少年自然の家も含めまして、経費は本当に寝室代と食費の実費ぐらいで済みますので、大変安い経費で、バス代ぐらいしかかかりませんので、それほど大きな負担ではないです。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"平成２５年特別区および東京都人事委員会勧告の概要","agenda":"平成２５年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この給与の改定というのはどのくらいの期間、ずっと引き下がっているという気がするんですけれども、何年ぐらい下がり続けてきているんでしょうかというのが１つ。そういう点で、ちょっと先ほどの、どのくらいの年月引き下がり続けているのかというのをちょっと改めて確認しておきたいと思います。","respondent":"渋谷指導課長、田村教育次長","answer":"正確にはちょっとわかりかねるんですけれども、一応今、手元にある資料を見ると、２００２年ぐらいからマイナスになっているのかなです。ですから、それの反射的な影響で需要が拡大しないという問題はあるかもしれないですけど、制度がそういう制度なので、それに沿って進めていかざるを得ないと私どもは考えています。","voiceIndex":15,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"公務員の待遇に関する人勧制度というところでのその話は承知した上で質問しているんですけれども、やはり１１年間下がり続けてきているというのは、これは民間全体がリストラだとか、ボーナスを出さないと、そういう状況の中で比較されて公務員が高くなっちゃったという話の中でのことなので、やはり経済全体を底上げしていくことが、今とりわけ日本社会は求められているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ特別区人事委員会や東京都人事委員会の勧告はやはり重く受けとめて進めていくべきだと思います。人事委員会の勧告ですから、そこまで把握していなければいいんですが、何か生活ステージ、年齢が上がると下がっていく部分の加算措置のあり方、何か意見があれば教えていただきたいなと思うんですけど、その２点お願いいたします。","respondent":"渋谷指導課長、田村教育次長","answer":"２点目の若い人に厚くというふうな部分については、では、次長のほうから。先ほどの人事委員会勧告の資料の中の１ページのところの１の月例給で、公民較差でＩ類初任給までの号給等は据え置きと書いてあるように、要は若い人たち、優秀な人材をとる。","voiceIndex":19,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"さっき言い切れなかったんですけども、そもそも国家公務員の賃金を削減するというところがまず冒頭にあった。そういうことでなっていくと、さっきも言った話に戻るんですけれども、繰り返しになるから言わないですけど、全体の経済が落ち込んでいくというところにもつれ込んでしまうという危険性を非常に強く感じるものですから、さっきのような発言と質問をさせていただいたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"}]},{"id":"topic-03","title":"認可保育園の新規開設および移転","agenda":"認可保育園の新規開設および移転","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、最後に不足分とおっしゃったんですけど、あった場合のというそういうことなんでしょうか。それとも今からもう不足というのはわかっているのかなと、ちょっとそのあたりがわからなかったので、今の説明されたところをもう一度伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"予算につきましては、当初、予算では３園の開設を予定しておりましたが、人数等の過不足もありますので、またこちら、区内私立保育園経費ということで移転経費、運営経費ともに大きな予算を抱えておりますので、その経費の中で。","voiceIndex":29,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"さっき聞けばよかったんですけど、例えばアンジェリカはまかわというところは、単独の施設だったんですね。あるいはどこかのビルの１階なり、どこかのフロアーを使っている保育園があるのであれば、どこなのか。そのあたりを教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最後、アンジェリカ東品川保育園につきましては、こちらはビルインで既存の建物の中の１階に建てますので、外で少し遊びスペースはありますけれども、屋外遊戯場という形ではございません。","voiceIndex":31,"id":"exchange-009"},{"speaker":"南委員","kind":"確認","question":"委員長、確認なんですけど、グローバルキッズ中延園というのは単独の施設ということでいいわけですね。戸越ひまわりも含めて。","respondent":"今井制度改革・待機児童対策担当課長","answer":"大変失礼いたしました。今、２点のご質問にお答えいたします。グローバルキッズ中延園は、駅前に建ちますビルの２階部分にありますので、ビルインですので屋外遊戯場はございません。","voiceIndex":33,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"大崎ひまわり園の定員増も含めると３００人以上、保育園の定員が増えるということで、これ、いつぐらいから検討というか、開園に向けての準備というか、話というか、そういうものが始まっていたのかということと、あとこの４つの新設される場所ですね。それから、大崎ひまわり園につきましては、跡地はどうなるのかということで、何かしら情報があれば教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長、立川保育課長","answer":"最初にこちらのほうの保育所の開設の検討時期ですけれども、それぞれに異なってまいりますけれども、一番早いところでは１年半以上前からお話が来ていて、場所等を含めて検討していたところでございました。戸越ひまわり保育園の跡地利用ですが、こちらにつきましては、区全体、こども未来事業部ということではなくてで、区全体で総合的に検討しているところがあります。","voiceIndex":35,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうすると、１年半ぐらい前から、直近だともうちょっと年内に入ってから始まったりしたものもあったのかもしれないんですけれども、この開設に向けての周知ですね。もう保育園の申し込みがそろそろ、皆さんいろいろ、親御さんたちはどうしようかということで悩み、いろいろ希望を考えていらっしゃるかと思うんですけれども、どういう形で周知されていくのかをちょっと一応確認させていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"例年１２月１日の広報、そして保育園のご案内なども４月１日向けにつくり直しまして周知をしてまいります。","voiceIndex":38,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"それはいわゆる保育園に預ける年代のお子さまを持っている方全員に何かこう、個別配付みたいな感じで周知されるようなものでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"既にお申し込みをいただいている、今年度ですね、今年度というか来年の４月までお申し込みをいただいている方がいますので、そちらの方には改めてあわせて周知をしてまいります。","voiceIndex":40,"id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"いわゆるこの３歳児、４歳児というところの定義もあるので、近くにできたので転園したいという方々に、広報等があれば、一応広報しながわなんかでは気がつかれるかなと思うんですけれども、今、保育園に通っている方々にも一応は全員にお知らせするような形はとったほうがいいのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"１つ目は４番のアンジェリカ東品川ですが、３歳児～５歳児が４人ほど定員的には少なくなっているんですけれども、３歳児～５歳児というと幼稚園も含めて窓口がいっぱいあるので、そういうご希望の方もいたらということでのこういうことなのかなと、ちょっと勝手に想像しているんですけど、区のほうでこういう形で認可というんですかね。","respondent":"今井制度改革・待機児童対策担当課長","answer":"昨年は、出生数も品川区は大変伸びたところですので、その出生数と待機増から見た待機児童の状況が今年は伸びたわけなので、ちょっと３００ではまだ少し、もう少し認証保育所ですとか、家庭的保育事業などから。","voiceIndex":43,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"そのあたりをちょっともう一度伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後１２月に、今年度にまた来年度の見込みを立てておりますが、来年度につきましては、やはりどうしても待機児童というと０歳児、１歳児のところがありますので、やはりそこは認可保育園だけでは、まだ施設としては受けとめ切れないというふうな認識でおります。","voiceIndex":45,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういうので、例えば定員が９人であっても、９人全員入れるとは限らないというそういう現状もあるわけですよね。民間の事業者だったら当然それは考えますよね。私はあまりないんじゃないかなと思っているんですけれども、もしあったら教えていただきたいんだけれども、なければやはり区がつくるという、そういうことを真剣に考えるべきだと思うんですが、そのあたりについてはいかがでしょうか。","respondent":"今井制度改革・待機児童対策担当課長、金子こども未来事業部長","answer":"平成２５年度につきましても、二葉すこやか園や平塚すこやか園、幼保一体施設の計画的な整備を進めて、区としても整備を進めてきたところです。来年度も今の段階でこの新しい４つの保育園と１つの保育園を移転、拡大するということをお示ししましたけれども、平成２６年度の中でさらに開設できるか、あるいは平成２６年度の中で認証保育所、それから、家庭的保育事業も含めまして。","voiceIndex":47,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"区が一生懸命努力していただいていることはわかるんですけれども、保育ママというのは０歳児、せいぜい１歳児くらいでしょう。そういう人を一人も残さないという、この姿勢にしっかり立つべきだというふうに思うんですね。答弁をここで求めても同じですから求めませんけど、強く要請したいと思います。来年度はぜひ待機児解消を、「万歳、できた」と言えるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、ここには児童会とか生徒会活動と位置づけてあって大事なことだというふうに思うんですけども、現実的に学校の中の教育活動の中で、私はこれ、１ページに書いてある市民科のところの下のほうで、特別活動というところでいろいろなテクニックを教えるんだみたいなことが書いてあるんですけど、それと同時に、やはり小学校は小学校なりの児童会というか全体でどういうふうに話し合って。","respondent":"渋谷指導課長","answer":"ちょっとこれもすごくわかりにくい説明になってしまうんですが、学校現場における標準授業時数というのは、１年間を３５週というふうに考えて授業時数を計算している。","voiceIndex":57,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう一つは、４ページ目の将来設計領域というところの右側にあって、社会認識能力の中で、望ましい職業観や経済・金融の仕組みということで、経済・金融というのがちょっと私の中ではふうーんという、この市民科という中で、特別にこの経済・金融というのを取り上げて授業をするというところのねらいが何なのかなというのがちょっとありましたので、ちょっとその辺を詳しく教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"先ほどちらっとお話ししましたが、例えば合唱コンクールに向けて、例えばパートごとに分かれて練習をするときに、友達との協力をすることが大切だとかというような人間関係に関するステップ１、ステップ２を踏まえて、ステップ３で練習を、例えばリーダーシップ。","voiceIndex":59,"id":"exchange-020"},{"speaker":"本多委員","kind":"質問・要望","question":"よく小学校の卒業式とかで、将来私は何になりたいですよというのを聞いていると、すごい主体性のある子とそうでない子、あっ、あの子が例えばパティシェと言ったら、何かパティシェが何人も続くような傾向があったり、本当に最終的には主体性というんでしょうか、個々の我が本当に生き抜く力というのを身につけるというか、自覚とか意識をしてもらいたいんですけれども、その辺の基本的な挨拶の部分と。","respondent":"渋谷指導課長","answer":"自分がこういうものになりたい、こういう方向に進みたいというふうなことをしっかりと自覚できた子どもはすごく伸びるので、これはまだまだ市民科も完璧なものではございませんので、そういったしっかり子どもが主体的にみずからの将来について考えて意思決定できるような。","voiceIndex":63,"id":"exchange-021"},{"speaker":"高橋委員","kind":"確認","question":"その一方で、児童生徒が聞くだけで終わったり、あとワークシートを書いているんですけど、この単元で何を勉強したかというのがオープンエンドならいいんですけど、そうじゃなくて、確認できないものというのかな、みんなどういう意見がある、こうだね、こうだねって、こういう表情には気持ちをあらわすからこうですよみたいなので、そこで終わっているというか、後で評価の話になるんですけど。","respondent":"渋谷指導課長","answer":"一方で、家庭のステップ４のところで、実際朝起きて、おはよう、お休みなさいと挨拶ができたかというのは、お母さんにチェックしてもらったものを子どもが自己評価するのをチェックしてもらって、それを学校の担任の先生がチェックをして。","voiceIndex":65,"id":"exchange-022"},{"speaker":"高橋委員","kind":"質問・要望","question":"評価のところはやはり、何となくなんですが、授業公開、先生方はとにかく授業をやるのに一生懸命で、その時間内に終わったというんじゃないんですけど、それはそれなりの結論が出て、きちんとした形になっているんですけど、その後どれだけ児童生徒に残っているのかというところが、先ほどお話があったように、アンケートがいいのかどうかちょっとわからないんですけれども。","respondent":"渋谷指導課長","answer":"そういう変更で時数の調整をしています。","voiceIndex":67,"id":"exchange-023"},{"speaker":"高橋委員","kind":"意見","question":"そうすると、時数の調整だということですね。ということは、中身は、本当の柱は変えていないということ。ということは、そこでの対象としてこれまでのこの中身、大きな柱についてはきちっとしていただくということがあるわけですね。外部評価。外部の方の声、もし、おわかりになれば。","respondent":"渋谷指導課長","answer":"外部の方々からの評価で、直接私が何かここ何年かで携わったことはございませんが、例えば７月でしたか、道徳の教科化にかかわって、前の教育委員の細川先生からお答えをかけていただいて、文科省のほうに行って、今ご説明したような品川市民科の取り組みについて。","voiceIndex":69,"id":"exchange-024"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"先生方同士で授業の見学等をし合いながら、市民科の授業の内容の充実を図っていくとか、そういうことがあったら教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"教育委員会としては、これは当初からですが、ほかの区から来ると、えーと思われちゃうんですけども、赴任した２日目だったり３日目に、新補・填補の方を集めて、最初に市民科のコンセプトをきちっと理解いただくような研修をし、さらにまたその１ヶ月後に。","voiceIndex":71,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4806#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":44942,"voices":80}},{"id":"h25-20131105-5","meetingId":"h25-cm11","date":"2013年11月5日","dateIso":"2013-11-05","committee":"総務委員会","time":"午後 １時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"担当課長の設置","agenda":"担当課長の設置","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オリンピック・パラリンピック調整担当課長は、行財政改革担当課長が兼務されるということで、任務がさらに増えて、ご苦労さまですということなのですけれども、そして、その中で、この担当ができるということは、担当に配置される職員というのはどのようになるのか、職員の配置について、両方あわせて、わかったら教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"職員につきましては、現段階ではこれに対する特別な配置等々は考えてはございません。ただし、これから東京都や国の動き、今後７年間、また動きが大きく出てくると思いますので、そういった動きを見ながら、そういった時期に必要な場合は検討していくことになろうかと思います。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"平成２５年特別区人事委員会勧告の概要","agenda":"平成２５年特別区人事委員会勧告の概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、今回の引下げでは、国家公務員が復興財源の確保というところで引き下げられたのがあると思うのですけれども、それとの連動というか、関係というのはどうなのかということについてもお聞かせいただきたいと思います。とりあえず２点お願いします。","respondent":"堀越人事課長","answer":"実施されてきたところ、平成２１年に国において、自宅にかかる住居手当の廃止を行いまして、今、全国の自治体の中でも約６割程度が自宅にかかる住居手当を廃止しているという状況にあります。","voiceIndex":12,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"優秀な人材を確保するという、こっちの雇う側からすると、そうだと思うのですが、生活する職員の側からという観点でも、月額そのものを引き上げていくということも必要なのではないかと私は思いますけれども、そこはペンディングにしておきます。","respondent":"堀越人事課長","answer":"国につきましては、実際比較するときに、今、給与減額をしているということで、減額前の給料で計算した結果を用いまして、減額前と比較した結果が０.０２％ということですので、その結果を見て、改定を行わないという形で、実際にそういう形で国では判断しているです。","voiceIndex":14,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今回の特別区人事委員会勧告の中身というのは、例年の民間との較差を解消するというところで出されてきていると捉えていいのかということを、ちょっと確認をお願いします。そんな中で、職員の頑張りに支えられて、区役所業務が成り立っているというのが実態なのではないかと思うのですけれども。","respondent":"堀越人事課長","answer":"市場原理による給与決定は困難であるとか、一方で、職員は勤労者ですので、適正な給与を確保していく必要があるということ、そういう中で、やはり民間の情勢と均衡を図っていくというのが当然あるべき姿だと思っていますので、今お話がございましたけれども。","voiceIndex":16,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に賃上げこそが日本のデフレ不況からの脱出というところで、民間の賃上げも求め、さらに公務員の賃下げはしないということでぜひやっていただきたいと、私は意見として申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"新たな住宅手当制度ということで出ているので、ちょっと気になったのですけれども、昨年の勧告には、状況を考慮して検討するとあったのですけれども、状況を考慮してやられたと思うのですが、これは公民較差の中の数字に入っている額なのか、それとも外なのかということをちょっと教えていただきたいのです。","respondent":"堀越人事課長","answer":"今お話がありましたように、昨年の勧告において、あり方について検討していくという旨の言及がございました。","voiceIndex":19,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"もう一つですけれども、人事制度、勤務環境の整備等に関する報告の中で、１番目の１の(2)、受験者獲得策の強化ということで、特に技術系の職種についてのことが記載されていますけれども、技術系の方を採るというのは、品川区としても結構難しいのかなと、これを読むだけでは感じるのですけれども、昨年の人事委員会勧告を読みますと、職務の意欲等を的確に伝えるなど。","respondent":"堀越人事課長","answer":"来年度に向けまして、試験のいろいろな、本人の負担等も考えまして、今、１次試験ですと、択一試験の中で知能分野、知識分野のいろいろな出題の割合等もありますので、多少細かい話になって恐縮ですが、その中で選択しやすい形での改正等を検討しているという話も聞いてあります。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今の浅野委員の質問と似たところもあるのですが、聞き洩らしたかもしれないので、もう一度お聞きしたいと思うのですが、月例給は公民較差を解消するという理由でこういうふうになりました、特別給もこういうふうになりました、しかし、新たな住居手当制度については、公民較差は実際あるのか、ここには何も載っていないということで非常に矛盾を感じるのですが、片一方は下げるならば。","respondent":"堀越人事課長","answer":"給料とボーナスにつきましては、この後、組合交渉とかがありますけれども、例年どおりのスケジュールでいけば、１１月下旬に妥結して、また条例改正をお願いして、来年、年明けに改定後の給料で実施という形で考えてあります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"聞きたかったのは、そうやって公民較差をなくすということで、バランスで動いているのはわかるのですが、ところどころこういうふうに手当が増額したり、また引下げを緩和したりということになると、そこら辺、全体として矛盾が生じるのではないか、その辺についてちょっともう一回。","respondent":"堀越人事課長","answer":"矛盾が生じるのではないかというお話ですけれども、そういう形ではなくて、全体として０.１４％を解消できるような形にしまして、その後、各職員の給料表の級ごとの配分につきましてはそういう形で少し差を設けて、全体としては公民較差を解消するという形で。","voiceIndex":26,"id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"民間会社の一部は除いて、一部は確かに厳しいところはありますが、そうすると、採用に対してはもう十分優秀な人材が来ていると思うのですが、人事委員会の勧告も勤務環境の整備等に関する報告もそうなのですが、ちょっと矛盾しているのかなと思うのですが、その辺について、ちょっとご見解をお聞かせください。","respondent":"中山総務部長","answer":"人事委員会勧告の考え方の中に、国家公務員の給与水準のような官民較差はかなり分析して、ある種、その時々の緻密な分析の中で修正するということと、もう一つ、特別区、あるいは品川区にとっても、組織として望ましい給与なり。","voiceIndex":28,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つ、４ページの勤務環境の整備なのですが、メンタルヘルスの推進、超過勤務は一部の方にはあると思うのですが、これはそれなりの残業手当、振替休日等はとっていると思うのですが、メンタルヘルスに関して、これは民間でもそうですが、今や公務員、この品川区役所においても、さまざまなメンタル的な問題で休まれている方が少しずつ増えている、また、下がるということがなく、そのままずっと増え続けるか。","respondent":"堀越人事課長","answer":"予防するというものです。もし、メンタルヘルスで不調を訴えた場合には、適切な対応をしていくということと、今後再発を防いでいくという考え方が大きくありまして、先ほど申し上げました若い職員、新規採用職員からそういった形での研修をしております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に意見だけ、人は宝なので、品川区にも優秀な人材がたくさん採られていると思います。管理職の方が適宜、個人とちょっと話をしたり、頻繁に話をして、何とかそれを早期に解決して、本当に優秀な管理職に育て上げるように努力していただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"}]},{"id":"topic-03","title":"平塚橋会館・シルバーセンター・西中延区営住宅解体工事請負契約","agenda":"平塚橋会館・シルバーセンター・西中延区営住宅解体工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この解体工事というのは、いつから始まって、近隣への説明会とかはいつごろされるものか、わかったら教えてください。","respondent":"小林施設整備課長","answer":"解体工事説明会につきましては、１０月１８日に実施したところです。工事の着手につきましては、１１月１日から着手しております。","voiceIndex":37,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"今回解体ということですけれども、４ページの上にもあるのですけれども、交通誘導員をここに置かれるというふうに見えるのですけれども、交通誘導員の役割というのは、ここが通用口になっていて、例えば、そこから車両が出たり入ったりというところを想定されているのか、それと、税務署のほうにも交通誘導員というのがあって、ここも確かに門がありまして、ここからの車等の出入り、まあ。","respondent":"小林施設整備課長","answer":"これは２カ所書いてあるのですが、原則、補助２６号線の北というか、右上が搬出入の出入り口、メーンゲートになっております。基本的には、補助２６号線から出入りしております。","voiceIndex":39,"id":"exchange-014"},{"speaker":"浅野委員","kind":"確認","question":"補助２６号線がメーンとなっているということで、税務署側がサブということで、それほど大きい車が出入りすることはないということでよろしいのかということを１つ確認したいのと、私の記憶によりますと、この補助２６号線は、たしか両側が荏原平塚学園の通学路に当たっていると思うのです。","respondent":"小林施設整備課長","answer":"１点目のご質問の税務署側は、基本的にはここの出入りはいたしません。通学路の質問ですが、通学路については、８時から８時半の朝の部分については、現場の車については出入りいたしません。あくまでも子どもを優先しております。","voiceIndex":41,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"学校側と何らかの形で調整とか、父兄への説明会とか、やっていないのであれば、これからだとは思うのですけれども、スタートするのですよね。そういう関係はどうなっているでしょうか。","respondent":"小林施設整備課長","answer":"学校とは綿密に打ち合わせをしております。今回の工事説明会も目の前の荏原平塚学園の校舎をお借りしまして、そちらで工事説明会を開いたところです。ＰＴＡについては、学校のほうから周知徹底を図ってもらうようなことでやっております。","voiceIndex":43,"id":"exchange-016"},{"speaker":"浅野委員","kind":"意見","question":"事故というのは、これだけは何が起こるかわからないということもありますので、工事関係者も含めて、安全確保に努めていただければと思います。騒音の問題もありますので、なるべく静かに、学校のほうまで聞こえるというふうになったら、大変なことになると思いますけれども、業者にも配慮をするようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"確認","question":"ちょっとお伺いしたいのが、先ほどの話で１１月１日から工事が始まっているということで、またこれからいろいろ大きな音が出て、ダンプの出入りも激しくなるのかなという中で、工期が来年３月３１日ということなのですが、説明もしたということですが、改めて確認なのですけれども、これからどんどん日が落ちて、せわしない１２月が来る中で、先ほど浅野委員からも話がありましたけれども。","respondent":"小林施設整備課長","answer":"１点目のご質問、交通誘導員の関係ですが、当然コンクリートのがら等の搬出時については、交通誘導員を増員いたしまして、２名態勢で行います。","voiceIndex":46,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問","question":"作業中、洗浄をちゃんとしていくというのですけれども、このエリアだと、４メートルの交通誘導員のところから入ったところで洗浄するのですか。よくそういった洗浄場というのは、別に設けたりはしているのですけれども、そういう記載がないのですが、どこで洗浄しているのですか。","respondent":"小林施設整備課長","answer":"場合によっては、ついたと仮定したときには、補助２６号線のゲートの手前に駐車場がありますので、わざわざつくるところは想定しておりません。ガンでタイヤを清掃して、確認ができた段階で補助２６号線に誘導するということでお話ししております。","voiceIndex":48,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"最近本当に多く見受けるので、そこはちゃんと指導していただくことと、あとは交通渋滞を巻き起こさないような誘導をするように徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"}]},{"id":"topic-04","title":"南品川四丁目で発見された不発弾の処理","agenda":"南品川四丁目で発見された不発弾の処理","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"不発弾が発見されてからこの爆破処理まで、本当に大変なご苦労だったとお聞きしましたけれども、今までにないような、災害対策基本法に基づいた対応という状況になったと思うのですけれども、この中でどういう検討がされたのかというところで改めてお聞かせいただきたいのですが、区の本部長以下区職員の２８０名というところなのですが、これは主にどういう課の職員がされたのかということと。","respondent":"工藤危機管理室長","answer":"現地は区の職員２８０名ですけれども、区の当日の業務はいろいろと指揮、情報や広報をする班、また避難所を運営する班、避難の誘導をする班、道路を規制する班等、それぞれ班体制を組みまして、そこのところから区の職員を募って対応したところです。これが現地の対応です。","voiceIndex":55,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"なかなかあることではないと思うのですが、前に不発弾処理計画というのもいただきましたけれども、ここの中でも、災害対策基本法第２条第１号の中にさまざまな問題についてというところがありまして、その中の爆発というのがここに当たるということで、市町村長の責任で住民の生命、身体を守るということで今回この対応をされたということなのですけれども、そういう点でいえば、防災対策というか。","respondent":"工藤危機管理室長","answer":"今回の部分をもとにまたいろいろと踏まえて対応していきたいと考えています。","voiceIndex":57,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とても丁寧にやっていただいて、終わった後でのさまざまな教訓というのをまとめて、次に活かせるようにぜひしていただけたらと思っているのですけれども、説明会にしても、個別訪問にしても、本当に丁寧にやっていただいたと思うのですが、この７００世帯、１,１５０人に個別訪問ということなのですが、これはどれぐらいの体制で、どんなに大変だったかというのをちょっと教えていただきたいのと。","respondent":"工藤危機管理室長","answer":"入院、もしくは入所しているという方が１６名、実際のところ、３７名中、特別な支援が必要な方が８名ということで、この８名に対してヘルパーを派遣したり、ショートステイの利用をお願いしたり、車で避難所に移動したりということで、個別に対応した。","voiceIndex":59,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"パイプ椅子で、ストーブを囲んでずっといるという感じで、避難所の中がちょっと寒々とした感じがしたということだったのですけれども、そこら辺の対応という点では、また２時近くになったにもかかわらず、食事も出なかったということなのですけれども、そこら辺の対応がもうちょっと、人数も結果的には、小学校の体育館は２３人ということでしたので、地域センターのほうはよくわからないのですけれども。","respondent":"工藤危機管理室長","answer":"ただ、お話にもありましたけれども、避難所の責任者もその辺は十分加味して、ストーブをすぐたいた、また毛布も配って対応したですので、私どもとしましては、限られた環境の中で最善を尽くしたとは思っております。","voiceIndex":61,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"避難までの事前の準備、個別訪問から、高齢者福祉課や障害者福祉課などとも連携しながらの全庁挙げてのさまざまなきめ細やかな、一人一人に対応するというところでの丁寧な対応ということで、ぜひここから震災対策にも教訓として活かしていただきたいということと、避難所では、これが震災だともっと大変になるところが想像されますので、そこら辺は今回の教訓も踏まえながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-025"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"数日前なのですけれども、故障車を運んでいる米軍の車両が、どうも道を間違えて入ってきてしまったみたいで、大崎高校の前から曲がることができなくて、ストップした状態になって、五、六時間ぐらいにわたってずっと車が通ることもできないし、大変な状況になっていたとお聞きしたのですけれども、この点について、一体どういう状況だったのか、自治体に何か情報が入っていたら。","respondent":"工藤総務課長","answer":"その結果、結論を申し上げますと、１３トンの車だということで、レッカー移動がなかなかできないということで、レッカー車がなかなか来なかったということで、警察で別の牽引方法で車両を受けて、道路から取り除いたということで、５時５０分だと思いますけれども。","voiceIndex":66,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"米軍ということで、意思疎通というのがすごく大変な状況みたいで、近隣の方も何が起こっているのかわからない、ただ、米軍だという状況なのですけれども、米軍が一般道を通るときというのは、そういうのは全く自由に通るという感じで、自治体への連絡とかもなくて通るのか、また今回みたいに事故が起きたときの対応というのも、どういうふうに対処されるのかというあたりは。","respondent":"工藤総務課長","answer":"そういった部分では、特に私ども品川区には報告はございません。ただ、今回の場合には、複数で通行していて、１つの車両が道を間違えて左に入ったという話は聞いております。","voiceIndex":68,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"英語を話せる方が近所から来られて、いろいろ聞いたところによると、海兵隊が富士の演習場に行くときに道路を間違えて、行き過ぎたのではないかということと、曲がったらということで、米軍の方と話をしたということもちょっと聞いたのですけれども、そういう状況というのは、区としては全く、今言われたようなことしかわからないし、米軍ということになると、全くわからない、事故が起こっても。","respondent":"中山総務部長、須藤委員長","answer":"ですから、基本的には、そういうものを一自治体として把握し、また住民に説明する必要はないと考えておりますけれども、警察を通じてとか、そういう情報が入ってくる部分については適切に把握していくと区としては考えているところです。以上でその他を終了いたします。以上で、本日の予定は全て終了いたしました。これをもちまして、総務委員会を閉会といたします。","voiceIndex":70,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":25492,"voices":72}},{"id":"h25-20131106-14","meetingId":"h25-cm11","date":"2013年11月6日","dateIso":"2013-11-06","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２５年陳情第１５号、東五反田４丁目の国有地活用","agenda":"平成２５年陳情第１５号、東五反田４丁目の国有地活用","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、この陳情に出ているように、グループホームを建設する際にはサービスコーナーや、公園とか多目的ルームとか防災施設のようなものというふうに、そこが趣旨なんだろうと思うんですけれども、実際この地域には、公的施設でこういうものをつくってほしいという趣旨に合致するような施設がどこにどれだけあるのか、そのあたりを教えていただきたいなと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらの陳情にあります、例えばサービスコーナー、地域センターのミニ出張所というような表現もされてありますけれども、こちらの地域ですと、大崎第一地域センターがまず西五反田の３丁目にあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"地域センターで戸籍にかかわること、住民登録だとか印鑑証明だとか、そういう事務をここではできるにしても、そのほかの図書のサービスも含めて幾つかはできるんですけれども、それ以外のことは区役所までおいでにならないとできないという関係もあって、利便性という点では一定の配慮があっていいんじゃないかなと思っているんですけれども、サービスコーナーの設置については。","respondent":"柏原行財政改革担当課長","answer":"サービスコーナーの部分ですけれども、今現在は大井町と武蔵小山のところにありますが、こちらにつきましては、例えば区民の方の利便性といったところを考慮しまして、区役所とか地域センターとか来るまでちょっと遠いであるとか、時間的なものを考慮いたしまして。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そういう点についての見解を伺いたいなと思います。","respondent":"柏原行財政改革担当課長","answer":"サービスコーナー等々における地域性の部分であろうかと思いますけれども、確かにそういった、例えばサービスコーナー的な行政サービスといった部分においては、地域センターが西五反田の３丁目にありますので、こちらに行くのはなかなか大変だろうという認識はしています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"これは当然といえば当然だと思うんですけれども、新しく国の土地を購入して、どこが設置主体かはまだわかりませんけれども、とにかく高齢者の施設をつくっていくという決断をされた時点で、そこの地域を、そういう計画を区が持ったんであれば、地域のニーズがある、そこのところをよくしんしゃくしていただいて、つくっていただきたいという趣旨ですから。","respondent":"柏原行財政改革担当課長","answer":"今後、限られた面積の中で、では何ができるのかというところになりますと、例えばグループホームという想定等々が今ありますけれども、そういったところで運営していかなくてはいけないといったことを考えたときに、こんな施設もこんな施設も入れるかというのは。","voiceIndex":12,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"五反田駅はエレベーターも設置されたんだと思うんですけれども、それでも乗りかえていくのは大変な一日仕事になっちゃうと思いますので、そういう点でぜひ、サービスコーナーについては区民全体に、年齢に限らず皆さん、全世代を対象にしたサービスですから、そういうことをきちんと受けとめていっていただきたいということを、強く要望しておきたいと考えていますけれども。","respondent":"柏原行財政改革担当課長","answer":"繰り返しになりますけれども、こちらは土地面積も小さい、それからグループホーム等々でやっていくために、ある程度制限といいますか、限られた延べ床面積を有効的に使わなくてはいけないといった部分がありますので、いろいろご要望等々はあるのだろうとは思いますけれども。","voiceIndex":14,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ地域ニーズはしっかり把握していただいて、それで検討していただきたいとさっきから繰り返しているので、これだけにしますけれども、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"幾つかお伺いしたいと思います。陳情にあるこの地域のエリアなんですけれども、陳情書に東五反田４丁目、５丁目および上大崎とある大体この地域のことを、この地域と呼ぶことにすると、先ほども近隣に公共施設が幾つあるか、どういったものがあるかという質問が出ていたんですけれども、計画も幾つかあるかなと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらにつきましても、例えば防災の倉庫的なものであるとか、子育て支援施設、それから行政サービス機能というのも検討の中に入っているところで、中身そのものの細かい検討は今後ですけれども、昨年でしたか、建設委員会等々でも。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"確かに今、陳情の出ているこの地域というのは、区役所から非常に不便な地域だと考えていますが、仮に目黒駅にサービスコーナー的なものができるのであれば、それはかなり改善されるかなと思うんですけれども、この計画について、ちょっと所管が厳しいところかもしれませんけれども、もろにかぶるところでもありますので、現段階での状況を教えてほしいと思います。","respondent":"桑村企画部長","answer":"前から目黒の辺につきましては、行政サービスコーナーの要求、ご要望があったのも私どもは知っておりますし、検討はしておりますけれども、正直言って、その意味での委員会報告をしているわけではございませんし、またやめるという報告もしていませんので。","voiceIndex":21,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"なので、私もこのエリアのどこかに行政サービスコーナーがあればいいなと思うのですが、それが五反田駅あるいは目黒駅といったところでご検討はしていただきたいなという気持ちは持っております。今の段階ではまだ建物もない段階で、そこまで確約するのは難しいかもしれないですけれども、その方向でも物を考えていただくことは可能かどうか、ご答弁いただけるでしょうか。","respondent":"柏原行財政改革担当課長","answer":"例えば福祉的な用途ということで、ある程度の幅が可能かどうかというのは、これからの国との話ですけれども、比較的そこは厳しめに国は考えているようですので、例えばグループホームと何々というふうにある程度明記した形で出して、それ以外の用途で使うと。","voiceIndex":23,"id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"一番基本的なところで、品川区の中で西というか北というか、北西に位置している場所ですよね。そうすると、ここの場所について、区自体は基本的にどういうふうに考えているか、まずお聞かせいただきたいんですけれども。","respondent":"柏原行財政改革担当課長","answer":"ちょっと抽象的な言い方になってくるかもしれないんですけれども、こちら、山手線の内側というところで、建物等々も大きいお屋敷があって、そういった地域であって、わりと静かな住宅街といった環境にあると思ってございまして、施設的なところで申しますと。","voiceIndex":25,"id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、これは私自身の感覚的なものになってしまうのかもわかりませんけれども、国もこれから高齢者向けの、厚生労働省が基本になって、２４時間のいろいろなセンター管理とか、いろいろ法律的なものも変わってくると思いますので、そうすると、今回当該物件、実際にＮＴＴ東日本関東病院がありますので、その辺との兼ね合い的なものができたならば、すごくありがたいなと思うんですけれども。","respondent":"柏原行財政改革担当課長","answer":"そういったところも踏まえて、そういった施設が足りないといいますか、ない地域でもございましたので、今回こういう物件が出てきたところを捉まえて、そういった面での重視といいますか、区としても一つそこにてこ入れができるのではないかと思いますので。","voiceIndex":27,"id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"これは聞くことではなくて、お願い事なんですけれども、うちの鈴木博委員もそうなんだと思いますが、どうしてもこういったケア関係というのは、区だけ単独ではできませんので、都とか国とかの関係等もありますので、そういう意味合いからしてでも、とにかく連除法的なものを含めて連絡を密にしていって、こういったものが高齢者とか福祉というところに貢献していっていただきたいなと切に願いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"このような形で、区民の方からも陳情いただいておりますけれども、ちょっと立ち返って、先ほど答弁もありましたが、高齢者施設ということで申請をされているということで、これが例えば要望のある多目的ルームとか、いろいろありますけれども、どこまで高齢者施設と、福祉施設と言えるかというところになってくると、かなり難しいだろうし。","respondent":"柏原行財政改革担当課長","answer":"はっきりしたボリュームチェック的なところは、まだ今の段階ですからなかなかと思いますけれども、机上の想定の中では２ユニットまでグループホームをつくったり、それプラスアルファの部分というのは何らかの制約をされるだろうとは考えてあります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"そうしますと、ここで入れるのかと言われると、ちょっと違うのかなという感じもしますし、また適地というものがそう簡単には出ると思わないですけれども、適地が出たときというんでしょうか、考えられるときに、また検討するというのも１つの手かなという気がします。そういう意味では、グループホームというのがこの場所にはよいのかなと考えます。そこは意見ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"渡部委員","kind":"意見","question":"１点だけです。８月１日の段階で、厚生労働省年金局から照会があったということで、私どもが２回ここで審議をしてきたと思います。行財政改革ですので。で、当然このような陳情が上がった経緯の中で、行政として８月の照会で、議会でもまだ２回しかできないような状況。ご地元の町会長ですとか当該地域に対して、そこの土地を取得しますよというようなアナウンスはかけましたか、かけていませんか。","respondent":"柏原行財政改革担当課長","answer":"例えば地元の町会長等々に、具体的にこういった形でということでの照会はかけてございません。","voiceIndex":33,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"もともとの報告事項にあった、この国有地の購入を基本とするという、ここについてもこの質疑の中で触れていいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"先ほど陳情だけだったので、こちらについて質問したいと思って手を挙げました。それで、購入するということは、私は前向きに評価して受けとめたんですけれども、同じ国有地でも、今回購入と決めたのはどういうことなのかなというのを聞きたかったんです。今回購入したというのは、そことの関係で、どういう判断で購入したのかなというのを率直な疑問として感じたので、それを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ちなみに南品川は、あちらの物件の対応は保育の施設ということで考えてありますので、今後の人口の動向であるとか、そういったところを考えたときに、定期借地という判断をしたところです。","voiceIndex":40,"id":"exchange-017"},{"speaker":"南委員","kind":"確認","question":"それと、今は購入を決定したというレベルなので、それ以上のことは聞いても、まだこれからだという答弁かなと思うんですけれども、事業主体というのはどういうふうに考えているんですか。","respondent":"柏原行財政改革担当課長","answer":"事業主体につきましては、今の段階ではお答えできる状況ではないです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"したがって、この価格調整についてはこれからのスケジュールで、今聞いても、あまり正しい価格は出てこないと思うんですけれども、この地域的な価格の想定される金額、一定のレベル以上の金額になるんだろうと思うんですが、そういう金額を承知しながら買うというふうにしたというあたりを、もう一度伺いたいなと思います。","respondent":"桑村企画部長","answer":"前回の行財政改革特別委員会でもいろいろご議論いただきましたけれども、委員の皆さんからもかなり購入のご意見があったということもあって、その意味でいろいろなことを勘案させていただいて、国としっかり金額が折り合っているわけじゃありませんけれども。","voiceIndex":44,"id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"今後の見通しなんですけれども、１０月の末に厚生労働省に回答して、確定するのがいつごろで、その後というようなスケジュールが、わかる範囲で教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"スケジュールの部分ですけれども、相手方が財務省であれば、ある程度きっちりとしたスケジュール感を出してきてくれているんですが、厚生労働省は何分、こういったところの事例がないということで、あれなんですけれども、この後に、品川区にしますよという決定の回答は。","voiceIndex":46,"id":"exchange-020"},{"speaker":"渡部委員","kind":"確認","question":"内容に書かれていますことも、確認はしています。あくまでもこの東五反田４丁目の国有地の活用についてということであれば、さまざま書いていただいてありますが、あくまでもグループホームの設置を推し進めていくんだというところで、下のほうに、仮にこの土地でかなわないのであればというのは、全く別問題と考えますので、今回、私ども自民党としては、結論を出して不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"理由につきましては、こちらの土地を検討する中で、グループホーム２ユニット、私どもの質問の中でも、２ユニットでないと、１つの事業者がやるにしても採算はとれないだろうということで、１ユニットというのは当然難しいですし、３ユニットというとフロアが足りないという、さまざまな要因から、また高齢者の需要、これから高齢者がさらに増えていくことを考えるならば、こういう施設を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうした形で地域の要望を寄せていただいたこと自体は、いいことだなと思うんですけれども、ただ、先ほども申しましたように、ここの陳情の中で主に出てきているサービスコーナーというのは、もう少し駅前等、利便性のいい場所につくるのが筋であろうと考えています。ただ残念ながら、今回の当該の土地については、ご希望には沿えないかなという意味で、不採択と考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-023"},{"speaker":"原委員","kind":"意見","question":"本日決めるということで、内容につきましては、各委員からご意見が出ているとおりでございまして、私も、まず行政、頑張ったなという思いです。この陳情に関しましては、本当にいろいろなものをたくさん、とにかくできる限りのことを地域の方のために入れたいというのはわかるんですが、やはりスケール的に難しいだろうという形で、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"私は採択を主張したいと思います。気持ちは先ほどの質問のところでも表明してきたつもりなんですけれども、この地域には公共施設が少ないということ、そして、品川区役所まで行かないと、あるいはガードまでくぐって、しばらく川のほとりを歩いていかないと、地域センターには到達しないということで、利便性から見るとかなり疎外されている地域じゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"これからもこういうことは、今までもありましたけれども、こういうことが出てくるということもあり得るんですが、区民の方々の共有財産でもあるし、そういう点で一定の判断基準はあってしかるべきだと思いますので、その点を確認したいので、もう少し説明をしていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、こういったことを受けて、先ほどもちょっと触れましたけれども、跡地の有効活用といった面、それから防災面、地域の実情等々を考えて、検討に入るところです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"そうしますと、この朋優学院は、校舎の新築に当たって補完避難所機能を高めるという内容も、改修・改築計画には含まれているという理解でいいんですか。","respondent":"柏原行財政改革担当課長","answer":"既に今、補完避難所と指定していますので、それが建物が新しくなるといいますか、耐震化、それから老朽化を直すために建替えするわけですから、補完避難所としての機能は高まるです。","voiceIndex":64,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"決定ではないということだったんですけれども、いつの時点で、しばらく来年の９月までは利用のところがあるのであれですけれども、そこまでの期間、どの程度の時点で本格決定するというふうになっていくのか、もしその間に、例えば利用状況等々が出てきた場合にはどうだとか、ちょっとあれですけれども、それと、地域でかなり、豊葉の杜中学校のある地域では。","respondent":"柏原行財政改革担当課長","answer":"スケジュール感のところですけれども、こちらにつきまして、平成２７年３月というふうにご要望が出てあります。","voiceIndex":66,"id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"時間も押しちゃっているので恐縮なんですけれども、地域の防災に対する要求のところがよくわからなかったので、学校の施設あるいは校庭等々で、防災に対して非常に、事があったときにはもちろんそこは活用するんですけれども、日常的に訓練も含めて、防災にかかわる町会としての事業展開ができるようなスペースも確保してほしいというふうに私は理解しているんですけれども、そのあたりのことは。","respondent":"柏原行財政改革担当課長","answer":"こちらの地域から伺っているお話は、まずここが避難所であるということで、何かあった際には避難所としての機能を確実にできるようにしておくということ、それがまず第１点です。","voiceIndex":68,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":21955,"voices":76}},{"id":"h25-20131107-17","meetingId":"h25-cm11","date":"2013年11月7日","dateIso":"2013-11-07","committee":"震災対策特別委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6442#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":1171,"voices":10}},{"id":"h25-20131125-6","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"区民委員会","time":"午前１０時００分～午前１１時２４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６６号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６６号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"９月８日にＩＯＣ総会で東京開催が決定されました。この事業の開催に当たって、生活や環境の調和のとれた無理のない取り組みを進めることが必要だと思いますけれども、例えば便乗した無理な箱物建設や住民追い出しなど、こうしたことはオリンピック憲章と反すると私は思いますけれども、そういう点についてはどのように考えていらっしゃるのか、まず総論を伺いたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今回２０２０年に向けて補正予算を組んだものについては、９月に決まりましたその熱い思いを、今、継続して、ここで子どもたちを中心にひのき舞台で活躍する夢を持っていただこうというもので、実際に計上させていただいているものです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、具体化していくに当たって、やはりどういう視点が大事なのか、その点を改めて伺いたいと思います。私はこのオリンピック・ムーブメントの意味を、子どもたちにも実感できるような事業にしていただきたいと思うのです。そして、その意味合いからも、今回一般財源を投入するというわけですから、あえて伺いたいのは、なぜ一般財源なのかというところも、その意味合いからもご説明いただきたいと思います。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"さまざまなところで、ただ技術の提供だけにとどまらないで、そういうスポーツをやっていく上での考え方等の部分も今後は事業の中で入れていきまして、そういうものを皆様には経験していただいて、オリンピック・ムーブメントの考え方を広めていきたいと考えています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ。当初予定の休館の時期よりも、今回の休館の時期のほうが長くなるので、ちょっとそこの事情と、それを踏まえた利用者への案内の説明を改めて伺いたいと思うのと、これに伴って、ほかの天井部分はどうなのかというのも思いますので、ほかの施設のこういうホールの天井部分についてはどういう状況になるのか、そこだけ説明していただきたいと思います。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"当然それがまた英語の多言語化を行い、あるいはほかの多言語化マップを見つつ、ほかの言語の作成も必要であろうということがありましたら、これはまた次年度以降の判断になってくるかと考えているところです。そしてその天井部分を改修するということで、期間もこの４月１日から３カ月半ぐらい、まだ設計もこれからかけるものですから、今、予定がとりあえず３カ月半という形で設定をさせていただいたところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"それについてはどこがどう旗振りになるのか、所管が正直わからないまま伺っているところは申しわけないとは思っておりますけれども、ぜひそういうところにもこの多言語化という意味合いに含めることが必要だと思いますけれども、その点についてはどのように取り組んでいこうとしていらっしゃるのか、お考えだけ伺いたいと思います。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"確かにちょっとどこがということはありますが、基本的にオリンピック・パラリンピックへ向けた動きというのは全庁挙げて取り組んでいくということで、担当課長等の設置もされておると。庁内の調整だとか、そういうものについては担当課長がやると、対外的な部分については私がやるというようになってありますが、またそれとは別に、庁内で検討委員会も第１回が９月２０日には立ち上がってあります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほど中塚委員からも出ましたが、これは一般会計で、今回オリンピック・パラリンピック関連の補正予算が出ていますけれども、今までも例えばオリンピック・パラリンピックの東京招致の事業とかいうのは、基本的には東京都でやっているものが多くて、区でやるものに関しても東京都から何らかの補助金等が出てきたものが多いと思うのですが、これはなぜこの時期に、あえて一般会計で区単独でこの事業を幾つか。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"しかし、今、決定されて、先ほどちょっとお話しましたように、東京都のほうも、今、そこが変わって、この１０月にスポーツ局のほうもオリンピック準備部局として一つの看板ができました。","voiceIndex":17,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。次に、１個ずつ、各事業についてお伺いしますが、まず初めに、日本の伝統文化・おもてなしについてですが、この事業は区が直接やっていくのか、それとも国際友好協会に委託をしていくのか、その点を教えていただきたいのと、先ほど何か恵方巻きの食材に関しては実費だということでしたが、屋形船の借り上げ等がありましたね。その実費等で負担をされるのかどうかを教えていただきたい。","respondent":"寺嶋協働・国際担当課長","answer":"３点目の在住の方と海外からいらっしゃる方、まさにご指摘のとおりですが、基本的には日本に住んでいる、区内に住んでいる外国人の方、ご家族の方で参加していただくということがベースになっているのですが、先ほど申しましたこの委託を予定されている。","voiceIndex":19,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"荏原文化センターですが、これはいろいろ耐震化を各施設されていて、今回、８月５日付で建築基準法施行令の改正がされたということで、やらざるを得なくなったということだと思いますが、まず、荏原文化センターの耐震化をされているのですが、今後荏原文化センターをどのように、どこまで今後活用していくのかというような展望がもしあれば、教えていただきたいのと、近くにスクエア荏原が開設されて。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今後荏原文化センターをどのように、いつまでですが、これは荏原文化センターに限ってのことでよろしいでしょうか。","voiceIndex":21,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。その耐震化をやりますときに、さまざまな基準値があると思うのです。もちろんその基準値をクリアするために耐震化をやりますけれども、できたら今後も基準値というのは変わる可能性があるでないですか。これは要望で終わります。それと、区内の小学校高学年４５人程度となっていますが、これの選考方法というのはどのように考えているのか、その点を教えてください。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"対象の選考方法ですが、今、公益財団法人スポーツ協会のほうでもジュニアの育成をやってあります。そんな中で、今、非常に頑張ってやっている子どもたちを対象にするのか、ちょっと選考方法についても検討するです。","voiceIndex":25,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。パラリンピックは、ぜひ力を入れていって、やっていただきたいと思います。最後、観光資源の整備のところですが、まず、ビーチバレー大井町大会の開催、７００万円という、これ１日ですよね。非常に大きな額が計上されていますが、まずこの内訳を教えていただきたいと思うので、よろしくお願いいたします。","respondent":"米田商業・観光課長","answer":"大体ですけれども、いわゆる会場の設置から撤去までが約３００万円。それから、その他企画運営ですとか、あるいはそれに関する印刷物等、それからあとはある程度有名な選手を呼んでくる場合の出演料ということで、計上させてあります。","voiceIndex":27,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"少し、このビーチバレーを大井町の駅前でやるというのに非常に違和感を感じるのですが、まず、これは砂を道路に設置をしてやるということでよろしいのでしょうか。３月ぐらいに予定されているのかと思いますが、まだ肌寒い時期にビーチバレーを駅前でやるというのが、本当にこのオリンピックのためになるのかどうかも含めて、必要なのかどうか、その辺の考え方を教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"そちらのなるべく駅に近いところ、人の通りが多いところに会場を設置して、いわゆる品川区内で開催される競技、実際の開催される場所は別ですけれども、そちらで実施というのもちょっと今のところ現実的ではないので、まず、品川区と言えばどこかということで一つ大井町が選ばれ。","voiceIndex":29,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういうので向こうに行って、向こうでビーチバレーを見てもらうとか、そういったほうが、逆にもっと「あ、こっちでやるんだ」と場所を皆様に知ってもらう意味でも、それこそオリンピック・パラリンピックのあれになるし、例えば水陸両用バスを使うことによって、新たな観光のアピールにもなるのかと僕は思いますけれども、今回、予算計上されていますけれども。","respondent":"米田商業・観光課長","answer":"今、ご提案いただいた趣旨等については、多分このビーチバレーのイベントというものも、２０２０年まで継続して何かしらまたこの取り組みを通じて今後どうしていこうかというようなことは検討されるものだと思いますので、そういうときに。","voiceIndex":31,"id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つは観光資源ですけれども、今、石田委員もおっしゃっていて、本当に開催されるところでやはりそういうものをやっていただきたいと思うのと同時に、あと一つここで聞きたいのは、区内大使館の協力の国際ＰＲのブースとか商店街の模擬店というのは、同時ではなくて、日にちを変えた開催というか、どういうふうにやるのか教えていただきたいのと、それから、特にこの模擬店等には。","respondent":"安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長、米田商業・観光課長","answer":"そういうものも一から設計していかなくてはいけないという部分。それと、あとは温水プールも特定天井に当たるということで、温水プールのほうもあわせて設計を委託ということで含めさせていただいてあります。いわゆるイベントの一つの盛り上げということで、さまざまなところがやはりこのオリンピック・パラリンピックの歓迎の機運があるよということで、この辺の各団体については今後の調整というようなことになってまいりますので。","voiceIndex":33,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"細かく伺いますが、まず、日本の伝統文化・おもてなしの国際交流で、節分の豆まきをやるということですが、節分に豆をまくというのを伝統文化としているわけですから、その起源を把握しておかないといけないと思うのですが、節分に豆をまく起源を教えてださい。","respondent":"寺嶋協働・国際担当課長","answer":"この予算案の計上に当たりまして、いろいろ調べましたけれども、諸説あるということで、具体的に何年のいつごろからということではないのですけれども、いわゆる陰陽、占いみたいというとちょっと語弊があるかもしれませんけれども、あれに基づいておりまして。","voiceIndex":37,"id":"exchange-013"},{"speaker":"藤原委員","kind":"提案","question":"大井町でビーチバレーをするというご提案が出ていますけれども、これは先ほども少し課長から出ていましたけれども、２０２０年にどう結びついていくのですか。今、これをやることが、２０２０年のオリンピック・パラリンピックに具体的にどういう効果のためにやるのかというのは、区が予算をつけるわけですから押さえておかないといけない。なっているかもしれないし、ならないかもしれない。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長兼オリンピック・パラリンピック推進担当課長","answer":"今後もこの実施を踏まえて、いわゆる商業ですとか、あるいは観光の部門の関係、あるいはそれ以外のところで、どのようなオリンピック・パラリンピックに向けた、いわゆる外国人の方、それから国内の方の受け入れの醸成について。しかし、区としては私が務めします職務については、行政の継続性と申しましょうか、しっかり後進にバトンタッチをしていきながら進めていきたいと考えています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"おもてなしの国際交流のところで、予算のところにガイド通訳要員とかありますし、例えばそういった商店街の活性化のパンフレット等も英語でつくるというお話だったのですけれども、この間、外国からいらっしゃる方のアンケートがありまして、一番困るのが日本に来て言葉が通じない、英語で話かけても皆様わからなくて、買い物もままならないという話があったのですけれども。","respondent":"寺嶋協働・国際担当課長、米田商業・観光課長","answer":"これは専門的なその部分の通訳等、保険をかけてという意味ではないのですけれども、専門の方を１名と２名を配置するとありますけれども、ご質問の趣旨については、これは１つの事業としてはやりますけれども。あと、全体的には今後の話になってくると思いますけれども、いわゆる指さしである程度翻訳できるような、「これ下さい」というのが外国語で書いてあり、日本語に訳したものが並列してあるというようなもので。","voiceIndex":44,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"おもてなしのところで、品川神社が候補に挙がっていますけれども、その理由を教えていただきたいのと、要望ですけれども、２０２０年までに、例えばこういった事業をぜひボランティアで、そういった子たちが、２０２０年に本当に開催するときにその子たちがボランティアとして活躍できるように、その辺、こういった事業からボランティアの獲得といった連携というのは。","respondent":"寺嶋協働・国際担当課長","answer":"このエリアが北品川だけというのはそういう意味でありまして、まずそこを今回、そこで活動されている方たちを中心に、比較的得意な分野においてやっていただくというのが、今回ですけれども、これは７年間ありますので、ある意味モデル的になってしまうのですが。","voiceIndex":50,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういうものは考えているのでしょうか。それとも、それでは対象にならないのかどうか、そこら辺をまず１点目にお聞きしたいと思います。その効果というものは、区としてどういうふうに検証なさっているのか、それをまず教えていただけますか。","respondent":"寺嶋協働・国際担当課長、米田商業・観光課長","answer":"そういった場合には、おそらく補助金対象になるであろうということは、今後の検討委員会の結果を踏まえてですけれども、ある程度想定がつく分ですが、こういった気運醸成とかで。機内情報誌の関係のいわゆる効果ですけれども、こちらについては、やはり写真を伴って見せることに対して、特に外国の方への影響というのはある程度あり得るということで、特にそれがその外国の方が日本に求めるものと合っている場合。","voiceIndex":52,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財調の関係は担当が違うので、非常に答えにくいと思いますけれども、ただ、さっき課長も話していたように、２３区統一しないと要望が通らないかもしれないので、ぜひ品川区としては持っていけるように各部署からも努力していただきたいということを一つ、これは要望します。それから、例えば羽田空港の観光案内所だと。そこら辺を考えると、何で恵方巻きが競って出てくるのか、ちょっとそこら辺だけ確認を。","respondent":"寺嶋協働・国際担当課長、中川原地域振興事業部長","answer":"ただ、もうここ１０年弱ぐらいになると思うのですが、ある意味商業ベースでもありますけれども、東京のほうの各コンビニエンスストア等々で入ってきて、結果的にある程度、まだ全国規模になったとは言いませんけれども。申請する期間が短かったこともあり、すみません、考える時間が少なかったということで、それなりに頑張りましたけれども、ただ、オリンピック・パラリンピックは７年といっても非常に早く過ぎるし、今、私たちが説明したことは。","voiceIndex":55,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"部長の、随分よくわかりました。その中で、ちょっと繰り返しになってしまいますけれども、品川区としての財源として、やはりこれからずっとやっていくと、一般財源の中でどこまで持ちこたえられるかというのもあるから、その辺は財源を確保できる形、当然交付金は交付金でもらうとしても、別の形もいろいろ考えておいていただきたいと、これは要望しておきます。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":28298,"voices":70}},{"id":"h25-20131125-7","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"厚生委員会","time":"午前１０時００分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の第６７号議案、品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","agenda":"はじめに、(1)の第６７号議案、品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"幾つか、お伺いをしたいと思います。一つ目が、修学資金の貸付けなんですけれども、現状、どのぐらいの方が、何％ぐらいの方が利用されているのかということ。それから、条件の中に、休学、または停学による修学資金の貸付けの停止ということなんですけれども、これは現状、どれぐらい発生をしているのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"休学等により停止になった場合につきましては、毎年１名から２名というような割合になっており、少人数ということで推移しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"８９.４％の方が利用されているということで、非常に利用率も高いし、この事業自体、品川区にとっての介護行政のための非常に必要な事業だと思いますので、ありがたい制度だなと思います。今回の条文の中に、第１６条、区長が特別な理由があると認めたときは、当該延滞金を免除するという免除規定がありますけれども、特別な理由というのは、どういったものを想定されていらっしゃるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういうことも考えますと、一律に延滞金を取るということは、本人の今後の生活に対しても非常に苦しい部分が出てきますので、返済の方法なども相談しながら、その状況に合わせて延滞金を免除するとしています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"この専門学校が設立された経緯と、それからこの事業についてなんですが、専門学校を運営していくうえに、区が支出している経費と、補助金などが充てられているのかどうか、ちょっと大きなところで質問させてください。","respondent":"永尾高齢者福祉課長","answer":"品川介護福祉専門学校への助成につきましては、今、ご説明いたしました状況を踏まえますと、やはり区のほうで人件費、運営費の助成等が必要だというところで、３,０００万円を、人件費、運営費の助成に充てております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"今おっしゃった介護福祉士の取得ということなんですが、ほかにこの専門学校で資格取得ができるものがあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この介護福祉専門学校で受ける資格というのは介護福祉士なんですけれども、こちらの学校の講師や、いろいろな設備も活用するということで、社会福祉士の養成コースという通信制の講座もやっているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"社会福祉士の通信の講座というのは、今までの３,０００万円とか、そういったところの費用とは別のものでされているのか。それから、同程度の資格を取れる学校として、今、ほかの専門学校やたくさん養成講座があるんですけれども、その中で、授業料としては、今回値上げをして１４０万円ということなんですが、高いのか、同程度なのか、そういったところはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"１４０万円の授業料の件ですけれども、他の学校の資料等は、ちょっと手持ちはないんですけれども、土地代、建物代は区のほうで助成しておりますので、ほかのところに比べれば随分安い金額になっているかと考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"事務事業概要では、在籍数のみなんですけれども、願書受付人数、試験を受けられる方たちがどのぐらいいて、以前も入学者数、在籍者数が少ないというような指摘があって、随分努力されて、平成２４年度実績では、定員８０名のところを７４名となっているんですけれども、そして３回ほど受験をされているようですが、どのぐらいの方が入学試験をされて、この在籍人数になっているのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"設立当初は、かなり応募の方がいらっしゃいまして、４０名のところ、１００名を超えたというような話は聞いておりますけれども、ここ五、六年の間は、なかなか希望される方がいらっしゃらなくて、介護福祉専門学校のほうでも、各高校を回ったり。","voiceIndex":16,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"貸付けの返済者割合と、免除になった方たちは、品川区の事業所で３年間働かれた方というふうに思うんですけれども、そうでない、先ほどの返済者の割合ですよね。決算書では、１,６００万円ほどの返還金が毎年計上されているように思うんですけれども、そうすると、貸付けを受けて、品川区内の施設に就労されなかったという方になると思うんですが、どのぐらいの推移で行かれているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"返還する場合なんですけれども、１回はそこの指定施設に入っても、その後に、３年たたないうちに辞めてしまったり、ちょっと精神的なことでほかの施設に移ったりという方もいらっしゃいますので、途中の方も何名か入るというような形になっております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"井上委員","kind":"意見","question":"今、ちょっと答弁をいただいたんですけれども、免除者の中で、３年に満たなかった方たちは返済をされているということになると思うんですけれども、大きな授業料の負担を、区がしているので、３年以降の定着率というのも押さえておかないといけないと思うんですけれども、先ほどの数名ということではなくて、きちんと実際の状況をお知らせください。","respondent":"永尾高齢者福祉課長","answer":"実際に学校の卒業生で、思ったよりも大変だとか、人間関係が難しいとか、いろいろなところで、卒業した後もご相談に見えていて、教務の先生方がいつも丁寧に対応をしながらつなげていたりというような状況は、現実としてあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"３年間そこで働けば免除になるわけで、その先、いかに定着支援をしていくかということで、継続するのはすごく大変で、やっとの思いで３年間というのは、心情的にもわかるし、そういう職場だと思うんですけれども、とにかく３年勤めれば、授業料免除になるからそれでいいというふうにならないように、職場のほうの定着支援もしなきゃいけないんですが、その辺のデータをちゃんと押さえていますか。","respondent":"永尾高齢者福祉課長","answer":"実際の数字について、今は手元に用意されていませんけれども、３年我慢をして続けると、結構職場の中でも、実務者の中心的な存在になりますので、そのまま継続されるというケースが多いかと考えています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"そこの部分については、非常勤の人たちの中で、正規で頑張り通すってすごく大変だと思って、逆に責任が重くなってしまうという方たちもいるので、その辺は、学校のほうでもお願いしたいと思います。貸付け申請の審査の内容については、どんな条件があるのかということと、今まで、貸付けが認められなかったケースというのは、どういったものがあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"継続して貸付金を受けるためには、ある程度学業のほうをきちんとやっていただく必要がありますので、例えば、入学した前期については、条件についての審査になりますけれども、後期分につきましては、科目で落ちているものがないかとか、その方の欠席、出席状況とか。","voiceIndex":24,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"今、お伺いしていると、授業料が全額貸付けで、３年勤めれば返済免除という、ほかの貸付けに比べれば大変好条件で、なおかつ、先ほどほかのところの授業料のところでお伺いしたんですが、少し調べたら、やっぱり１年間で１００万円とか、もっと高い。通信教育ではあるけれどもというところで、資格取得の数が少ないというところでの人気がどうかと、私個人的には思うんです。","respondent":"永尾高齢者福祉課長","answer":"各学校を回ってみると、学校のほうも、大学に何名進学したというような名前で子どもたちを集めているところもありますので、そういうところで専門学校がちょっと苦戦してしまうのかなと思っているところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"そうすると、区が介護福祉士の養成事業に取り組んでいくということについて、長期的に何かお考えがありますでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今後ですけれども、介護福祉士の資格の取得についての改正なども控えておりますので、また介護保険法の改正などもあります。そういうものも踏まえながら、どういうふうに人材を育成していくかということは、今後、検討していきたいと考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"そこのところについては、これだけ見たら、何だという話だと思うんですけれども、そこについては、何か検討とか、お考え、説明とか、どういうふうに考えているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、この１４０万円を２４で割ると割り切れないということもございまして、そしてまた貸付け自体も、前期と後期で貸付けをしているという現状がありますので、月額という表現ではなくて、総トータルの金額という表現に、今回、変更をいたしました。","voiceIndex":30,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"先ほど来、いろいろ質疑があって、区内の社会福祉法人等で３年間勤務されない方が意外と少ないんですけれども、その中で、返還できなくて、実際の滞納率というんですか、それを教えていただきたいんです。","respondent":"永尾高齢者福祉課長","answer":"平成２４年度までの対象の方で、収納されていない方は、人数といたしましては、現在、５人になっています。それにつきましては、分割の申込み等を５人ともがしています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"幾つか教えてください。基本的には、在学される方はみんな、この貸付けを希望されて入ってくるのかが、まず１点。それから、専門学校ですから、高校新卒に限らず、１回社会に出られてから入ってくる方とか、逆に、大学を卒業された後にまた入る方とか、どれぐらいいらっしゃるのか、その辺の割合がもしわかれば教えてほしいというのが１点。","respondent":"永尾高齢者福祉課長","answer":"入学生のうち、貸付けをする人数ですけれども、例えば平成２３年でいけば、４０名の入学者のうち３８名が貸付け、平成２４年は４０名のうち３７名、平成２５年は３５名のうちを２８名となっています。","voiceIndex":36,"id":"exchange-015"},{"speaker":"渡部委員","kind":"質問","question":"最初の質問はわかりました。ということは、毎年２名から何名かの方は、はなから奨学金、３年働いて免除になるということを何も当てにせず、自費で純粋に品川区の介護福祉専門学校に来ようとされている方なんですか。それとも、申請はされているけれども、先ほどの何かの理由で落されている方なんですか。","respondent":"永尾高齢者福祉課長","answer":"最初から当てにしないで入っている方がほとんどです。もともと田舎に帰ってやりたいという方だとか、資格は取るけれども、縛られるのはちょっとというような方が多いと考えています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"最後に、品川区の指定福祉施設というのは、考え方としては、どこがどこがというよりも、品川区内で働いてもらう分には、これは３年間働いていただくと、ほぼ免除になるという考えでいいんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"基本的には、品川区の事業所で働いていただく方は、３年間で免除という考え方をとっております。","voiceIndex":40,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"授業料が１２０万円から１４０万円に引き上げられることに伴っての貸付け額を引き上げるというところで、そもそも授業料が引き上がる理由を教えてください。","respondent":"永尾高齢者福祉課長","answer":"痰吸引等の医療ケアというのがそこにまたさらに追加されますので、教育課程が変更になります。それに伴いまして、教育の内容もかなり充実した内容になりますので、授業料のほうも、それに合わせて上げていくところです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、授業内容が充実というのは、教員の態勢とか、授業でいう材料とか、そういったものが変わってくるということなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"医療ケアを行うことになりますと、吸引シミュレータだとか、経管栄養シミュレータとか、そういう整備も必要になるということがあります。それでまた、指導に関しても、それなりの教員が必要というところで、授業料についても値上げをすることになりました。","voiceIndex":44,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"先ほど、区内事業者に就職すれば大丈夫ということだったんですが、今まで、区内であるにもかかわらず、免除にならなかった要件とか、ケースはあったのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"こちらのほうでは、学校からそういうケースというのは、具体的には聞いておりません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"それはそれでオーケーなら、それはそれで結構なんですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"就職先につきましては、介護福祉専門学校と区とが連携を密にしておりますので、その中で、そういうお声があれば指定施設にするかどうかという検討をしていきたいと考えています。","voiceIndex":50,"id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど、卒業と同時に国家試験を受ける資格が得られるということで、そうすると、国家試験にもし落ちてしまって介護福祉士になれなかった場合は、どうなってくるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"その部分が非常に、学校のほうも苦慮しているところで、国家試験に合格できるような学生の育成をしなければいけないというところで、問題意識を持っているところです。ただ、国家試験に合格しなければ、当然のことながら介護福祉士にはなれないということになります。","voiceIndex":52,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、貸付けを受けても、３年間福祉士として働けないということになるんですよね。そうすると、打ち切りになるということなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"現状の制度でいくと、そういう考え方もとれると思うんですけれども、ただその国家試験の内容だとか、合格率とか、そういうものがまだやっていなくてわからないことがありますので、平成２６年度から入学される方は２年間ありますので、その間に情報を収集して。","voiceIndex":54,"id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"賛成なんですけれども、一言意見を述べたいと思います。先ほどの、３回試験をするにも定員がなかなか集まらないというところの原因をしっかりと把握して、対策をとっていただくこと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私も賛成ですけれども、一言。１年１０万円、２年で２０万円の値上げというところでは、これは区が負担してもいいのではないかと思うんです。さらに国家試験にもし落ちてしまったらというところでも、そういったリスクを考えると、さらに入学生も集まりづらくなるのかなという危惧もありますので、生徒への負担軽減というのは、さらにちょっと検討していただきたいということを含めて、賛成をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"}]},{"id":"topic-02","title":"の第６８号議案、品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"の第６８号議案、品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問","question":"在宅サービスセンターなんですけれども、今回、認知症の通所が２階にできるということで、これは今まで北品川でも、同一のサービスが行われていたものなのか、新規のものなのか。それから、北品川サービスセンターで行われていた方たちの定員みたいなところは、どのぐらい拡大されると考えられるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"認知症の部分ですけれども、今回の移転に伴いまして、面積が広がるということで、新たに始めるものです。これまでやっていたサービスセンターの定員に変更はございません。定員３５名ということです。","voiceIndex":70,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、広くなるということだったんですけれども、広くなったことで、かかる経費が増えてくるとかはあるんでしょうか。それから、これを建設するにあたって、こういった形に建設してほしいと、区も一緒に入られたのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この建設にあたりまして、レイアウト等につきましては、品川区と、指定管理者である福栄会と協議しまして、使い勝手のよい形でレイアウトを考えているところです。","voiceIndex":72,"id":"exchange-027"}]},{"id":"topic-03","title":"の第７３号議案、指定管理者の指定","agenda":"の第７３号議案、指定管理者の指定","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"東大井の部分では、通いと、泊まりと、グループホームと、ケアホームになっているんですけれども、ここの部分では訪問介護というのは入らない仕組みなんでしょうか。すみません、小規模とちょっと理解をしていないので、そこの説明をお願いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"こちらの東大井地域密着型多機能ホームにつきましては、協議会は特に設置しておりません。訪問介護についても、地域密着型多機能ホームでは設置の義務は、特にございません。","voiceIndex":86,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"前回、モニタリングの資料をいただいたときに、１年未満での退職者が多く、職員の定着等、人員不足について早急に改善が必要であるという指摘に対して、今回、指定にあたって、それはどのような改正で、評価をすると選定したんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"事業系別プロセスごとの研修として、基礎課程の研修だとか、入居系の職員の現任研修だとか、そのほかに東大井多機能ホーム独自の研修や勉強会を実施しているという実績があります。","voiceIndex":88,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"指定管理の再委託についてなんですけれども、食事の部分が再委託先というふうに、前回のモニタリングのところに表記をされているんですが、どの程度の再委託が認められるのかということ。こういった部分で、万が一食中毒とか、そういった問題が発生したときに、ここはどういうふうなルールをもって責任が発生するように、仕組みとしてなっているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"給食とか、清掃については、再委託をしています。こちらには、看護師が常勤換算で２名いますので、万が一の場合には、看護師の対応も可能です。ただ、そういうことが起こらないようにということで、施設内でのマニュアルもつくっているのを確認しています。","voiceIndex":90,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"指定管理の事業者に言っても、自分はお世話になっている身だから、ということもあるんですが、そういったときの窓口を整備をしているのか。そしてそれをちゃんと利用者のところに、口頭だけではなく、文書とか、そういったもので、そういったときには、ここを通してこういう救済の仕組みがありますという制度は、ちゃんと整えてあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区では、事故に起こったことに対しては、事故報告書というのを常にいただいており、内部での確認をきちんとしています。第三者評価も実施しております。その中で、そういう報告があれば、区のほうでも実際に実地指導等を行っているところです。","voiceIndex":94,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問・要望","question":"事故の報告の件数が多いとか、少ないとか、そういったものは、これは高齢者ですから、当然起こり得ることだと、私も思いますし、絶対というのはなかなか難しいのかなと思うんですけれども、極端な話をしますと、高齢者の施設で、介護をする方によってお亡くなりになる方が非常に多いような事件、たまに逮捕されたりする事件がありますけれども、自治体が絡んでいるかどうかは、また別として。","respondent":"永尾高齢者福祉課長","answer":"ただ、事故報告が上がってきたときに、その原因だとか、その後の対応だとか、そういうところをきちんと注意をして、迅速な対応ができていないようであれば、区も事業者を呼び出して指導する等の措置をとっているところです。","voiceIndex":96,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"社会福祉法人ではなくて株式会社ということで、株式会社ならではメリット、デメリットとか、何か区のほうでお気づきのことがあったら、なければいいんですけれども、特徴的なものがあれば教えてください。","respondent":"永尾高齢者福祉課長","answer":"基本的には、やっぱりさまざまな担い手が福祉を支えているというような現状ですので、その施設のよさが、事業者として生かせるかというところが重要だと考えています。","voiceIndex":98,"id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この多機能ホームの職員数は、皆さん正規職員なのか、そこの正規率、またこの間、離職率なんかもわかれば伺いたいんですけれども。","respondent":"永尾高齢者福祉課長","answer":"先ほどのご質問にもございましたとおり、施設内の研修会、勉強会は、月１回重視して行っているということで、施設長みずからが意見を聞きながら、介護職の離職につながらないようなご相談を受けているというような状況になっております。","voiceIndex":100,"id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、常勤の部分を教えていただいたんですけれども、非常勤数というのはどうなってくるのか、ちょっとわからなかったので、わかれば教えてください。離職率が、ここ２年ほど多かったというところでの、離職の理由というのはわかっているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"事業の中身の説明だとか、そのほか、処遇についてもちゃんと説明をしたうえで適任を選択すればよかったという声を聞いているところです。","voiceIndex":102,"id":"exchange-035"},{"speaker":"渡部委員","kind":"質問","question":"今回、指定管理の議案が多数出ておりますけれども、全体に係わる質問なんですけれども、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"全体的な話をお伺いしたいんですけれども、指定管理をされる場合、特に今回新たにではなくて、継続してされる場合に、どのようなときに、いわゆる継続性を重んじる、どのようなときに新規にプロポーザルをかけるのか、仕組みがどのようになっているのか。これの構成員がどのような形で、例えば、これはこういうところに係るから、こういう選び方をするみたいな、何か基準があれば教えてほしいと思います。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"それからまた、安全で安定した運営をするというところを考えますと、やはり、公募ではなくて選定をするということが適しているのかと思います。第７７号議案につきましては、健康センターのほうになります。私のほうから、第７５、第７６号議案に企画部が入っていないのではないかということについて、お答えいたします。","voiceIndex":106,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成です。一言意見を追加したいと思います。先ほどの事故についての問題なんですけれども、事故の報告書を上げてもらって、第三者評価もあるということだったんですが、課長の答弁で、この施設は最終的には区の施設だから、区に責任が発生をするというようなところで、区に改善を求めるという部署が、今ないわけですよね。やはり、事業者も、第三者評価も、設置者である区も、やっぱり身内なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"共産党は反対です。ですので、そういったところが保証されていない、そして５年間という短い期間の更新だったりすれば、やはり正規社員が、人材育成として、公共施設の職員としての自覚や専門性が身につかない、なかなか難しいのではないかとも感じますので、やはりこういった福祉施設に株式会社はなじまないと、引き続き反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-039"}]},{"id":"topic-04","title":"の第７４号議案、指定管理者の指定","agenda":"の第７４号議案、指定管理者の指定","exchanges":[{"speaker":"井上委員","kind":"意見","question":"ここの部分で、障害者の居場所というか、その支援と、障害者生活支援センター、基幹相談支援センターということで、ここにはあるんですけれども、そこの指定管理者として品川総合福祉センターなんですが、今いろいろ制度が変わっているんですけれども、具体的にこの中で、事業として指定管理に任せている業種というのを、全て挙げていただけたいと思います。","respondent":"中山障害者福祉課長","answer":"３点目が地域活動支援センターということで、こちらＩ型なんですけれども、さまざまなボランティアの活用も行いながら、障害程度区分にかかわらず、趣味ですとか、創作活動、あるいはさまざまな教室などを行っているところです。","voiceIndex":121,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"最後の生活支援センターの中で、まずここが基幹相談支援センターということで位置づけているのではないかと思うんですが、そこはどのようになっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"ここを中心に、地域の相談支援センターということで、こちらの会館にあります障害者生活支援センターのほか、精神のほうの支援センターたいむ、それからこの４月から福栄会のほうに新たに障害者相談支援センターを開設したということになっております。","voiceIndex":123,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"ここだと、品川総合福祉センターを利用している人たちのことはよくわかるんですけれども、そういう要望があったんですが、そういったことについては、区のほうに言うのか。一法人への相談みたいになることに、ほかの法人を使っている利用者はなかなか相談がしにくいという声に対しての問題意識というのはあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"そこは三つの相談支援センター、それから区の基幹型と入りまして、相談のレベルアップだけではなく、事業者間の情報収集などというものも行っておりますので、その機能を活用しながら、利用者のお声をできるだけ細かく聞いていくような体制に努めていきたいと考えています。","voiceIndex":125,"id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"やっぱりたいむでいけば、福栄会が基本相談とか、計画相談とか、法人が品福と、福栄会等とか、そうではないところを利用される方々もいますので、やはり自分が利用しているところではないところの情報が共有されることも必要だし、本人ではなくて、家族もいろいろなところがわかって、なおかつ選考できるとか、先ほど、そういう状況にないように努められていますというでしたが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"提案","question":"Ｂ型では、水耕栽培事業をモデルとし、ブランチ型ファームを関連機関に置き、ＩＴ（パソコン）による生産管理を行う、とあるんですけれども、これは、これまでの実績を生かし、地域の企業とのつながりを強みとして事業提案されている、とあるんですけれども、これは、今までも実績としてやられていることなのか、その辺について教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"この間、げんきのほうでも、区内企業といろいろご相談する中で、株式会社ミウラのほうで既にやられている書類や図面の電子化サービスについて、業務を請け負うような形で実施ができるという運びになっているものです。","voiceIndex":140,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"新しい試みということなんですけれども、Ｂ型のほうもどういう内容なのか、もう少し詳しく教えていただければと思います。水耕栽培事業って、この前も厚生委員会で視察したところでも、ちょうどやっていたんですけれども、そういうものか、ちょっとこの辺も詳しく事業内容をご説明していただきたいと思います。","respondent":"中山障害者福祉課長","answer":"そのための練習として、あそこの地下に倉庫がありますので、倉庫でもそういった管理ができればというような中身のお話です。","voiceIndex":142,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"この公開プロポーザルなんですけれども、９月１３日から２５日ということだったんですが、他の案件では、公開プロポーザルの期間はどのぐらい取っているのかについて、教えてください。","respondent":"中山障害者福祉課長","answer":"恐らく高齢者の施設なんかですと、建設とセットになっているので、これよりは期間が長いかと思われます。こちらのほうは、もう既に施設があるところに事業の中身だけの提案ということでしたので、この期間で設定をさせていただいたところです。","voiceIndex":144,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"これから出る健康センターなんかは、１カ月ぐらいちゃんと公開プロポーザルをしているという意味では、２週間に満たない募集というのは、私は短か過ぎると思っています。そんなに短くならなければならなかった理由と、この募集期間が短か過ぎることによって応募件数が１件になってしまったというような影響があったか、どうかについて、お伺いします。","respondent":"中山障害者福祉課長","answer":"１者の提案しかなかったということにつきましては、この募集要綱の期間の短さということはあるかもしれませんが、やはり就労継続Ａ型事業の提案というのが、非常にハードルが高かったのかなと感じているところです。","voiceIndex":146,"id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"ここには、ホームページへの掲載と書かれていまして、やはり公開プロポーザルをするにあたっては、発達障害で、既に他の自治体などで発達支援センターを運営しているところからとか、いろいろな情報はあると思うので、そういったところに働きかけはしなかったのかどうか。ただ、ホームページに書いて待たれていただけなのか、その辺を教えてください。","respondent":"中山障害者福祉課長","answer":"こういう事業を品川区がやりますということにつきましては、特に具体的な話はしておりませんけれども、区内の法人をはじめ、発達障害の支援をしているような、ちょっと今名前がすぐに出てこないんですが、そういったところの事業者から問い合わせがあったときにも。","voiceIndex":148,"id":"exchange-048"},{"speaker":"井上委員","kind":"提案","question":"指定管理者制度活用に係る基本方針の中では、公開プロポーザル方式など、複数の事業者から提案を受けることを原則するというふうにありますよね。そこについて、どのようにお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"当然、１者だからそこしかないだろうという考え方でないのはもちろんです。なので、審査におきましては、シビアな視点でしっかりと審査をさせていただいたところです。","voiceIndex":150,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"シビアに審査をしたということなので、お伺いをしたいのですけれども、第３回定例会で可決いたしました発達障害支援施設設置条例の指定管理者の指定手続第１０条第２項の２に、支援施設の適切な維持および管理ならびに管理に係る経費の縮減を図る、というふうに書かれていますけれども、比較対象がない中で、経費の縮減というのはどういうふうに判断をしたのでしょうか。","respondent":"中山障害者福祉課長","answer":"今までの法人が運営している事業所の経費節減もそうですし、今回の提案の中では、人材確保のところについては、積極的に人材を充てていくという姿勢が見られているんですけれども、通常の運営費に当たります、例えば光熱水費ですとか、その他維持管理については。","voiceIndex":152,"id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"それはそうでしょうと思うんですけれども、そういったところで、地域との連携を円滑にするというようなこととか、縮減というのが、区がこのぐらいと想定していることに対して、こういう提案がありましたとか、そういう協議の場での議論なのか、何か言われたとおりで全然見えないんですけれども、そこら辺がどうなんでしょう。","respondent":"中山障害者福祉課長","answer":"プロポーザルの中で審査した項目としましては、プログラムの有効性、それから運営の確実性、連携と協働の視点、これが発達障害者支援施設のほうで、その視点でチェックいたしました。グループホームの運営についても、同様です。","voiceIndex":154,"id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"それからまた、人材確保、ここのスタッフ構成は、多分グループホームのほうは管理人が一人というような態勢でいくのかもしれないんですが、両者のスタッフは、何人でこの事業を遂行していくのかというところは、どのように審査をされて、結果がどうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"下の就労支援施設は、４人ないし５人常時職員がいるような形になります。それから、２階の成人のサロンのところになりますが、こちらのほうに心理職、それから社会福祉士の資格を持つ者を３名、採用しています。その人員配置に合わせまして、この間、かなり研修をやっています。","voiceIndex":156,"id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"ちみなに、法人のげんきは、就労支援センターで５人のスタッフで事業が行われているんですけれども、これは全然別の形で、こちらの施設で、今言われたのは７名ですけれども、７名のスタッフが確保されて進められるということなのか。その就労支援センターのほうとの関係は、どうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"就労支援センターのほうの職員はそのままです。そこの職員がこちらに来るということはありません。それから、こちらの法人のほうで、ほかの関連するＮＰＯのぴゅあサポートの事業のほうからお一人、こちらのほうに来るということは聞いております。","voiceIndex":158,"id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"発達障害施設の施設長は、どのような方がなられるのかということ。それから、げんきが就労支援センターで、法人化前にＮＰＯのぴゅあサポートが、就労支援センターということではなくても、相談とか、訓練などが、対象者が長らく愛の手帳を持つ知的障害者に限定されていましたけれども、いつから、手帳を持たない人たちに利用が拡大されてきたのか、教えてください。","respondent":"中山障害者福祉課長","answer":"法人げんきのほうで、就労の相談、就労支援事業のところで長らく知的障害の人中心だったということなんですけれども、昨年度以降、精神障害、身体障害、そういった方たちの受け入れも行っているところです。","voiceIndex":160,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"社会福祉法人げんきに委託をして、指定管理にするのに、ＮＰＯのぴゅあサポートの方が施設長という、その関係は少しおかしいのかなと思うんです。その方が法人のスタッフになって、そういう形をとるということですか。","respondent":"中山障害者福祉課長","answer":"すみません、表現が悪くて申しわけありません。法人げんきの職員が、そこの施設長になるということになります。それから、手帳のない方にも支援が広がったのはいつからかというのは、先ほどの平成２４年度からということになっております。","voiceIndex":162,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"今回は、発達障害の支援施設ということで、平成２５年度の社会福祉法人げんきの発達障害者の就労支援施設なんだけれども、事業継続Ａ、Ｂということは、就労支援という形なんだろうと思うんですけれど、就労支援の、発達障害者の実績はどのぐらいあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、先日、ご視察いただいたセンターの工夫の中でも、実はその方は知的障害の手帳をお持ちの方でしたけれども、独自の作業工程の工夫ですとか、プログラムの工夫をすることで、発達障害への対応をしているところは、ご視察いただけたのかなと思っているところです。","voiceIndex":164,"id":"exchange-056"},{"speaker":"井上委員","kind":"意見","question":"目的は、発達障害者の自立および社会参加に資する支援を行うことにより、発達障害者の福祉の増進を図る、というところで、発達障害の支援をされてきたというところが、これからの分野でもあるので、非常に難しいと思うんですけれども、ここはどういうふうな能力を有しているからということで決められたのか、ちょっと肝だと思うんですが、説明をお願いしたいと思います。","respondent":"中山障害者福祉課長","answer":"そういった中では、区のほうも、この施設に対して、あるいはこの法人に対してしっかりと連携を組みながら、一歩一歩着実に成人期の発達障害の方の支援ができるようなところは、区のほうも十分に責任を持って対応していきたいと考えているところです。","voiceIndex":166,"id":"exchange-057"},{"speaker":"井上委員","kind":"提案","question":"さっき、あくつ委員からあった、就労Ｂのところで、ブランチ型ファームというのは、それが地下というのがよくわからなかったので、そこの説明をお願いします。それから、事業経費をどのぐらいでしていただくように、区からの提案をされたのか、それによって結構プロポーザルの事業者とかも変わるのかなと思うんですけれども、そこはどういう提案を、こちらからはされているのでしょうか。","respondent":"中山障害者福祉課長","answer":"最近では、企業の中に受付の広い窓口のところの一角に、そういったファームを設けているところもあるというお話でした。それから、運営の金額ですが、障害者福祉課のほうのプロポーザルの実施要領の中では、特段金額については載せさせていただいておりません。","voiceIndex":168,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"一つなので。先ほどの企画のお話もありましたけれども、全体を通して初めての施設であって、実際に幼少期から就労までという特別教育の連続した支援をしていくという中で、ここになぜ教育委員会を入れなかったのか。私は入れるべき、これからもしそういうことがあれば、入れていかなければいけないというふうに思いますけれども、そこについて、なぜ入っていないのか、教えてください。","respondent":"中山障害者福祉課長","answer":"特別支援学校のほうにも、対象となる方がいらっしゃるということも聞いておりますので、最初にこの就労につなげるところについては、区のほうもかかわって、どういった方がここの施設で安定的に継続的に訓練サービスが受けられるかというところは。","voiceIndex":171,"id":"exchange-059"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点だけ、今、態勢だったりとか、社会福祉法人げんきの品川区での実績なんかも、いろいろ聞かせていただいたんですけれども、ほんとうに発達障害に特化した新たな施設というところで、区も連携して、という言葉がたくさん出てきたんですけれども、連携の具体的なところ、今、協議会的なものが、げんきと一緒に開かれているのか、そういったところを、ちょっとお聞きしたいんですけれども。","respondent":"中山障害者福祉課長","answer":"最初の仕事としましては、近隣への事業者説明というところにも、げんきと区と両方で参りますし、その後の具体的な事業の準備、それから、例えばグループホームの入居者であるとか、就労Ａ、Ｂのほうにつながる方、サービスを受けられる方の選定であるとか。","voiceIndex":173,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"今ほんとうに第１条の目的のところで、連携を取って、区も一緒に育てていくという言葉をいただきましたので、ぜひそこのところはしっかりと期待をされている施設として育てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-061"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"共産党は、当初の設置条例と同時に行われた指定管理の運営のところで、株式会社が入ってくるのではないかといったところを危惧して反対をいたしましたけれども、今でも、本来区がやるべきではないかとは思うんですが、げんきの今までの経験と、立ち上げにあたって区が丁寧に支援をしていく、目を離さずに十分にやっていくというところで、丁寧にやっていっていただきたいと思っています。それで賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-062"}]},{"id":"topic-05","title":"の１の(7)、指定管理者の指定","agenda":"の１の(7)、指定管理者の指定","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今回の申請から修繕体制を強化することを目的にということで、住友不動産リフォームが参加するということなんですけれども、どういったことを、この共同事業体として、修繕体制の強化を新しく参加した理由に挙げているのかというところ。これは、区としての募集の条件の中に、そういったものが入っていたのかどうか、あわせて教えてください。","respondent":"江部健康課長","answer":"この点について、特に募集要項でこれを強化することというような特記事項などは載せておりませんが、事業内容全体の中には、維持管理の中で、こういうところで経費がかかるということは、具体的に金額を明示している中でのことですので、事業全体の中での協議で。","voiceIndex":189,"id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問・要望","question":"指定管理者側の健康センターに対する強い意欲が認められることということで、５年間やってこられて、その上で、経験値から必要なことということで、多分こういう提示があったと思うんですけれども、５年前と比べて、新しく脱衣所等というところもあると思うんですが、そのほか、今回の選考の中で、区として、指定管理者の選定の公募の条件として新しく求めたところがそれ以外であるのであれば。","respondent":"江部健康課長","answer":"したがいまして、光熱水費の削減ということは、テーマとして出しております。それにつきまして、５年間で２５０万円の削減を提案をしてきております。","voiceIndex":191,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"３点目は、以前にこのセンターの中で、健康づくりをする市民団体が施設の中の会議室とかを使われていたんじゃないかなと思いまして、それができなくなったという経緯があると聞いているんですが、その部分について、健康づくりをしている団体への、地域での活動も含めた健康づくりの支援というところがありますけれども、ここについては、どういったことで選定した理由の中に含まれているんでしょうか。","respondent":"江部健康課長","answer":"ただ、スポーツ施設だけではなく、貸館という部分では、７階のホール、それから３階の会議室は、一般の方が申し込みをされておりまして、そこは利用していただけるものと思います。","voiceIndex":194,"id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"ここの事業の中で、以前だと、双子のお子さんたちの教室とか、区民であってもなかなか利用できないような、そういうことで、この事業をここでやってほしいという提案とか、そういうものがあるのか。今、すべて事業メニューは指定管理者からのものなのか。そういう仕組みは持っているけれども、やっていないのかとか、その辺はいかがでしょうか。","respondent":"江部健康課長","answer":"それで、あと、前にあった双子の教室云々というところは、ちょっと私、今、お答えできません。","voiceIndex":196,"id":"exchange-066"},{"speaker":"たけうち委員","kind":"質問","question":"先ほどのあくつ委員のところにちょっと関連するんですが、新しくリフォームが加わるということで、結構なことなんですが、そうすると、指定管理料の中で小規模修繕をやる場合に力を発揮されるという認識でいいのか、それとも、いろいろ大規模なものになってきて、別途区のほうからお金が出るような場合にも、何かそれをにらんでのお話なのか、その辺のところでちょっとお聞きしたい。","respondent":"江部健康課長","answer":"ただいまのご指摘のように、施設修繕をする場合に、小規模の１件１３０万円未満のものについては、指定管理料の中に入ったものということで位置づけておりまして、その他の大規模については、健康課で予算を持ちまして、委託で発注をするという形になりますけれども。","voiceIndex":199,"id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この公募のところで、３団体が説明会には来たと伺ったんですけれども、それが最終的には１団体だけしか来なかったというのは何でかなというところと、あと、指定管理になる経緯、前回コナミがやっていたと伺っているんですけれども、なぜ指定管理にしたのかというところも、ちょっとその経緯だけ伺いたいです。お願いします。","respondent":"江部健康課長","answer":"８月、３０日間募集期間がある中で、途中で８月１６日の日に、事業者に対する現場での説明会を行っております。そちらに３者、３団体が参加されて、お話を聞いていただいたです。","voiceIndex":202,"id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、インストラクターがころころかわってくるといったところも、なかなか区民が定着していけないところがあるという声も伺っているんですけれども、このインストラクターがかわってくるというところには、どういう構造があるのか、職員の待遇というのはどうなっているのか、ちょっとお聞かせください。","respondent":"江部健康課長","answer":"それは隠しようもないことですので、民間だからということではなく、民間の中にこそよさを求める事業かと認識しております。それから、インストラクターがかわる件につきましてですが、この５年間につきまして、複雑にかわった、多くかわったということはございません。","voiceIndex":204,"id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、職員の待遇のところで、こういった職員の方がどの程度の賃金なのかというところまでは、区は把握できているんですか。","respondent":"江部健康課長","answer":"施設運営につきましては、指定管理者にお任せしておりますが、数名の常勤と非常勤の組み合わせで、シフト制で行われている状態だとは思います。それで、給与につきましては、把握はしておりませんが、こちらでお願いしている金額の中でやっていただいていると思います。","voiceIndex":206,"id":"exchange-070"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成なんですけれども、一つだけ、協定書に向けての意見として一言あるんですけれども、私もFacebookの発信力というのはすごく評価をするんですけれども、表裏一体、表裏の部分があって、利用者の囲い込みというか、情報の受け取られる方だけが利用するということにならないように、その部分はきちんとチェックをしていただきたいということと、区の施設ですので、利用勝手のいい人たちだけではなく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-071"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"反対です。一言。やはり区民の健康づくりの場ですので、そこに株式会社が入ってくる。それで、働く職員によって、区民の得られるサービスが変わってくるので、この職員の働く待遇、また賃金が把握できないということは、やはり健康づくりにはそぐわないのではないかなと思います。ですので、以前からも言ってきていますけれども、区民の健康づくりに指定管理、株式会社は反対ということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-072"}]},{"id":"topic-06","title":"平成２５年陳情第１６号、食品放射性物質測定器の設置についての陳情","agenda":"平成２５年陳情第１６号、食品放射性物質測定器の設置についての陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"１あったら安全なのか、安全ではないのかというのは、もう独自が判断せざるを得ない。もう一度確認いたします。区として、この放射能の問題に対して、今後の取り組み、どのような形で区民の方々の不安を払拭していくかというところの確認と、再度、今回の陳情の趣旨というのが、あくまでも食品放射性物質測定器の設置についてですので、これに対する考え方を再度お願いいたします。","respondent":"高山品川区保健所生活衛生課長","answer":"やはり膨大な量の物流を統計学的な保障に基づきまして、国等において抽出しまして、モニタリング検査を継続的に実施してきております。","voiceIndex":221,"id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。陳情のタイトルと陳情項目についての質問を、今、させていただきましたが、その他、課長から、再度のご答弁をいただきました。地域の区民の皆様方がしっかりとした情報をとれるような形で、安心できるような情報発信について、今までも続けていると思いますけれども、これから、それは必要以上に、やはりきめ細かく対応を続けていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"第３回定例会におきまして、我が会派のこんの孝子議員より、同趣旨の要請をさせていただいていますので、その趣旨にのっとっての質問をさせていただきたいと思います。ちょっと質問なんですけれども、その中でも、いろいろなホームページへのアクセスが多いというところで、例えば、この窓口というのは、今保健所になっていると思うんですが、現段階でそういったご相談が今でも継続してあるのかどうか。","respondent":"高山品川区保健所生活衛生課長","answer":"それで、ご相談としまして、どのような対応をですが、平成２４年４月以降、新しい放射性物質の基準値が決められまして、そういった形で、乳幼児につきまして、乳幼児の食品については、１キログラム当たり５０ベクレルというのが一つの指標として出されておりますので、当然。","voiceIndex":225,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"乳幼児については、５０ベクレルということで、新たな基準値が発表されたということなんですけれども、これは本当に国が発表することで、これを区が発信すると、これが役目であるという先ほどのご答弁、ちょっと簡単かもしれませんけれども、正確な情報発信等々されていると思うんですけれども、それに対して不安を覚えている方がいるというのが、今回の要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-076"},{"speaker":"井上委員","kind":"提案","question":"それで、今回、ここの陳情の２３区内では、五つの区が持ち込みで検査をしているという状況の中では、当然食の問題というのは、東京都、国、そういったところでの判断が責務であるけれどもという区民への寄り添いという部分だと思うんです。みんな、全部の自治体、それは都と国が責任を持ってやるべきですと思いながらと思うんですけれども、そこのところについては、どんな見解をお持ちでしょうか。","respondent":"高山品川区保健所生活衛生課長","answer":"一方で、区民の不安な気持ちに寄り添うといったことに関して、品川区としてはどのようなという点につきましては、一つ、既にそういった持ち込み検査などを対応している区もあるわけですから、そのこと自体は、別に否定するものではないんですが、では、品川区はどうか。","voiceIndex":229,"id":"exchange-077"},{"speaker":"井上委員","kind":"意見","question":"そんなふうにも、私は考えているので、区民の方たちの思いには沿いたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-078"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、給食食材の測定は、今年４月から回数を減らしてしまったし、牛乳測定は無実施とか、そういったところをもとに戻して、実施をしていくべきだということは、一般質問等でも言わせていただいているんですけれども、そういう中でも、区民の方々は、そうは言っても区はやってくださっていると、やってくれていると。ですがというところなんですよね、今回のは。それは、もう十分わかることですよね。","respondent":"高山品川区保健所生活衛生課長","answer":"２点目の放射線測定器の設置できない理由というんでしょうか、区の見解という部分ですが、できないと申しますよりも、やはり先ほどの説明の繰り返しになりますが、国と区のそれぞれの担うべき役割、責務の部分で、こういった部分は役割が分担されているんだと。","voiceIndex":233,"id":"exchange-079"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、わかってください、わかってくださいではなく、そこから一歩進んで、今まで一緒に測定なんかもしていただいているのであれば、食品測定、放射性物質測定器の設置をしていくべきではないかと思いますし、そんなに高額じゃないと聞いています。私も単純計算で、素人考えなので、あれですけれども、そういった一歩進んで考えていく、検討していただくということをやっていただきたいと私も思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-080"},{"speaker":"渡部委員","kind":"意見","question":"本日、結論を出すということでお願いいたします。態度ですが、私ども自民党でも、この陳情に関しまして、２日間にわたり協議をしてまいりました。しかしながら、今回の陳情項目というのが、あくまでも食品放射性物質測定器の設置ということが主題であり、それに対する陳情項目が上がっておりますので、私たち自民党としましては、今回、この陳情に関しましては、不採択という形にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"公明党は、本日採決を主張いたします。それで、態度としては、採択とします。ただし、先ほどありましたけれども、区に食品のことで相談に乗るということは、その食品がどれぐらいの放射線なのかというのがわからなければ相談に乗れないわけで、その意味での食品の放射性物質測定器の設置だと考えます。第３回定例会一般質問でも要望させていただきましたけれども、我々は採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-082"},{"speaker":"井上委員","kind":"意見","question":"結論を出すということで、いいです。一つ、食品の放射性測定器を設置した場合に、大田区の場合なんですけれども、これを使いまして、学校給食の測定もされているということであれば、今品川区が行っている外部委託の給食食材測定も、こういったところでもできるということも一つ考えれば、いろいろな活用方法ができるのではないかと思いますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":242,"id":"exchange-083"},{"speaker":"鈴木（博）委員","kind":"質問","question":"結論を出す。それで、今日は、また一貫して、その情報発信をしておりまして、１回目と２回目の講演会は、実際に行ったんですけれども、中立的な、説得力のある講演で、非常によかったです。それで、放射線が怖いという気持ちも非常によくわかるんですが、現行のシステムで、少なくとも信頼に足るものだという点を評価すると、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-084"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"本日、結論を出すということで、共産党は採択でお願いします。ですので、やはりそういったところを出せる場所、そして、持っていけばはかってもらえる場所、危険性の認識の差はいろいろあると思うんですけれども、不安だと思う人が安心を得られる場所というのは、区が責任を持って設置していくべきだと私は思いますので、ぜひ検討をお願いしたいと思います。採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":244,"id":"exchange-085"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"松澤議員の質問のところで、認知症対策なんですけれども、ＧＰＳの携帯について、伸びていないと。そのときに、答弁があったんですけれども、やはりこれについて、もう少し研究をして、不安に思っている方たちが利用できる方法について、少し質疑をしたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":248,"id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":59074,"voices":251}},{"id":"h25-20131125-8","meetingId":"h25-cm11","date":"2013年11月25日","dateIso":"2013-11-25","committee":"建設委員会","time":"午前１０時０６分～午後３時５２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６９号議案、品川区営住宅条例の一部を改正する条例","agenda":"第６９号議案、品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今のご説明の中で、まず、被害者の保護等というのがついて拡大されたと。この基本の法律のところなんですけれども、ちょっとお伺いしたいのは、婚姻関係がなくても同居しているということなのですけども、先ごろ、デートＤＶとか、結構、ＤＶがもっと範囲が広がっているというところにおいて、この法自体がその辺もカバーする法律なのかどうか、ちょっと直接ではないのですが、そこが１点気になったことで。","respondent":"大串住宅担当課長","answer":"それからストックの関係です。区営住宅、先ほどご説明申し上げましたように、基本的には親族の要件が要るというのが大原則になっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目の、ちょっと緊急性を要する場合に満室で無理だというのだと、法律はできて広がったかに見えるけども実際には実効性がないということになってしまうので、ぜひやはり絶対数が少ないというところにおいては、やはり確保の面で公営の住宅を増やしていくという、やっぱり社会情勢に合わせてしていくという意味では、こういった要求も出てくるというところで。","respondent":"大串住宅担当課長","answer":"２点ご質問をいただきましたが、それと関連するお話になるのですけれども、基本的にはこういった被害を受けられた方は、都道府県が設置しております配偶者暴力相談支援センター、あるいは一時保護ができます婦人保護施設、こういったところにご相談に行かれます。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そこの秘密の保護というか、そういうのはどういう関係性を持ってやっていこうとしているのかというのと。で、それを申請して、ではそれだったらということで、ほかの、これは何ですか、西大井の第３区営住宅ですかね、そちらの方に移ることもできるということになるのか。ちょっと運用の上でわからないところがあるのですが、そこはどうなるのでしょうか。","respondent":"大串住宅担当課長","answer":"別に、ＤＶに遭われた方がどこにお住まいかということは問いませんので、区民住宅の中にお住まいで、そういった状況に陥られた場合には、先ほど申し上げたような、一時的にはまず配偶者暴力相談支援センターですとか。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"例えば、先ほども一部ありましたけど、確保するとかね。何部屋はそういう方たちのために確保するとかということができるのか、空いているときに、まあ、たまたま空いていたら使っていいですよというふうになっちゃうのか。そこら辺が、うまく救済できるような形ができ上がっていると、わりと緊急性に対応できるような形になっているのかなと思うんですけど、それに対しては何か今後、考え方としていますか。","respondent":"大串住宅担当課長","answer":"なかなか、そういった形で空きを確保できればよろしいのですが、優先度合いというか、そういったところにいけば、いろんなケースの方がいらっしゃいますので、なかなか、その方その方全てにおいて入居が確保できるような状況というのは難しいかと考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"それとも、現行で要は新旧対照表の部分で、旧の条例が適用されるのか。それとも新しい条例でやるのか。そこのところはどういうふうになっているのか教えてください。","respondent":"大串住宅担当課長","answer":"こちらの新しい法律あるいは条例につきましては、ご議決いただければ、年明け１月３日から、こういった状況の方について適用範囲が広がるといったところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あべ委員長","kind":"確認","question":"ほかにご質疑はありますでしょうか。副委員長、よろしいですか。私から２点確認させていただいてよろしいですか。先ほど運用の話がありましたけれども、一般にＤＶの被害で逃げて住宅を用意するという場合、例えば品川の方がそういうことに遭って、品川の住宅に逃げるというのはあまり考えられなくて、これは他の自治体を含めてかなり広域に運用されると理解してよろしいでしょうか。１点だけお願いします。","respondent":"大串住宅担当課長","answer":"おっしゃるとおりです。品川区内でこういった状況になった場合、やはり同じ、同一の品川区にいらっしゃるというのはちょっと難しいかと思います。といったところで、先ほども申し上げましたが、配偶者の相談支援センター。これは都道府県レベルで設置しているものです。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"第７０号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"第７０号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"ちょっと部署は違うかもしれませんけれども、区の統一的な延滞金の考え方は５％というご説明ですよね。それは、その根拠をもう少し説明していただければと思うのですが。５％の根拠。わかる範囲でご答弁をお願いします。","respondent":"小林品川区清掃事務所長","answer":"明確に５％としなければいけない理由はないかと思いますが、準拠しているのは、最終的な、非強制徴収公債権は私債権との関係がありますので、強制徴収する公債権ではございませんから、最後のよりどころは民法の、債権の延滞清算利率の５％。","voiceIndex":31,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点です。１点目は、区民への影響について教えていただきたいのが一つです。２点目なんですけれども、３定にかかった、区税にかかわるところがありましたよね。それと今回ずれているという４定でされたという理由をひとつ教えてください。","respondent":"小林品川区清掃事務所長","answer":"２点目の時期の問題ですけれども、区として基本的な考え方は、私債権の管理に関する条例でご判断をいただく予定になっておりましたので、その結果を得て改正しても、税法の改正に合わせるとすると、本法の施行が明年、平成２６年１月１日なので間に合うということで。","voiceIndex":33,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"後半なのですけれども、私債権の判断結果が出たのでそれに合わせてということは、ちょっと管外になってしまうかもしれないんですけど、ほかの区の延滞金、ほかにかかわる部分もこれから発生してくるということなのでしょうか。品川区清掃事務所長の管轄ではないんですが、延滞金にかかわる部分で、今後、ほかの部署で出てくるという可能性があるのかどうか、わかったら教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"条例改正ということで、現在の金利状況云々というところですけれども、条例改正の目的とか狙い、要は１４.６％からパーセンテージが落ちていますけど、実は延滞金に対する徴収率を高めるのか。どういう目的があるのか教えていただきたい。","respondent":"小林品川区清掃事務所長","answer":"延滞金の狙いは納付促進ですが、今ご説明させていただきましたとおり、現時点では延滞金が発生してございません。ただ、手数料形態をきちっと整えておく整合性から、今回改正をお願いするところです。","voiceIndex":38,"id":"exchange-010"}]},{"id":"topic-03","title":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"駐輪場の増設は理解しているところなんですけれども、先日、新たな駐輪場、自転車駐車場の設置の向かい側の大森駅前住宅の住民の方々から、中止・反対・撤回を求めるという意見が多数寄せられているんですね。そういった面で、住民の方々の理解を得られていないと私は受けとめているのですが、この間の経過を改めて時系列的に、どういう対応を行ってきたのか教えてください。","respondent":"谷口交通安全担当課長","answer":"それから業者選定等進めまして、１１月から実施したいと考えていたところですが、大森駅前住宅の皆様から説明会を実施してほしいというご要望が再三寄せられまして、１１月１１日にこの住宅内で説明会を実施したところです。","voiceIndex":52,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとわからなかったのが、９月補正で、１０月２１日決定をし、業者を選んで、１１月実施の予定だったと。ここまではいいですね。住民の方には、１１月１１日、ここの住宅の方に説明をされたと。１１月１１日ですね。で、１２月６日工事実施のお知らせというのはいつ配られたのか、ちょっとこれをもう一回教えてください。","respondent":"谷口交通安全担当課長","answer":"工事実施のお知らせにつきましては１１月６日に配付いたしました。大森駅前住宅の理事長の方には１１月２日に、自治会長がちょっと体を壊されているということでございましたので、理事長のほうに工事を実施しますというご連絡を申し上げたところです。","voiceIndex":54,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"こういった案件では、もし地域の方でご不満があったり、意見したいと声が聞こえてくるのですが、今回、９月補正のときに聞こえてこなかった。現時点で、多分、私のところにも、自宅にもファクスでいろいろご意見をいただいたので、理解は得られていないと思うんですが、課長はその辺、どのように受けとめていらっしゃるのか教えてください。","respondent":"谷口交通安全担当課長","answer":"いろいろ説明会の中で、明日、説明会を実施予定なんですけど、いろいろ頂戴したご要望、ご意見については、真摯に、明日も含めて回答していきたいと考えております。","voiceIndex":56,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住民に説明がないということに対して１点と、あと、今お話がありました、外部の人々による騒音。放置自転車による歩道での事故。４点目に、水神公園の駐輪場拡大が最適ではないでしょうかと書かれているので、ちょっとこの辺の検討についてもお答えいただきたい。ちょっとその辺を伺いたいのと。だから水神公園のところが、具体的に言うとどういう方向性になるのかを含めて教えていただきたいと思います。","respondent":"谷口交通安全担当課長、松代防災まちづくり事業部長","answer":"ほかに駐輪場がないのかということで、昨年から駐車スペースがないか、民地も含めまして、区道上も含めまして、ずっと検討を進めてまいりました。なかなか、そういった意味では、十分な説明とご理解という点では不足したところがあったかに思いますが、こういった点をぜひ勘案していただきまして、地域の課題をぜひ共有していただき。","voiceIndex":58,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、私は一つ聞きたいのが、水神口のところ、どのような対策をイメージされているのか、もうちょっと具体的にお伺いをしたいのと、私はもっと周辺を見て検討が必要ではないかなと思うんですね。そういった面で私は、あしたもお話し合いがあると伺っていますが、話し合いがされる予定なのに、その前日に決めてしまうというのはないであろうなと思うのですが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"そういった意味では、今ある公園の施設を一部改良して、今の駐輪場の、そもそも段差があって利用等になかなかしにくい面もありますので、そういった部分を少し利用しやすいような形と、今の公園設置の一部をそういった形で拡充できないかというふうに思いを持っております。","voiceIndex":61,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"水神口のところをもうちょっと具体的にお伺いしたいのですが、公園法の中で広げていくというところでは、めど的には時間がかかりそうなのですが、いつぐらいまでにどのぐらいの規模増やしていけるのかというところで、今回、当日利用なんですね、１６５台ね。","respondent":"谷口交通安全担当課長、松代防災まちづくり事業部長","answer":"地下式にかかる費用、従前もちょっとご説明したことがありますけど、サイド式なんですけど、２００台の地下式をつくるに当たっては、調査研究で二、三千万かかります。で、設置に１億かかります。水神公園のもう少し具体的なですけれども、申しわけありません、具体的なところはまさに今、検討中です。","voiceIndex":63,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もちろん地下式だけではなくて、いろいろ建設するのにもかかっていくのが当然なので、余分な自転車は整理していく方向はもちろんそうなのですが、駐輪場対策って本当に、さまざまな対策をしていかないと、まちづくりにおいて、いかないので、駐輪場だけではないと思うのですが、私は本当に、ＪＲの鉄道事業者に対しての具体的な、あの地域の困難さも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"それから第２下川ビルに塾が入っているんですよね。そこには相当、放置自転車があるということは、私も何回も言っているのですけれども。さて、そういうことをずっと考えていくと、違法駐輪が多いところに駐輪場を設置して、そこに駐輪を指導するような方法をとれば合理的であると思うのですが、そういうところをなぜ検討されなかったのでしょうかということをまず確認させてください。","respondent":"谷口交通安全担当課長","answer":"それを設置することによって、各商店に対する出入りの障害であったり、自転車と歩行者の交通事故も当然懸念されますので、そこの部分は設置しないということで判断したところです。","voiceIndex":67,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"もう少しちょっとお伺いしたいんですけど、日立ソリューションズの大森駅側のほうです。実はここが一番多いということはもうご存じだと思うんですけれども、そこになぜつくらなかったのでしょうか。単純な話なんですよ。多いところにつくっていただいたほうが。ましてやこの辺はいわゆる商業施設が入っているところでありますから、あえてそういうところを避けた理由をもう一度聞かせてください。","respondent":"谷口交通安全担当課長","answer":"商店に出入り口から出てくる方は当然、自転車のことは想定されていないと思われますので、出てきた方と、通行も含めての、自転車の事故は当然想定されますので。出入り口付近に設置することによる駅前の景観も含めまして、いろいろ総合的に判断したところです。","voiceIndex":69,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"だから、確かにお金はかかったかもしれない、大田区の場合。だけれども相当効果があったことは確かであって、その余波がこっちに来たということも事実である。となると、私の思いとしては、駐輪場の設置ももちろん必要ですよ。大田区の施設が目の前にあるわけですから、そういうことをお考えになって、ハードなのよりソフトなところで駐輪場対策をしていくといいと思うんですが、いかがでしょう。","respondent":"谷口交通安全担当課長","answer":"委員ご指摘の大田区で、いろいろ人を配置しながら指導・啓発をやっていると伺いますけど、当然、区としましてもハード・ソフトを含めて、ハード面を整えまして、ソフト面につきましても来年度、シルバーであったり警備員を配置して指導・啓発、また撤去。","voiceIndex":71,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"そうだね。その部分は理解するんだけれども、どうしてもついていけないのが、今既に違法駐輪がある場所につくらないで、ここにつくるのかという、ここの疑問がずっとついて回るんですよ。確かに法律の関係なり、それから条例上の仕切りなりでわかるんだけれども、何といったらいいのかな、もう少し外に、ハード面も含めて、総合的な駐輪場対策を検討すべきではないかということを思うんです。","respondent":"谷口交通安全担当課長","answer":"それで、終わりではございません。大森駅周辺の放置自転車対策につきましては、引き続き調査研究しながら、あらゆる手法・手段をとりながら、地域住民にはご理解が得られるように努めてまいりたいと思います。以上です。","voiceIndex":73,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"意見","question":"だけれども、私どもとしては総合的な駐輪場対策を議論していく中で、ここにつくることについてはいろんな意見があることが象徴するのだけれども、何というかな、もっと総合的な対策を検討して、どなたの方々にもご理解し、納得していただくような対策を進めていくべきであると思っていますので、そのことについてのお考えを最後に聞かせてください。","respondent":"松代防災まちづくり事業部長","answer":"物理的には、今、言葉で言ったようなことを右から左になかなかできないのが現状ですけれども、まずそういった取り組む姿勢をご理解いただきたいということと、あわせて解決の段階、その状況状況で、まずとり得る方法をとりながら、今。","voiceIndex":75,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"まとめますけど、当然、全ての区民の方々を相手にする仕事なんですよね、皆さんのお仕事というのは。ですから、その中で最大公約数といいましょうか、できるだけの努力をして、多くの方々にご理解いただいて、なおかつ負担の少ないような対処をしていく。だから、そういう単純予測に立って、これからも駐輪場対策等を進めていってくださいますようにお願いしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、お話しいただいて、駐輪対策としての課題で、議会からも要望があった。で、９月補正でもこちらのほうで認めた。そういう流れの中としての放置自転車対策の課題。そこのところのお考えから伺いたい。先ほど、道路幅の広い、駐輪するには適した場所ということは聞きましたけれども、そこのところもお含みおきをいただきながら、もう一度、すみません、そこの件に関してお答えをいただきたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"それは現実ですので、やはり禁止区域を設けるのと同様に、そういった収容施設を設けるというのが、一方でとらなければいけない対応策だろうと考えています。したがいまして、今回も直近のところで収容できる施設ということで考えたところがここです。","voiceIndex":78,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"それは十分わかりますが、確かに区としての課題を解決すべく駐輪対策を遂行しているというのは十分わかります。そこのところの温度差をどのように埋めるか。埋めることによってさまざまな問題が対処されていくと思うんですけれども、そこのところの温度差を埋めるには、どのようにすべき、したらいいかと。どのように考えているのか教えていただきたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"いろいろとご不安等がある、そういったことは、今の形で想像できること、もしくは今後起こり得るであろうというところも含めて、誠心誠意、もって、区はその後、設置するだけが目的ではございませんので。","voiceIndex":80,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"事業の発案、着手、完了までの間に、確かにスピード感という、地域課題に迅速に対応するという区の責務の重さ、十分に感じて日夜業務に励んでいただくのはわかるんですけれども、それがかえって、スピード感が速過ぎてしまって、このように地域の方の欲するところと行政のする事業との間にスピードのそごが生じていることがまま見受けられる部分がありますので、そこのところを、対処型。","respondent":"松代防災まちづくり事業部長","answer":"確かに今、委員がおっしゃられるように、スピード感の中にも、今、いろいろと地域の方々の不安等を、我々計画を進める者がしっかりと酌み取りながら、それを説明し、理解を求め、ご理解のもとに進めるというのは、これが基本だと考えています。","voiceIndex":82,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"もう一回言いましょうか。これはおそらく、今の時点では、条例が可決される前の時点では、非常に民地の近くといったらいいんですかね、大森駅前住宅等の位置関係のような、非常に区民の住宅の近くにつくられている施設はおそらくないと思われるんです、現状では。だから、そのことについてしっかりとした考えを持っていくべきだと思うんですが、いかがでしょうか。","respondent":"谷口交通安全担当課長","answer":"委員からの、民地、要は住宅の前。大森駅前住宅のような大規模マンションの前には今回初めてとなります。ただ、区内２３カ所の区営自転車駐車場がありますけれど、この中には荏原町であったり旗の台であったり、要は住宅の直近の付近にも設置しています。","voiceIndex":84,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要は、今までにないところにつくろうとしているわけですから、それがやはりはっきりとした防犯上の対策なり、それからずっと部長がおっしゃっていたような理解を求める仕組みなりを、ここだけ特別というのはなかなか言いにくいのかもしれないけれども、だけどこれだけ民間の住宅が近い位置もなかなかないわけでありますから、そのことはこれからもあるかもしれない話であるから、ぜひ十分に検討して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"で、これは非常に要望があったと私は認識しているし、多分ここにいらっしゃる委員の皆さんも非常に要望があって、早くここに駐輪場が必要なんだと、皆さんは主張していたと思うんですよね。その要望というのはどういう経緯があって、どれだけのものとして区として補正にかけてまで重要視して、今回、スピード感を持ってしたかということの思いでありますとか、それをちょっと確認したいということ。","respondent":"谷口交通安全担当課長","answer":"で、今回つくったからといって、では放置自転車がなくなるのかと。それは、私自身もまずゼロにはならないと思っています。しかしながら、区としましては一歩一歩、放置自転車対策につきまして取り組んで、地域の社会のために貢献していきたいと考えております。","voiceIndex":87,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"で、今、どうもこの議論を聞いていると、それが、何というのでしょうか、その議論が、さも何か積み上げて、やっとここまで来たのにというところの思いが、何となくマイナス方向に行っているような気がして残念なのですが、それだけに住民さんたちのご理解というのがやはりきちんとしていかなければならないのだろうなと、非常に私も考えさせられた事案かなと思っています。その辺について。","respondent":"松代防災まちづくり事業部長","answer":"先ほどから申し上げていますが、重ねて、あすの説明会も含め、しっかりと誠意を持ってお話を続け、ご理解を得るように努めてまいります。","voiceIndex":89,"id":"exchange-030"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"今、ほかの委員さんたちからの質問もお聞きしながらですが、この大森駅前周辺の駐輪場の増設は、私どもとしても大変要望しておりましたし、スピード感を持ってという、ほかの委員さんのお言葉をかりれば、そういったことも要望してきた。現時点で、その進め方でどのような状況になっているのか。そこをお聞きしたいと思います。","respondent":"谷口交通安全担当課長","answer":"その場で、いろいろご要望、ご不満、撤回論も含めてお話を聞いたところです。あした予定されております説明会におきましては、地域の皆様、多くの方にご出席いただきまして、その場で、１１日に頂戴しましたご要望、ご意見、一つ一つ丁寧に不安を解消できればと考えております。","voiceIndex":91,"id":"exchange-031"},{"speaker":"こんの副委員長","kind":"提案","question":"そこで、いろんな要請の項目が出ておりますけれども、先ほどもご答弁いただいたんですけれども、改めて、大事なことなので確認させていただきたいのですが、そのご不安なり、また皆さん方のご提案なり、そうした具体的な項目でどのように対処し、どのように対応され、どのようにしていこうとお考えなのか、恐れ入りますが、もう一度ご項目別にご答弁いただければと思いますが。","respondent":"谷口交通安全担当課長","answer":"防犯上の問題は、今度の拡張予定の場所につきましては、防犯カメラを設置したりですとか、夜間帯は音の出ない機器を使ったりだとか、放置利用の増える状態も想定されますので、それは警備員の配置だったりシルバー人材センターの配置だったり。","voiceIndex":93,"id":"exchange-032"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ご理解を得て進めていくというのが大事であろうと思いますが、この項目、皆さん方から、例えばこの項目に対して先ほどからもご答弁、ほかの委員からの質問に対してご答弁されていたのも伺っているので、そのことに対して誠意を持って答えていくという姿勢も伺っております。決して、ほかのところでもそのご理解を求めずして進めたところというのはないと思うんですよね。意見にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-033"},{"speaker":"木村委員","kind":"質問・要望","question":"大変、放置自転車が多いという地域であれば、やっぱり駐輪場というのが全体に必要になってくるだろうと思います。ただ、住民の方々の心配というものも幾つか挙げられておりますけれども、そういうことに対して、先ほど、しっかりと考えをあすの説明会でお話をするということを聞きました。ぜひ、そのことに対してお聞かせいただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"ただ、手前みそですが、一応、工事に関しましては、事前にご質問をしたり、あと各町会、関係する町会には事前にご説明に上がったりとか、そういう手続も踏んでいるところですので、どうか明日の説明会につきましては、一つ一つ不安の解消に努めてまいりたいと思います。","voiceIndex":96,"id":"exchange-034"},{"speaker":"木村委員","kind":"質問・要望","question":"ご答弁で十分、そういう意味では通知をしてということを言っておりますけれども、その地域の住民の方々にしてみれば、本当に突然そういうことがあるということを知ったと。驚いたというようなことを聞いております。その点をこれからしっかりとやっていただきたいなと思っています。これは要望ですけれども、そういう意味では、もっとしっかりと住民の方々に説明をしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-035"},{"speaker":"こんの副委員長","kind":"質問","question":"動議を出します。その理由は、今回設置するに当たっての、先ほども質問をしてまいりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-036"},{"speaker":"こんの副委員長","kind":"意見","question":"いわゆる、今回のここの採決に関して、私どもは住民の方へのご理解をいただかないまま、これが設置されていくというところでは、今現時点で、あすの説明会もありますので、その説明会の皆様のご理解も聞いた後に採決をしても、結論を出すということでもいいのではないかという考えを持っておりますので、ここで、また別途委員会を設けて結論を出すという考えのもと、動議を出したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"すみません。質問なのですが、保留となると、今後どういう扱いになるのか、ちょっと具体的に教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問","question":"今回、今ここでというのは、説明会があしたあることから、いわゆるこの説明会でどのようなご理解を得られ、どのような形だったのかをお聞きするために、その後いわゆる最終本会議の間までにまた別途委員会を設けて、そこの状況をお聞きして、そして決めていくという形で考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"これは、審査予定表というのを渡されて、それで議案の審査ということがあって今に至っているわけですよ。で、ここで議論するのに、いろいろお時間を使って議論したわけですよ。であるならば、一番初めに諮るべきなのではないのですか。皆さんしっかりと議論されているではないですか。それと本会議の間にまた再度、議決しましょうという話になるわけじゃないですか。私は意味がないと思うんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-040"},{"speaker":"原委員","kind":"確認","question":"当然、議員ですから、議会の運営のやり方とか段取りはご理解されていると思うので、ほかに動議を、同調される方がいるかいないかの確認と、それからあとは実際の問題としては、いつ出されても構わないので、それはそれで。ですから粛々と委員長方で対処されればいいのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"今の動議でありますけれども、当委員会に今度の本件委託をされたわけでありますので、今日の委員会の中で決を出していきたいというのが私の意見になります。ですから動議に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"動議に反対です。やはり、散々今まで議論していたわけですから、この中でやはりこの結論を出す。付託をされたという私たちの使命もありますので、きっちりと今の審議の中で結論を出すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-043"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ただいまの私の動議に対しての否決という形になりましたので、私どもは現段階として結論は出せないという姿勢です。ですので、態度は保留とさせていただきたいと思いますので、ご了承いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"意見","question":"ですが、この中にはやはり十分な説明をする案件と、それから先ほど部長がお話しされたように、特に１８番地につきましては緊急避難的なものであるということ、それから管理・防犯・セキュリティーに対しても十分していただくこと、それから適地がほかに見つかったら即、撤去するような、特別な配慮をしていただくことを改めて自民党としてお願いさせていただいて、賛成であります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-045"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、全体のメリット、各委員、ほかの委員が皆さんおっしゃっているとおりだと思います。全体のものと、それから約８００戸の世帯との問題。ですから、その手順としてはもう少し段階をうまい形での対処、事前事前でやってほしかったと。ですから、あくまでもここの個別のいわば８００世帯の、言葉表現は適切かどうかわかりませんけど、価値観を落とさないようにしていただきたい。それが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"意見","question":"駐輪場の必要性については、この会議、同意がとれている。これは確かです。しかし、この場所でいいのかということが、理解が得られていないことが今日明らかになったと思います。おっしゃっておられること、ごもっともであると思っています。そういった意味では、明日、２６日、話し合いがあると言われていますので、今日は決定できないといったことで、反対の立場を出します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろご意見、状況も確認させていただきました。やはり、やり方論になるのかな。こういう問題があって、他の地域からも要望がたくさんありましたと。それはもう仕方ないですね。ここに駐輪場が必要ですから。ということが今回、明らかになったわけですから、それはしっかり伝えていただいて、何とかご理解いただけるように最善を尽くしていただきたいということで、７１号議案については賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-048"},{"speaker":"あべ委員長","kind":"質問・要望","question":"ここで委員長として一言申し上げたいと思います。もう、これが終わったから、あすから工事、あさってから工事ということではなくて、きちんと手続を踏んでいただきたいと思います。それから二つ目。これは区からも答弁がありましたけれども、駅周辺での総合的な対策ということを、引き続き熱心に進めていただきたいと思います。そういう考えですが、皆様いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-049"}]},{"id":"topic-04","title":"第７８号議案 指定管理者の指定","agenda":"第７８号議案 指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"選定理由のところなんですが、５番目のところ、管理経費、コスト削減案、滞納対策と書いてあるのですが、この経費、コスト縮減というのがどういう意味なのか、額が出ているのだったら幾らか縮減しているのかという、ちょっとこの中身を一遍教えていただきたいのと、共産党としては直営を求めているのですが、改めて指定管理者の制度をとっている理由を聞かせてください。","respondent":"大串住宅担当課長","answer":"額につきましては、あくまでもプロポーザルというところで各３社のほうからご提案をいただいているものですので、ちょっとこの場でお幾らというのは、なかなか答えにくいのかなと。","voiceIndex":137,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"ご説明の中で、額は示せないと。どこをどう工夫して削減をしているのか。やっぱり例えば滞納一つをとってみても、やっぱり困難が始まった区民の方に対して、自治体のいろいろ手だて、特に福祉面での手だてができるというのがとても重要であると思うのですが、その辺が、私たちはやはり、直営でない、指定管理者のところでは、不十分ではないかなと思っているのですが、その点はいかがでしょうか。","respondent":"大串住宅担当課長","answer":"基本的には皆さん同じ回答です。丁寧に対応していく。初期段階のところからなるべく、要するに滞納額の小さなところから小まめに対応していく。これしか方法はないよというお話でございました。","voiceIndex":139,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"ローテーションの見直しで給与のところが縮減できているということなのですけれども、なかなかつかめないと思うのですが、お一人一人、働いている方の給与に響いているのかどうか、そこまで把握しているのでしょうか。人員は変わりないということなのですが、やはり一番関心事は、プロポーザルをやるたびに下がっているという声も聞いているのですが、その辺はいかがでしょうか。","respondent":"大串住宅担当課長","answer":"ですので、例えば西五反田の東館、西館だけのローテーションということではなく、ほかの地域のほかの物件、あるいは東急がほかに手がけていらっしゃる分譲住宅ですとか、そういったところのローテーション、こういったものを活用しながらというふうに伺っているところです。","voiceIndex":141,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"指定期間が４年間。指定管理者はたしか５年ぐらいだったかなと思って、なぜ今回４年間なのかなということ。西館のほうはまたこれから指定管理者の期限が来るのかな、どういう感じになっているのかなと思って。で、それと、今回決めた中での補完的な何かメリットがあるのかどうか。同じような効果が上がるような対処がされるのかどうかをお聞きしたいです。","respondent":"大串住宅担当課長","answer":"４年間としたところですが、これは公募のときにも１度、委員会でご説明させていただいたかと思いますが、西館と東館は、それぞれ開設の年次が１年ずつずれております。で、東急コミュニティーが最初に指定管理に入ったのが、平成２０年の西館から入ったんですね。","voiceIndex":143,"id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"わかりました。１点だけ確認します。４年間にして、平成３０年以降は、一体的な形で指定管理という形になるのですけれども、そうすると西館のほうの指定管理というのは、５年になるのですよね。これはどういうふうになっていくのかなというか。","respondent":"大串住宅担当課長","answer":"西館のほうは昨年、プロポーザルを実施しまして、平成２５年４月から平成３０年３月３１日までという５年間で、昨年は議決をいただいております。ですので、西館は５年間、今度の東館は４年間ということで１年のずれが解消されるといった流れです。","voiceIndex":145,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対します。ちょっと意見を述べさせていただきたいのですが、先ほども述べましたけれども、住まいは人権ということで、ぜひ区で直営でやっていただいて、区民の住環境、しっかりと実態をつかんでいただきたいのと、やはり福祉の充実などとぜひ結びつけていただきたいということで、区営住宅の指定管理者には反対なので、本条例に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-055"}]},{"id":"topic-05","title":"第６６号議案、平成２５年度品川区一般会計補正予算（歳出、建設委員会所管分）","agenda":"第６６号議案、平成２５年度品川区一般会計補正予算（歳出、建設委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"道路改良費の追加分なのですけれども、予算では３,８３８万６,０００円。これの、当初、何件ぐらい見込んでいたのか、どのぐらい件数的に増えていくのか、そこをあわせてお聞かせください。","respondent":"中村建築課長","answer":"で、当初の予定といたしましては、委託料、現地の測量の委託ですが、これが、２２０件が１７件増加見込みで２３７件あります。そして、工事のほうですけれども、こちらが、当初見込みが２６０件が、これもまた年度内での決算見込みとして２９７件と見込んでおります。","voiceIndex":159,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それぞれ増えるわけですけれども、これの増える要因、何が背景にあるのかを教えていただきたいのと、あと事業の概要を見たら、助成金と奨励金と、二つ、２段階に件数がなっていたのですけれど、ちょっと助成金と奨励金の違いを教えていただきたいのと、その辺の件数の変化、推移をどう見ているのかも教えてください。","respondent":"中村建築課長","answer":"増えた要因ですけれども、こちらの、今までの年度当初からの実績の見合いから今年度の年度内のこれからの部分は推測しているわけですけれども、要因としましては、これははっきり申し上げることはできませんけれども、今、確認申請数なども。","voiceIndex":161,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"助成金と奨励金のところというか、だからこの間の件数の変化に対する評価をあわせてお伺いしたいなと。今回だけの、増えているのか、今までの経年的なものも含めてどうなのかなと思ってお聞きしたんですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問","question":"その下の段の、都市防災まちづくり事業費の追加分についてお伺いしますけれども、補正で前倒しでやっていくということなんですけれども、中身的に、これは専門家派遣と、あと除去助成ということになっていますけれども、基本的に不燃化の取り組みの中で、コア事業、今までと新しい部分がありますよね。除去はいいんだけど、更地にするだけではなくて建て替えの支援がどうなっているのかとか。","respondent":"品川木密整備担当課長","answer":"これを前倒しということで、今回、補正予算を上げているのですが、まず１点目、コア事業のほうですが、今回、コア事業のほうは主に、これは東京都のほうの不燃化特区のルールの中であるのですが、戸別訪問をやることによってコア事業とみなすという条項が。","voiceIndex":167,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"提案","question":"そういった面では、今回、１０年プロジェクトをかけたということは、２０２０年までに進めるというところですよね。私、その辺では大変、困難さが。木密を解決するという点ではやっていただきたい思いもあるのですが、そういった面では強引というか、困難を地域に起こしてしまうのではないかなという、すごい懸念を持っているのですが、その点はいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"そんな中で、やはり反対者の意見というのは非常に大切にして、よく話を聞いて、その反対者の方が一体何に不満を持っているのか、どうすれば解消できるのかというところは十分聞いて、こちらもできる限りの対応はしていきたいと考えています。","voiceIndex":169,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"提案","question":"もう一点なんですけれども、今回提案の地域、２９号線沿道が広く含まれているといった意味では、道路に反対の声が多数あるということと、やはり道路に合わせて沿道を耐火づくりの建物にしていくということに対して、まちの違和感が大変大きいというか、そういったがっちりとしたまちは望まないという声もたくさんあるんですけれども、またそういった中で、やはりこれを進めていくことが、本当に。","respondent":"品川木密整備担当課長","answer":"ただ、どうも説明会等で出る写真が、道路の沿道が非常に高層ビルになっているようなイメージの写真しか出ないというところもあります。ただ、我々が東京都と一緒に説明している中では、まあ東京都もそうなんですけども、補助４６号線のようなイメージですね。","voiceIndex":171,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"たびたびやっているので終わろうかなと思ったんですが、ちょっと、補助４６号線が出たのでね。補助４６号線、すぐ近くなんです。私、毎日通ってるぐらいよく知っていて、高いイメージではない。そうですよね。普通の住宅。延焼遮断帯効果があるからという言葉で、仕方がないなと思って賛成してらっしゃる方もいるんだけれども、実態がどうかというのも正しく伝えるべきだと思うんですけど、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"たびたびご説明があまりよくないようで、非常に私の説明を、もう少しわかりやすく説明しないといけないなと反省はしているのですが、耐火建築物イコール高層ビルというような形で考えているように思われてしまうのですが、耐火建築物というのは、現在では。","voiceIndex":173,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もちろんそういった認識を持っていますけれども、東京都が初め、高層の図を示してしまいましたよね。あれが影響しているのと、補助４６号線が今後。とてものどかな、補助４６号線、沿道ですよ。耐火づくりの２階、３階で固めた道路では決してないんですよ。そこのところをやっぱりきちんと伝えていただきたいな。そのことは、だから区民にわかりやすく説明をしていただきたいなと思います。答えは求めません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"一般財源があってということなんですけれども、これは全額出るわけではないんですか、東京都のほうは。そうすると、もっとこれが予算的にかけなきゃいけないことになると思うので、それは東京都との関係では、すぐ、申請すれば出してもらえるのか、一般財源からある程度出さなきゃいけないとなると、基金から出していくのか、出どころはどこから出していくのかという、その辺を教えてください。","respondent":"中村建築課長、品川木密整備担当課長","answer":"ですので、細街路の拡幅整備事業につきましては、大体、前年度の見込みをもとに次年度の予算を算出してという姿勢を変えないでいこうと考えております。今回の補正予算も、基本的にはこれに合わせた形で要求をしていくというような形になっています。まだ前倒しのほうは東京都がやると言っておりませんので、区のほうでこういうふうに補正予算を積んで要望をしていきたいと考えております。","voiceIndex":176,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"拡幅整備事業についてはわかりました。それと、密集住宅市街地ですけれども、多分これは、かなりいろんな動きが出てこようかと思いますので、やはり財源的にちょっと厳しいとなって、なかなか、とまってしまうようにならないように、ちょっといろいろ工夫していただいて、速やかに進められるところは進めていっていただきたいと思いますので。意見という形で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-065"},{"speaker":"伊藤委員","kind":"提案","question":"自民党としては、今回の補正予算、賛成いたします。ここに提案されております防災まちづくりについては、さまざまな意見がありますけれども、私ども自民党としては延焼遮断帯の効果はあるということ、それからこのことについての事業を進めていることによって、多くの区民の方々の生命が救えると考えていますので、ぜひ積極的に進めていただきたいところをお願いして賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて反対します。細街路の拡幅整備事業は賛成します。もう一つの密集住宅市街地整備促進事業についてですけれども、補助２９号線が木密の地域を救う状況にないということが明らかになりつつある中で、道路づくりと不燃化を一体で進めるもので、地域の住民の方からたくさんの反対が出ていますので、この点は賛成できないので反対です。あわせて、だから態度としては反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"この間、いろいろと地域の中で進めようとされていて、やはり早く考えようかなという方たちもいらっしゃるんですよね。なので、不安な方もたくさんいらっしゃると思うんですけれども、そういう方たちの要望があったら、それに対応していただく形で、財源確保もしっかりとしていただくようにということで、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-068"}]},{"id":"topic-06","title":"平成２５年請願第１５号、八潮から区役所などに行けるコミュニティーバスを求める請願","agenda":"平成２５年請願第１５号、八潮から区役所などに行けるコミュニティーバスを求める請願","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"あれはどのぐらいのコストがかかっていたのでしょうかとの確認。つまり、全く無料のバスですから、その地域を回してどれだけの費用がかかるかという算定モデルもあるので、そのことを教えていただきたいのと、それから現況、大井町から今でも走ってますけど、大井町からしながわ水族館まで走っている、その年間コストがわかれば教えていただきたいのですが、いかがですか。","respondent":"多並公園課長、藤田都市計画課長","answer":"詳しい、今、資料は手元にございませんが、数千万程度の運行経費をかけながら。百万単位ではなくですね。一つ上の桁ぐらいの運行経費ということで運行したかと記憶しています。同様な金額が、走っていた荏原の路線だと思いますが、それについてはなかなか乗降客が増えず、最終的には大井町からの直行便だけに変更したという経緯があります。","voiceIndex":195,"id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問","question":"しながわ水族館までのバスは無料ですから、つまり全額が税金の負担となっているわけですからね。それは皆さんご承知のとおりであって。だから、そういうことを冷静に考えていくと非常に厳しいと判断するのだけれども、改めて品川区のお考えをお聞かせください。お願いいたします。","respondent":"藤田都市計画課長","answer":"これまでの間、区で数年前に何度かまとめていただいた……まとめていただいたというか、陳情や請願が重なった時期がございまして、その時期に検討したようなこともありますけれども、そのときにも、約２,０００万から４,０００万近くの金額が、赤字が。","voiceIndex":198,"id":"exchange-070"},{"speaker":"伊藤委員","kind":"提案","question":"そういうことを冷静に考えていくと、この請願の紹介議員が言った提案なんだけれども、どういったルートを開拓して、どういうコストで、どういう料金設定をもとにしてバスの運行会社と協議をしていくかが全く書かれていないわけですよ。まして、今お話がありましたように、１路線４,０００万ですか、年間。１９区と、今、お話しされましたけれども、成功しているものがあれば教えてください。参考までに。","respondent":"藤田都市計画課長","answer":"すみません。ちょっと答えが、違う、反対側の話になってあります。","voiceIndex":200,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはちょっと意見なのですが、質問をします。品川は、駅に着いても駅の構内が延々と長いので、何百メートルあるんでしょうか、５００メートルあるとか言っていると思いますけれども、駅の構内を歩くだけでも大変だと言われています。こういった声が届いているのですが、八潮の方からさまざまな不便を解消してほしいという声が本請願なのですが、これに対してどう受けとめていらっしゃるのかが１点です。","respondent":"藤田都市計画課長","answer":"それからコミュニティーバスのほうですけれども、何度かご説明されていますとおり、既存のバス等も、それから鉄道も充実している中でのコミュニティーバスについては、その検討については慎重に行うべきと考えています。","voiceIndex":202,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この考えは私、やさしくないと思うんですね。で、一般質問でも行いました、既存のバス路線で補えるところは大いに補ってほしい。ですから、検討は幾らでもできると思うんですよね。あまりかたく考えないで、やわらかい頭でいろいろ検討していただきたいなと思っているんですけれども、その点、特に社会的要因考慮というあたりで、やはり見直していただきたいと思うんですけれども、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"困難地域に対してですけれども、これも、なぜ困難なのかというのが、理由がいろいろあると思いますので、その辺を十分考えながら、慎重な議論をしていく必要があると考えています。","voiceIndex":204,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"確認","question":"社会的な要因を考える。慎重に考えるということは、検討の余地があるということと捉えていいのでしょうかね。先ほどから、今回は八潮の方たちから出された請願ということで、八潮の地域の方が区内で移動するのに困難を抱えているという認識があると捉えてよろしいのでしょうか。その点を確認していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"提案","question":"すみません。最初のご説明は伺ったんです。１点です。ぜひ、そこに注目してほしいのは、私は、だから私が聞いたのはごく一部の方の意見だと思います。だから、コストの面っていろいろあるかもしれませんけれども、ぜひ工夫をして、まちを元気にするという立場でとっても有効だと思うので、ぜひこの請願の趣旨を受けとめていただいて、区も考えて、交通会議に提案してほしいなと思うのですがいかがでしょうか。","respondent":"藤田都市計画課長","answer":"やさしいまちづくりというお話がございましたけれども、やさしいまちづくりは、私ども、これをやめてしまったということではなく、しっかりこれは進めていかなければいけない事業だと考えてございまして、今年度・来年度を含めて。","voiceIndex":210,"id":"exchange-075"},{"speaker":"こんの副委員長","kind":"質問","question":"この請願に関連して、今定例会のときにもご質問が若干ありましたけれども、現状をちょっとお聞きしたいのですけれども、地域公共交通会議、これの今の進捗状況、それからスケジュール的にはどうなっているか。あのときたしか、学識経験者の方等のことがあったかと思いますけど、もう一度そこのところを教えてください。","respondent":"藤田都市計画課長","answer":"おおむねその辺も見通しがついてきてありますので、今、最終的に現況報告がきっちりできるような準備を進めまして、いつというお約束をすると、また時期がずれてしまうと大変申しわけなく思うのですが、少なくとも当初の予算の中では。","voiceIndex":212,"id":"exchange-076"},{"speaker":"こんの副委員長","kind":"提案","question":"私どもも、このバスという観点、それから公共の交通というところでは、非常に大事であるといったことから、地域公共交通会議で提案をさせていただいて、そこで慎重に今後のあり方というのをぜひ検討していただきたいということを考えます。ですので、この八潮の地に限らず、品川区全体のことを考えていただくということが大事かなと考えていますので、その状況をお聞きしたところであります。結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-077"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これから少子高齢化が進む中では、国、東京都、それから品川区が一丸となった福祉のまちづくり、総合的なまちづくりを展開していってくださいということを改めて要望すると同時に、八潮地区の交通での改修については、せっかくオリンピックの会場にホッケー場ができるわけですから、そういう時期を捉まえて、これこそ国、東京都と連携をとって、例えば新駅をつくっていくなり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-078"},{"speaker":"こんの副委員長","kind":"質問","question":"私どもは、先ほども少し状況をお聞きしました地域公共交通会議、この中でしっかり慎重に決めていただくというのが大事であるという、こうした姿勢から、八潮に限らずという、区全体の会議が必要ということから、本請願に対しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"採択を主張します。ちょっと意見。コミュニティーバスは区民が求めています。区内移動、不便なところがあります。介在して、ぜひ区内移動がスムーズにできるように。特に高齢者、体の不自由な方々、妊婦さん、お子様連れなど、外出が楽しめるようなやさしいまちをつくっていくというところで、ぜひコミュニティーバス路線の確保を必要と認識していますので、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-080"},{"speaker":"西本委員","kind":"提案","question":"ただ単に１日に２本とか３本では意味をなさない。ただ、税金を使っても効果があるんだよということであれば、それは前向きに考えていただきたいと思いますし、それでもほかの公共施設があるので、交通がいろいろあるので、それをもっとうまく組み合わせながら使っていただくような工夫があってもいいんじゃないかというところでの、改善提案も含めてお願いしたいなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":229,"id":"exchange-081"}]},{"id":"topic-07","title":"平成２５年請願第１８号、「容器包装リサイクル法を改正し、発生抑制と再使用を促進するための法律の制定を求める意見書」の採択を求める請願","agenda":"平成２５年請願第１８号、「容器包装リサイクル法を改正し、発生抑制と再使用を促進するための法律の制定を求める意見書」の採択を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"請願要旨のところについて、ちょっと区の認識をお伺いしたいなと思います。環境によいリユース容器が激減しているということと、リサイクルに適さない容器包装がいまだに使われているのが社会の実態ですと書いてあるんですが、この辺の認識をお伺いしたいのが１点と、先ほどご説明の中で、自治体の負担が大きいと。ちょっとその大もとのところをお聞きしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"それから今期のものは、１２月までに各業界のヒアリングを五、六回やって、それからその役割分担も含めたところに検討の駒を進めていくというふうに聞いておりますので、その中で、そういった課題、役割分担といいますか。","voiceIndex":236,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"こういった意味で、自治体のコストもそうですけど、環境対策にもすごく役立つという意味では、リサイクル中心ではなくて大もとのところを減らしていくという意味では、とても、拡大した製造者の責任を追及していくというのは、拡大生産者責任を追及していくというのは、自治体にとってもすごく大事なことでもあるので、ぜひ力を入れていくべきだろうと思うんですが、その点はいかがでしょうか。","respondent":"小林品川区清掃事務所長","answer":"確かに、流通経路云々ということですが、考えようによりますと、売れないものはつくらない、売れるようにつくるというのが、事業者の基本的な、利益追求の基本ですので、それから言うと、それは全て事業者の責任なのかなというところから言うと、やはり消費者も含めて。","voiceIndex":238,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問","question":"地方自治体がどんどん意見を言っていくことだと私は思っているので、この意見書を出していくのもすごく大事だと思うのですが、とにかくごみ行政で、出たごみをどうするのかでは解決しないと思うんですね。そういった意味では本当に、拡大生産者責任を果たしていくということは自治体の共通の願いでもあると思うんですけれども、最後になりますけどいかがでしょうか。","respondent":"小林品川区清掃事務所長","answer":"その辺をもって、事業者にも協力・負担を求めていくと同時に、区も大切な仕事の一つとして、おっしゃるとおり、達成したものをとるだけではなくて、それをどういうふうに社会として活かしていくのか、適正排出していくのか、減量していくのかというところの意識。","voiceIndex":240,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を一つだけ。今のに関連。すみません。最後と言ったんですけれども。拡大生産者責任は、ごみ問題解決の切り札と言われているんですね。回転にとってもプラスになるし環境負荷も少ないと。それでごみが減っていくということなのでね。ぜひこの点を皆さんにもしっかり受けとめていただきたいなと思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問・要望","question":"非常に難しい判断を求められたと思っています。そういう可能性は当然あるわけであって。だけれども、ここで言っているのは、拡大生産者責任を盛り込むこととイコールだから、それだけで私たちは解決すると思っていないんだけれども、難しい言い方かもしれないけれども、この問題の解決といいましょうか、品川区が今現在考えているベストな解決方法はどうお考えなんでしょうか、お答えください。","respondent":"小林品川区清掃事務所長","answer":"この辺に、今ご質問いただきましたことの回答のヒントがあるように思います。つまり、一定の可能性を決めたら、それに対する準備期間を持って、そして、それに対する三者のそれぞれの合意形成の期間を持って、一歩前に踏み出していく。","voiceIndex":243,"id":"exchange-086"},{"speaker":"伊藤委員","kind":"質問","question":"まあそうですね。三者の合意形成。やっぱりやるとなれば、区に全体の制度があって、その中で、例えば飲料会社ですか、そういうところと、例えばこういうことを契約していくとか、そういうふうに話をやっぱり具体化していかないと、この話はどんなに地方自治体が頑張ったとしても、態度、出ないんじゃないでしょうか。ですから、たしかこれは平成２２年に同趣旨の請願を趣旨採択されたかと思います。","respondent":"小林品川区清掃事務所長","answer":"その辺の一つ一つの動きについては今後の検討を待ち、前回のときも、三つほど大きな、一つ一つは小さいけれど全体としては大きな合意形成をしてまいりましたし、今回も今、作業状態は、その課題の抽出を、前回、９月にはなさったというふうに会議録では読めましたので。","voiceIndex":245,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"この請願の請願事項ですね。では、物が、ペットボトル１００円、１５０円ですかね、としたときに、ではその維持をしていく。で、今度消費税も上がるという状況を踏まえた中で、誰が犠牲になるのかなと思うと、私はちょっと、もっと広い意味で考えていかないと、ただ単に拡大生産者責任だけで追及できるものではないだろうなと思うんですが、その辺はどういうふうに考えられていますでしょうか。","respondent":"小林品川区清掃事務所長","answer":"で、そこでほぼリサイクルの費用は一時的には賄っているというところまでは、既に事業者は拡大生産者責任を果たしておりますので、その後の費用案分の負担も含めて、どう今後、考えていくのかというのが、次期のテーマになってくるだろうと考えております。","voiceIndex":248,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"かなり今、拡大生産者責任も負っていただいているよという現状もある。で、消費税も上がっていく。一応、会派で議論されての紹介議員になっていると思うので、どういう観点でどこまでのものを意見書として提出すべきと思っているのか、ちょっと確認をさせていただきたいと思うんですけどいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"いや、それはわかるんです。だから、何ですかね、今、いろいろな問題点があって、行政側の立場も考え、品川区として意見書を出す上で、どういう観点を持って、考え方で、意見書を提出できるのかどうか。どういうふうに皆さん考えて、この紹介議員になられている会派の方々が紹介議員になっておられるのかというのをちょっとお聞きしたいのですけど、だめでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"で、次に、上から７行目の、約８割が製品価格に内部化されていないという云々。それと、その２行下の、負担のあり方について不公平感が高まっていますと。こういう事実が三つ並べてありますけれども、このことに関して行政側の考えなり、現状というか、これを教えていただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"この請願、余談なんですけれど、意見書ということでは、法律の背景、ご説明させていただきましたように、容器包装リサイクル法の条項改正をもって法律としてしようとしているのか、そうではなくて、性格が違うので、趣旨はわかっているけれど、委員長がおっしゃいましたように。","voiceIndex":254,"id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"この３Ｒというのはもともと、順位が違うというのは、多分、本来の目的というのは、物を減らす、ごみを減らすということではないかと思うんですよ。それで、リデュース、リユース、それからリサイクルですよね。そしてごみを減らすことによって、今の、何というんですか、環境ですか、そういうものを守っていく、維持していくということが目的だと思うんですけども、それはどうなんでしょうか。","respondent":"小林品川区清掃事務所長","answer":"おっしゃるとおりだと思います。","voiceIndex":256,"id":"exchange-092"},{"speaker":"木村委員","kind":"質問","question":"そういうことで、消費者が本当に不公平感を感じるというのは、消費者はそういう意味ではものすごく、このリサイクルに対してというか、分別とか、いろんなことに対して努力をしていただいているということを考えても、そしてまたこれが内部化されることによって料金が上がっていくと考えると、やはり一番損をするというのもおかしいですけども、消費者が一番損をするのではないかなと思っているんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-093"},{"speaker":"こんの副委員長","kind":"確認","question":"さまざまな質問が出ていましたので、１点だけ、ちょっと現状を確認というか、先ほどのご説明の中に、区長会でも、そういう関係のことが出されていたと。ここら辺の様子をちょっと、わかる範囲で、どんな形で議論があるいはされているか、少しわかる範囲でご答弁いただければと思うんですが、いかがでしょう。","respondent":"小林品川区清掃事務所長","answer":"この間、毎年、区長会が国に出していく要望事項をまとめていく時期があります。そのときに、既にもう数年にわたって、この役割分担のあり方、とりわけその役割分担の中を構成する費用分担のあり方についての検討を進めてくださいという意見を上げてまいりました。","voiceIndex":261,"id":"exchange-094"},{"speaker":"こんの副委員長","kind":"質問","question":"様子がよくわかりました。そういう様子とともに、本請願で出されている、あらゆる、ほかの議員の質問のご答弁も伺いながら、やはり一定の、区長会で出される、いわゆる自治体としてどうしていくかということの動きも見ますと、そこら辺の動きは一定の理解をするところであります。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-095"},{"speaker":"伊藤委員","kind":"意見","question":"本請願は、私どもも随分議論させていただきましたけれども、この請願が掲げているとおり動いていきますと、拡大生産者責任がことさら強調されている感じがします。これだけでは、私どもとしてはこの目的を達成することは難しいと判断しましたので、本請願については不採択として主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":273,"id":"exchange-096"},{"speaker":"こんの副委員長","kind":"意見","question":"私どもの会派としても、今回、この請願に対して、実は前回、平成２２年のときにもこのような内容のものが出される中で、また区長会での今のご答弁も見る中で、一定のこの取り組みということに対しては理解をするというところで、本請願に対しては採択をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":274,"id":"exchange-097"},{"speaker":"飯沼委員","kind":"提案","question":"採択を主張します。本請願は、リサイクルでよしではなくて、先に進めるための提案であると受けとめています。先日、ＣＯＰ１９でも、世界から日本のＣＯ２削減、反対に増えてしまうといったことで、世界から批判を受けているところで、やはり環境問題からしても、これは早急に取り組むべきことであるので、意見書を上げていくことという、大変重用なことであると思って、採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":277,"id":"exchange-098"},{"speaker":"西本委員","kind":"意見","question":"非常に難しいな、判断に難しいなと思っているところです。ただ、拡大生産者責任というところというのは、それだけではなくて、もっと、合意形成という話もありました。やっぱり、ちゃんと深いところでのメリット・デメリットも含めて、しっかりと見据えた形で意見等を出すべきではないだろうかというふうな意見を申し上げて、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":278,"id":"exchange-099"},{"speaker":"こんの副委員長","kind":"意見","question":"まあ、意見書が、出す、出さないという、それに対しての採択というふうには申し上げましたが、気持ちはよくわかりますし、議会として気持ちはわかり、そして一歩でも進めてもらいたいという、意見をまとめるということでは、趣旨というところでもあり得るのかなと思いますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":282,"id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この大きな趣旨は、国のところに意見を入れていくというところなので、ぜひ、まとめて、意見書を提出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問・要望","question":"たしか、後日確認していただきたいんですけれども、今までの議会の流れからすると、意見書を提出するに当たっては、全会派一致が望ましい形になっているはずですので、それはぜひ確認しておいてくださいということだけお話をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":291,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、できる限り、意見書を出すということであれば、全会派一致で出していくべきものだと私も思っていますので、やはり私たち、いろいろなことを考えて、今回はというふうにさせていただいた経緯もありますので、皆さん合意の中で出すんだったら出していただきたい。ただ、今の状況だと合意には至っていないというのが現状だと思いますので、そこを配慮していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-103"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":85718,"voices":298}}]);
